use serde::Serialize;
use std::collections::HashMap;

pub type RefMap = HashMap<String, String>;

pub fn slugify(text: &str) -> String {
    let mut out = String::new();
    let mut last_dash = true; // trims leading dashes via flag
    for c in text.to_lowercase().chars() {
        if c.is_alphanumeric() {
            out.push(c);
            last_dash = false;
        } else if c.is_whitespace() || c == '-' {
            if !last_dash && !out.is_empty() {
                out.push('-');
                last_dash = true;
            }
        }
    }
    while out.ends_with('-') { out.pop(); }
    out
}

#[derive(Debug, Clone, Serialize)]
#[serde(tag = "type")]
pub enum Inline {
    #[serde(rename = "text")]
    Text { value: String },
    #[serde(rename = "strong")]
    Strong { value: String },
    #[serde(rename = "emphasis")]
    Emphasis { value: String },
    #[serde(rename = "strikethrough")]
    Strikethrough { value: String },
    #[serde(rename = "code")]
    Code { value: String },
    #[serde(rename = "link")]
    Link { text: String, url: String, title: Option<String> },
    #[serde(rename = "image")]
    Image { alt: String, src: String, title: Option<String> },
}

impl Inline {
    pub fn value_text(&self) -> String {
        match self {
            Inline::Text { value } => value.clone(),
            Inline::Strong { value } => value.clone(),
            Inline::Emphasis { value } => value.clone(),
            Inline::Strikethrough { value } => value.clone(),
            Inline::Code { value } => value.clone(),
            Inline::Link { text, .. } => text.clone(),
            Inline::Image { alt, .. } => alt.clone(),
        }
    }
    pub fn title_text(&self) -> String {
        match self {
            Inline::Code { .. } => String::new(),
            other => other.value_text(),
        }
    }
    // representation used when building paragraph content
    pub fn content_repr(&self) -> String {
        match self {
            Inline::Link { text, url, .. } => format!("[{}]({})", text, url),
            Inline::Image { alt, src, .. } => format!("![{}]({})", alt, src),
            other => other.value_text(),
        }
    }
}

pub fn content_from_inline(inlines: &[Inline]) -> String {
    let mut out = String::new();
    for inl in inlines {
        if let Inline::Image { alt, src, .. } = inl {
            out = format!("![{}]({})", alt, src);
        } else {
            out.push_str(&inl.content_repr());
        }
    }
    out
}

pub fn plain_from_inline(inlines: &[Inline]) -> String {
    inlines.iter().map(|i| i.value_text()).collect()
}
pub fn title_from_inline(inlines: &[Inline]) -> String {
    inlines.iter().map(|i| i.title_text()).collect()
}

fn normalize_ref_label(label: &str) -> String {
    label.split_whitespace().collect::<Vec<_>>().join(" ").to_lowercase()
}

// A valid link-reference/footnote definition line; returns (label, url) if valid.
// destination is a single token or <...>; remainder must be a proper title if present.
pub fn parse_ref_definition(line: &str) -> Option<(String, String)> {
    let t = line.trim_end();
    let bytes = t.trim_start();
    let indent = line.len() - bytes.len();
    if indent > 3 { return None; }
    if !bytes.starts_with('[') { return None; }
    let close = bytes.find(']')?;
    if close == 1 { /* empty label? still } */ }
    let label = &bytes[1..close];
    let rest = bytes[close + 1..].strip_prefix(':')?;
    let rest = rest.trim_start();
    if rest.is_empty() { return None; }
    let (dest, remainder) = if rest.starts_with('<') {
        let end = rest.find('>')?;
        (rest[1..end].to_string(), rest[end + 1..].trim())
    } else {
        // destination is first whitespace-free token (may contain balanced parens; good enough)
        let end = rest.find(|c: char| c.is_whitespace()).unwrap_or(rest.len());
        (rest[..end].to_string(), rest[end..].trim())
    };
    if dest.is_empty() { return None; }
    if !remainder.is_empty() {
        let ok = (remainder.starts_with('"') && remainder.ends_with('"') && remainder.len() >= 2)
            || (remainder.starts_with('\'') && remainder.ends_with('\'') && remainder.len() >= 2)
            || (remainder.starts_with('(') && remainder.ends_with(')') && remainder.len() >= 2);
        if !ok { return None; }
    }
    Some((normalize_ref_label(label), dest))
}

pub fn collect_refs(text: &str) -> RefMap {
    let mut map = RefMap::new();
    let mut in_fence = false;
    let mut fence_char = '`';
    let mut fence_len = 0usize;
    for line in text.lines() {
        let trimmed = line.trim_start();
        // fence tracking (rough)
        let fc = trimmed.chars().next().unwrap_or(' ');
        if (fc == '`' || fc == '~') && trimmed.chars().take_while(|&c| c == fc).count() >= 3 {
            let len = trimmed.chars().take_while(|&c| c == fc).count();
            if !in_fence { in_fence = true; fence_char = fc; fence_len = len; }
            else if fc == fence_char && len >= fence_len { in_fence = false; }
            continue;
        }
        if in_fence { continue; }
        if let Some((label, url)) = parse_ref_definition(line) {
            map.entry(label).or_insert(url);
        }
    }
    map
}

struct InlineScanner {
    chars: Vec<char>,
    pos: usize,
    refs: RefMap,
    strong: bool,
    emph: bool,
    strike: bool,
}

impl InlineScanner {
    fn peek_run(&self) -> (char, usize) {
        if self.pos >= self.chars.len() { return ('\0', 0); }
        let c = self.chars[self.pos];
        let mut n = 0;
        while self.pos + n < self.chars.len() && self.chars[self.pos + n] == c { n += 1; }
        (c, n)
    }
    fn cur_str(&self, len: usize) -> String { self.chars[self.pos..(self.pos + len).min(self.chars.len())].iter().collect() }
    fn node_for(&self, value: String) -> Inline {
        if self.strong { Inline::Strong { value } }
        else if self.emph { Inline::Emphasis { value } }
        else if self.strike { Inline::Strikethrough { value } }
        else { Inline::Text { value } }
    }
    fn flush(&self, buf: &mut String, nodes: &mut Vec<Inline>) {
        if !buf.is_empty() {
            let v = std::mem::take(buf);
            nodes.push(self.node_for(v));
        }
    }
    fn find_closing_run(&self, start: usize, ch: char, min_len: usize) -> bool {
        let mut i = start;
        while i < self.chars.len() {
            if self.chars[i] == ch {
                let mut n = 0;
                while i + n < self.chars.len() && self.chars[i + n] == ch { n += 1; }
                if n >= min_len {
                    // can close: previous char not whitespace
                    if i > 0 && !self.chars[i - 1].is_whitespace() { return true; }
                }
                i += n;
            } else { i += 1; }
        }
        false
    }
    fn can_open(&self, run_len: usize) -> bool {
        let next_idx = self.pos + run_len;
        next_idx < self.chars.len() && !self.chars[next_idx].is_whitespace()
    }
    fn can_close(&self) -> bool {
        self.pos > 0 && !self.chars[self.pos - 1].is_whitespace()
    }
}

fn entity_decode(name: &str) -> Option<String> {
    if let Some(hex) = name.strip_prefix("#x").or_else(|| name.strip_prefix("#X")) {
        u32::from_str_radix(hex, 16).ok().and_then(char::from_u32).map(|c| c.to_string())
    } else if let Some(dec) = name.strip_prefix('#') {
        dec.parse::<u32>().ok().and_then(char::from_u32).map(|c| c.to_string())
    } else {
        let v = match name {
            "amp" => "&", "lt" => "<", "gt" => ">", "quot" => "\"", "apos" => "'",
            "copy" => "\u{00a9}", "reg" => "\u{00ae}", "trade" => "\u{2122}", "hellip" => "\u{2026}",
            "mdash" => "\u{2014}", "ndash" => "\u{2013}", "lsquo" => "\u{2018}", "rsquo" => "\u{2019}",
            "ldquo" => "\u{201c}", "rdquo" => "\u{201d}", "laquo" => "\u{00ab}", "raquo" => "\u{00bb}",
            "nbsp" => "\u{00a0}", "eacute" => "\u{00e9}", "egrave" => "\u{00e8}", "agrave" => "\u{00e0}",
            "ccedil" => "\u{00e7}", "deg" => "\u{00b0}", "plusmn" => "\u{00b1}", "times" => "\u{00d7}",
            "divide" => "\u{00f7}", "minus" => "\u{2212}", "infin" => "\u{221e}", "ne" => "\u{2260}",
            "le" => "\u{2264}", "ge" => "\u{2265}", "rarr" => "\u{2192}", "larr" => "\u{2190}",
            "harr" => "\u{2194}", "uarr" => "\u{2191}", "darr" => "\u{2193}", "bull" => "\u{2022}",
            "middot" => "\u{00b7}", "sect" => "\u{00a7}", "para" => "\u{00b6}", "deg_" => "\u{00b0}",
            _ => return None,
        };
        Some(v.to_string())
    }
}

// find matching closing bracket starting at index of '[' (in chars), returns index of ']'
fn find_bracket_close(chars: &[char], start: usize) -> Option<usize> {
    let mut depth = 0usize;
    let mut i = start;
    while i < chars.len() {
        match chars[i] {
            '\\' => { i += 2; continue; }
            '[' => depth += 1,
            ']' => { depth -= 1; if depth == 0 { return Some(i); } }
            _ => {}
        }
        i += 1;
    }
    None
}
fn find_paren_close(chars: &[char], start: usize) -> Option<usize> {
    let mut depth = 0usize;
    let mut i = start;
    while i < chars.len() {
        match chars[i] {
            '\\' => { i += 2; continue; }
            '(' => depth += 1,
            ')' => { depth -= 1; if depth == 0 { return Some(i); } }
            _ => {}
        }
        i += 1;
    }
    None
}

pub fn parse_inline(text: &str, refs: &RefMap) -> Vec<Inline> {
    let mut scanner = InlineScanner {
        chars: text.chars().collect(),
        pos: 0,
        refs: refs.clone(),
        strong: false, emph: false, strike: false,
    };
    let mut nodes = Vec::new();
    let mut buf = String::new();
    while scanner.pos < scanner.chars.len() {
        let c = scanner.chars[scanner.pos];
        // code span
        if c == '`' {
            let (_, run) = scanner.peek_run();
            // find closing run of same length
            let mut found: Option<usize> = None;
            let mut i = scanner.pos + run;
            while i < scanner.chars.len() {
                if scanner.chars[i] == '`' {
                    let mut n = 0;
                    while i + n < scanner.chars.len() && scanner.chars[i + n] == '`' { n += 1; }
                    if n == run { found = Some(i); break; }
                    i += n;
                } else { i += 1; }
            }
            if let Some(close) = found {
                scanner.flush(&mut buf, &mut nodes);
                let mut content: String = scanner.chars[scanner.pos + run..close].iter().collect();
                content = content.replace('\n', " ");
                if content.len() >= 2 && content.starts_with(' ') && content.ends_with(' ') && content.trim() != "" {
                    content = content[1..content.len() - 1].to_string();
                }
                nodes.push(Inline::Code { value: content });
                scanner.pos = close + run;
                continue;
            } else {
                buf.push_str(&scanner.cur_str(run));
                scanner.pos += run;
                continue;
            }
        }
        // escape
        if c == '\\' && scanner.pos + 1 < scanner.chars.len() && scanner.chars[scanner.pos + 1].is_ascii_punctuation() {
            buf.push(scanner.chars[scanner.pos + 1]);
            scanner.pos += 2;
            continue;
        }
        // image / link
        let is_image = c == '!' && scanner.pos + 1 < scanner.chars.len() && scanner.chars[scanner.pos + 1] == '[';
        if is_image || c == '[' {
            let bracket_start = if is_image { scanner.pos + 1 } else { scanner.pos };
            if let Some(close) = find_bracket_close(&scanner.chars, bracket_start) {
                let inner: String = scanner.chars[bracket_start + 1..close].iter().collect();
                let mut after = close + 1;
                let mut dest: Option<String> = None;
                let mut is_link_attempt = false;
                if after < scanner.chars.len() && scanner.chars[after] == '(' {
                    if let Some(pclose) = find_paren_close(&scanner.chars, after) {
                        let inside: String = scanner.chars[after + 1..pclose].iter().collect();
                        let inside_t = inside.trim();
                        let d = if inside_t.starts_with('<') {
                            if let Some(gt) = inside_t.find('>') { inside_t[1..gt].to_string() } else { inside_t.to_string() }
                        } else { inside_t.to_string() };
                        dest = Some(d);
                        after = pclose + 1;
                        is_link_attempt = true;
                    }
                } else if after < scanner.chars.len() && scanner.chars[after] == '[' {
                    if let Some(close2) = find_bracket_close(&scanner.chars, after) {
                        let label_raw: String = scanner.chars[after + 1..close2].iter().collect();
                        let label = if label_raw.trim().is_empty() { inner.clone() } else { label_raw };
                        if let Some(url) = scanner.refs.get(&normalize_ref_label(&label)) {
                            dest = Some(url.clone());
                        }
                        after = close2 + 1;
                        is_link_attempt = true;
                    }
                } else {
                    // shortcut reference
                    if let Some(url) = scanner.refs.get(&normalize_ref_label(&inner)) {
                        dest = Some(url.clone());
                        is_link_attempt = true;
                    }
                }
                if let Some(url) = dest {
                    let inner_nodes = parse_inline(&inner, &scanner.refs);
                    let has_link = inner_nodes.iter().any(|n| matches!(n, Inline::Link { .. }));
                    if has_link && !is_image {
                        // not a link; emit '[' as separate text and rescan
                        scanner.flush(&mut buf, &mut nodes);
                        if is_image { nodes.push(scanner.node_for("!".to_string())); }
                        nodes.push(Inline::Text { value: "[".to_string() });
                        if is_image { /* shouldn't happen */ }
                        scanner.pos = bracket_start + 1;
                        continue;
                    }
                    scanner.flush(&mut buf, &mut nodes);
                    let plain = plain_from_inline(&inner_nodes);
                    if is_image {
                        nodes.push(Inline::Image { alt: plain, src: url, title: None });
                    } else {
                        nodes.push(Inline::Link { text: plain, url, title: None });
                    }
                    scanner.pos = after;
                    continue;
                } else if is_link_attempt {
                    // had ( or [ but reference missing: treat '[' as separate text node
                    scanner.flush(&mut buf, &mut nodes);
                    if is_image { buf.push('!'); scanner.flush(&mut buf, &mut nodes); }
                    nodes.push(Inline::Text { value: "[".to_string() });
                    scanner.pos = bracket_start + 1;
                    continue;
                } else {
                    // plain bracketed text; emit '[' as separate node and move on
                    scanner.flush(&mut buf, &mut nodes);
                    if is_image { buf.push('!'); }
                    // For image-like ![...] with no dest, fall through as text
                    if is_image {
                        buf.push('[');
                        scanner.pos = bracket_start + 1;
                        continue;
                    } else {
                        nodes.push(Inline::Text { value: "[".to_string() });
                        scanner.pos = bracket_start + 1;
                        continue;
                    }
                }
            } else {
                buf.push(c);
                scanner.pos += 1;
                continue;
            }
        }
        if c == ']' {
            scanner.flush(&mut buf, &mut nodes);
            nodes.push(Inline::Text { value: "]".to_string() });
            scanner.pos += 1;
            continue;
        }
        // autolink / html tag
        if c == '<' {
            // find '>'
            let mut gt: Option<usize> = None;
            let mut i = scanner.pos + 1;
            while i < scanner.chars.len() && i < scanner.pos + 200 {
                if scanner.chars[i] == '>' { gt = Some(i); break; }
                if scanner.chars[i] == '<' { break; }
                i += 1;
            }
            if let Some(gt) = gt {
                let inner: String = scanner.chars[scanner.pos + 1..gt].iter().collect();
                let inner_t = inner.trim();
                let is_autolink = {
                    let scheme_ok = {
                        let parts: Vec<&str> = inner_t.splitn(2, ':').collect();
                        parts.len() == 2 && parts[0].len() >= 2 && parts[0].chars().next().map(|ch| ch.is_ascii_alphabetic()).unwrap_or(false)
                            && parts[0].chars().all(|ch| ch.is_ascii_alphanumeric() || matches!(ch, '+' | '-' | '.'))
                            && !inner_t.contains(char::is_whitespace)
                    };
                    let email_ok = inner_t.contains('@') && !inner_t.contains(char::is_whitespace) && inner_t.contains('.');
                    scheme_ok || email_ok
                };
                if is_autolink {
                    scanner.flush(&mut buf, &mut nodes);
                    nodes.push(Inline::Link { text: inner_t.to_string(), url: inner_t.to_string(), title: None });
                    scanner.pos = gt + 1;
                    continue;
                } else if inner_t.starts_with(|ch: char| ch.is_ascii_alphabetic()) || inner_t.starts_with('/') || inner_t.starts_with('!') || inner_t.starts_with('?') {
                    // html tag: split text
                    scanner.flush(&mut buf, &mut nodes);
                    scanner.pos = gt + 1;
                    continue;
                }
            }
            buf.push(c);
            scanner.pos += 1;
            continue;
        }
        // entity
        if c == '&' {
            // try to match &...;
            let mut semi: Option<usize> = None;
            let mut i = scanner.pos + 1;
            while i < scanner.chars.len() && i < scanner.pos + 34 {
                if scanner.chars[i] == ';' { semi = Some(i); break; }
                if !(scanner.chars[i].is_ascii_alphanumeric() || scanner.chars[i] == '#') { break; }
                i += 1;
            }
            if let Some(semi) = semi {
                let name: String = scanner.chars[scanner.pos + 1..semi].iter().collect();
                if let Some(decoded) = entity_decode(&name) {
                    scanner.flush(&mut buf, &mut nodes);
                    // node type honours current style but entity standalone is text
                    nodes.push(scanner.node_for(decoded));
                    scanner.pos = semi + 1;
                    continue;
                }
            }
            buf.push(c);
            scanner.pos += 1;
            continue;
        }
        // strikethrough / emphasis delimiters
        if (c == '*' || c == '_') {
            let (_, run) = scanner.peek_run();
            // intraword underscore: literal
            if c == '_' {
                let prev_alnum = scanner.pos > 0 && (scanner.chars[scanner.pos - 1].is_alphanumeric() || scanner.chars[scanner.pos - 1] == '_');
                let next_idx = scanner.pos + run;
                let next_alnum = next_idx < scanner.chars.len() && (scanner.chars[next_idx].is_alphanumeric() || scanner.chars[next_idx] == '_');
                if prev_alnum && next_alnum {
                    buf.push_str(&scanner.cur_str(run));
                    scanner.pos += run;
                    continue;
                }
            }
            // decide handling based on run length
            if run >= 3 {
                // *** toggles both
                let want_strong_close = scanner.strong;
                if (scanner.strong || scanner.emph) && scanner.can_close() {
                    scanner.flush(&mut buf, &mut nodes);
                    scanner.strong = false; scanner.emph = false;
                    scanner.pos += 3;
                    continue;
                } else if scanner.can_open(3) && scanner.find_closing_run(scanner.pos + 3, c, 3) {
                    scanner.flush(&mut buf, &mut nodes);
                    scanner.strong = true; scanner.emph = true;
                    let _ = want_strong_close;
                    scanner.pos += 3;
                    continue;
                } else {
                    buf.push_str(&scanner.cur_str(run));
                    scanner.pos += run;
                    continue;
                }
            } else if run == 2 {
                if scanner.strong && scanner.can_close() {
                    scanner.flush(&mut buf, &mut nodes);
                    scanner.strong = false;
                    scanner.pos += 2;
                    continue;
                } else if !scanner.strong && scanner.can_open(2) && scanner.find_closing_run(scanner.pos + 2, c, 2) {
                    scanner.flush(&mut buf, &mut nodes);
                    scanner.strong = true;
                    scanner.pos += 2;
                    continue;
                } else {
                    buf.push_str(&scanner.cur_str(run));
                    scanner.pos += run;
                    continue;
                }
            } else {
                // single
                if scanner.emph && scanner.can_close() {
                    // ensure this isn't start of a ** pair handled above (run==1 so no)
                    scanner.flush(&mut buf, &mut nodes);
                    scanner.emph = false;
                    scanner.pos += 1;
                    continue;
                } else if !scanner.emph && scanner.can_open(1) && scanner.find_closing_run(scanner.pos + 1, c, 1) {
                    scanner.flush(&mut buf, &mut nodes);
                    scanner.emph = true;
                    scanner.pos += 1;
                    continue;
                } else {
                    buf.push(c);
                    scanner.pos += 1;
                    continue;
                }
            }
        }
        if c == '~' {
            let (_, run) = scanner.peek_run();
            if run >= 2 {
                if scanner.strike && scanner.can_close() {
                    scanner.flush(&mut buf, &mut nodes);
                    scanner.strike = false;
                    scanner.pos += 2;
                    continue;
                } else if !scanner.strike && scanner.can_open(2) && scanner.find_closing_run(scanner.pos + 2, '~', 2) {
                    scanner.flush(&mut buf, &mut nodes);
                    scanner.strike = true;
                    scanner.pos += 2;
                    continue;
                } else {
                    buf.push_str(&scanner.cur_str(run));
                    scanner.pos += run;
                    continue;
                }
            } else {
                buf.push(c);
                scanner.pos += 1;
                continue;
            }
        }
        buf.push(c);
        scanner.pos += 1;
    }
    scanner.flush(&mut buf, &mut nodes);
    nodes
}

#[derive(Debug, Clone, Serialize)]
#[serde(tag = "type")]
pub enum Block {
    #[serde(rename = "paragraph")]
    Paragraph { content: String, inline: Vec<Inline> },
    #[serde(rename = "heading")]
    Heading { level: u8, content: String, inline: Vec<Inline>, anchor: String },
    #[serde(rename = "code")]
    Code { language: Option<String>, content: String, start_line: usize, end_line: usize },
    #[serde(rename = "list")]
    List { ordered: bool, items: Vec<ListItem> },
    #[serde(rename = "table")]
    Table { headers: Vec<String>, alignments: Vec<String>, rows: Vec<Vec<String>> },
    #[serde(rename = "blockquote")]
    Blockquote { content: String, blocks: Vec<Block> },
    #[serde(rename = "horizontalrule")]
    HorizontalRule,
}

#[derive(Debug, Clone, Serialize)]
pub struct ListItem {
    pub checked: Option<bool>,
    pub content: String,
    pub inline: Vec<Inline>,
    #[serde(skip_serializing_if = "Vec::is_empty")]
    pub blocks: Vec<Block>,
}

#[derive(Debug, Clone, Serialize)]
pub struct SectionContent {
    pub raw: String,
    pub blocks: Vec<Block>,
}

#[derive(Debug, Clone, Serialize)]
pub struct Position {
    pub line: usize,
    pub offset: usize,
}

#[derive(Debug, Clone, Serialize)]
pub struct Section {
    pub id: String,
    pub level: u8,
    pub title: String,
    pub slug: String,
    pub position: Position,
    pub content: SectionContent,
    pub children: Vec<Section>,
    #[serde(skip)]
    pub line_idx: usize,
    #[serde(skip)]
    pub heading_start_byte: usize,
    #[serde(skip)]
    pub content_start_byte: usize,
    #[serde(skip)]
    pub title_inline: Vec<Inline>,
}

#[derive(Debug, Clone, Serialize)]
pub struct Metadata {
    pub source: Option<String>,
    #[serde(rename = "headingCount")]
    pub heading_count: usize,
    #[serde(rename = "maxDepth")]
    pub max_depth: usize,
    #[serde(rename = "wordCount")]
    pub word_count: usize,
}

#[derive(Debug, Clone, Serialize)]
pub struct DocumentData {
    pub metadata: Metadata,
    pub sections: Vec<Section>,
}

#[derive(Debug, Clone)]
pub struct Document {
    pub content: String, // processed content
    pub sections: Vec<Section>, // tree
    pub flat: Vec<Section>, // flat clones (children empty; content same) in doc order
    pub word_count: usize,
    pub heading_count: usize,
    pub max_depth: usize,
}

impl Document {
    pub fn data(&self) -> DocumentData {
        DocumentData {
            metadata: Metadata {
                source: None,
                heading_count: self.heading_count,
                max_depth: self.max_depth,
                word_count: self.word_count,
            },
            sections: self.sections.clone(),
        }
    }
    pub fn flat_sections(&self) -> Vec<Section> {
        fn walk(s: &Section, out: &mut Vec<Section>) {
            let mut c = s.clone();
            c.children = Vec::new();
            out.push(c);
            for ch in &s.children { walk(ch, out); }
        }
        let mut out = Vec::new();
        for s in &self.sections { walk(s, &mut out); }
        // NOTE: flat derived from tree order equals doc order
        out
    }
}

fn is_fence_start(line: &str) -> Option<(char, usize, String)> {
    let indent = line.chars().take_while(|&c| c == ' ').count();
    if indent > 3 { return None; }
    let t = &line[indent..];
    let fc = t.chars().next()?;
    if fc != '`' && fc != '~' { return None; }
    let count = t.chars().take_while(|&c| c == fc).count();
    if count < 3 { return None; }
    let info = t[count..].trim().to_string();
    if fc == '`' && info.contains('`') { return None; }
    Some((fc, count, info))
}

fn split_table_cells(line: &str) -> Vec<String> {
    let mut cells = Vec::new();
    let mut cur = String::new();
    let chars: Vec<char> = line.chars().collect();
    let mut i = 0;
    let mut in_code: Option<usize> = None;
    while i < chars.len() {
        let c = chars[i];
        if c == '\\' && i + 1 < chars.len() && chars[i + 1] == '|' {
            cur.push('|');
            i += 2;
            continue;
        }
        if c == '`' {
            let mut n = 0;
            while i + n < chars.len() && chars[i + n] == '`' { n += 1; }
            match in_code {
                Some(m) if m == n => in_code = None,
                None => in_code = Some(n),
                _ => {}
            }
            cur.push_str(&"`".repeat(n));
            i += n;
            continue;
        }
        if c == '|' && in_code.is_none() {
            cells.push(cur.trim().to_string());
            cur = String::new();
            i += 1;
            continue;
        }
        cur.push(c);
        i += 1;
    }
    cells.push(cur.trim().to_string());
    // drop leading/trailing empty caused by outer pipes
    let trimmed = line.trim();
    if trimmed.starts_with('|') && !cells.is_empty() { cells.remove(0); }
    if trimmed.ends_with('|') && !trimmed.ends_with("\\|") && !cells.is_empty() { cells.pop(); }
    cells
}

fn is_table_delimiter(line: &str) -> Option<Vec<String>> {
    if !line.contains('-') { return None; }
    let cells = split_table_cells(line);
    if cells.is_empty() { return None; }
    let mut aligns = Vec::new();
    for c in &cells {
        let c = c.trim();
        if c.is_empty() { return None; }
        let left = c.starts_with(':');
        let right = c.ends_with(':');
        let core = c.trim_matches(':');
        if core.is_empty() || !core.chars().all(|ch| ch == '-') { return None; }
        aligns.push(match (left, right) {
            (true, true) => "center",
            (false, true) => "right",
            (true, false) => "left",
            _ => "none",
        }.to_string());
    }
    Some(aligns)
}

fn atx_parse(line: &str) -> Option<(u8, String, usize)> {
    // returns (level, raw_inner, indent_chars)
    let mut indent = 0usize;
    let chars: Vec<char> = line.chars().collect();
    while indent < chars.len() && chars[indent] == ' ' { indent += 1; }
    if indent > 3 { return None; }
    let mut i = indent;
    let mut hashes = 0usize;
    while i < chars.len() && chars[i] == '#' { hashes += 1; i += 1; }
    if hashes == 0 || hashes > 6 { return None; }
    if i < chars.len() && chars[i] != ' ' && chars[i] != '\t' { return None; }
    while i < chars.len() && (chars[i] == ' ' || chars[i] == '\t') { i += 1; }
    let mut inner: String = chars[i..].iter().collect();
    // closing sequence
    let trimmed_end = inner.trim_end().to_string();
    inner = trimmed_end;
    if !inner.is_empty() && inner.chars().all(|c| c == '#') {
        inner = String::new();
    } else {
        // trailing hashes preceded by whitespace
        let mut end = inner.len();
        let bytes = inner.as_bytes();
        let mut j = end;
        while j > 0 && bytes[j - 1] == b'#' { j -= 1; }
        if j < end && j > 0 && (bytes[j - 1] == b' ' || bytes[j - 1] == b'\t') {
            inner = inner[..j].trim_end().to_string();
        }
        let _ = end;
    }
    Some((hashes as u8, inner, indent))
}

fn is_hr(line: &str) -> bool {
    let indent = line.chars().take_while(|&c| c == ' ').count();
    if indent > 3 { return false; }
    let t = line.trim();
    let chars: Vec<char> = t.chars().filter(|c| !c.is_whitespace()).collect();
    if chars.len() < 3 { return false; }
    let c = chars[0];
    (c == '-' || c == '*' || c == '_') && chars.iter().all(|&ch| ch == c)
}
fn setext_level(line: &str) -> Option<u8> {
    let indent = line.chars().take_while(|&c| c == ' ').count();
    if indent > 3 { return None; }
    let t = line.trim();
    if t.is_empty() { return None; }
    if t.chars().all(|c| c == '=') { Some(1) }
    else if t.chars().all(|c| c == '-') { Some(2) }
    else { None }
}

struct ListMarker {
    indent: usize,
    ordered: bool,
    marker_char: char, // bullet char or delimiter '.' / ')'
    content_col: usize,
    content: String,
}

fn parse_list_marker(line: &str) -> Option<ListMarker> {
    let chars: Vec<char> = line.chars().collect();
    let mut indent = 0usize;
    while indent < chars.len() && chars[indent] == ' ' { indent += 1; }
    if indent > 3 { return None; }
    if indent >= chars.len() { return None; }
    let c = chars[indent];
    if c == '-' || c == '+' || c == '*' {
        let after = indent + 1;
        if after < chars.len() && chars[after] != ' ' && chars[after] != '\t' { return None; }
        let mut j = after;
        while j < chars.len() && (chars[j] == ' ' || chars[j] == '\t') { j += 1; }
        let spaces = j - after;
        let content_col = if spaces > 4 || after == chars.len() { after + 1 } else { j };
        // content_col counts chars; lines are mostly ascii here
        let content: String = if j <= chars.len() { chars[j..].iter().collect() } else { String::new() };
        return Some(ListMarker { indent, ordered: false, marker_char: c, content_col: if content_col > line.len() { line.len() } else { content_col }, content });
    }
    if c.is_ascii_digit() {
        let mut j = indent;
        let mut digits = 0;
        while j < chars.len() && chars[j].is_ascii_digit() { j += 1; digits += 1; }
        if digits == 0 || digits > 9 { return None; }
        if j >= chars.len() || (chars[j] != '.' && chars[j] != ')') { return None; }
        let delim = chars[j];
        let after = j + 1;
        if after < chars.len() && chars[after] != ' ' && chars[after] != '\t' { return None; }
        let mut k = after;
        while k < chars.len() && (chars[k] == ' ' || chars[k] == '\t') { k += 1; }
        let spaces = k - after;
        let content_col = if spaces > 4 || after == chars.len() { after + 1 } else { k };
        let content: String = chars[k..].iter().collect();
        return Some(ListMarker { indent, ordered: true, marker_char: delim, content_col, content });
    }
    None
}

fn strip_task(content: &str) -> (Option<bool>, String) {
    let t = content;
    for (pat, val) in [("[ ]", Some(false)), ("[x]", Some(true)), ("[X]", Some(true))] {
        if let Some(rest) = t.strip_prefix(pat) {
            if rest.is_empty() || rest.starts_with(' ') || rest.starts_with('\t') {
                return (val, rest.trim_start().to_string());
            }
        }
    }
    (None, t.to_string())
}

pub fn parse_blocks(raw: &str, section_line: usize) -> Vec<Block> {
    let refs = collect_refs(raw);
    parse_blocks_with_refs(raw, section_line, &refs, 0)
}

fn parse_blocks_with_refs(raw: &str, section_line: usize, refs: &RefMap, depth: usize) -> Vec<Block> {
    let lines: Vec<&str> = raw.lines().collect();
    let mut blocks: Vec<Block> = Vec::new();
    let mut i = 0usize;
    while i < lines.len() {
        let line = lines[i];
        let trimmed = line.trim();
        if trimmed.is_empty() { i += 1; continue; }
        // reference definition lines are consumed
        if parse_ref_definition(line).is_some() { i += 1; continue; }
        // fenced code
        if let Some((fc, flen, info)) = is_fence_start(line) {
            let lang = info.split_whitespace().next().map(|s| s.to_string());
            let mut content_lines: Vec<&str> = Vec::new();
            i += 1;
            while i < lines.len() {
                let l = lines[i];
                let indent = l.chars().take_while(|&c| c == ' ').count();
                if indent <= 3 {
                    let t = l.trim_start();
                    let run = t.chars().take_while(|&c| c == fc).count();
                    if run >= flen && t[run..].trim().is_empty() { i += 1; break; }
                }
                content_lines.push(l);
                i += 1;
            }
            blocks.push(Block::Code { language: lang.filter(|s| !s.is_empty()), content: content_lines.join("\n"), start_line: section_line, end_line: section_line });
            continue;
        }
        // ATX heading block
        if let Some((level, inner, _)) = atx_parse(line) {
            let inline = parse_inline(&inner, refs);
            let content = title_from_inline(&inline);
            let anchor = slugify(&content);
            blocks.push(Block::Heading { level, content, inline, anchor });
            i += 1;
            continue;
        }
        // html block
        if is_html_block_start(line) {
            while i < lines.len() && !lines[i].trim().is_empty() { i += 1; }
            continue;
        }
        // blockquote
        if is_blockquote_start(line) {
            let (bqs, ni) = parse_blockquote_group(&lines, i, section_line, refs, depth);
            blocks.extend(bqs);
            i = ni;
            continue;
        }
        // table
        if i + 1 < lines.len() {
            if let Some(aligns) = is_table_delimiter(lines[i + 1]) {
                if line.contains('|') {
                    let headers_raw = split_table_cells(line);
                    let ncol = aligns.len();
                    let mut headers: Vec<String> = headers_raw.iter().map(|c| content_from_inline(&parse_inline(c, refs))).collect();
                    headers.resize(ncol, String::new());
                    headers.truncate(ncol);
                    let mut rows: Vec<Vec<String>> = Vec::new();
                    i += 2;
                    while i < lines.len() && !lines[i].trim().is_empty() && lines[i].contains('|') {
                        // stop if this line starts another obvious block? tables gobble
                        let mut row: Vec<String> = split_table_cells(lines[i]).iter().map(|c| content_from_inline(&parse_inline(c, refs))).collect();
                        row.resize(ncol, String::new());
                        row.truncate(ncol);
                        rows.push(row);
                        i += 1;
                    }
                    blocks.push(Block::Table { headers, alignments: aligns, rows });
                    continue;
                }
            }
        }
        // list
        if parse_list_marker(line).is_some() {
            let (block, ni) = parse_list(&lines, i, section_line, refs, depth);
            blocks.push(block);
            i = ni;
            continue;
        }
        // thematic break
        if is_hr(line) {
            blocks.push(Block::HorizontalRule);
            i += 1;
            continue;
        }
        // paragraph (with setext conversion)
        let mut para_lines: Vec<&str> = Vec::new();
        let mut heading_block: Option<Block> = None;
        while i < lines.len() {
            let l = lines[i];
            if l.trim().is_empty() { break; }
            if !para_lines.is_empty() {
                if let Some(level) = setext_level(l) {
                    // convert paragraph to heading block
                    let mut all_inline: Vec<Inline> = Vec::new();
                    for pl in &para_lines { all_inline.extend(parse_inline(pl.trim(), refs)); }
                    let content = title_from_inline(&all_inline);
                    let anchor = slugify(&content);
                    heading_block = Some(Block::Heading { level, content, inline: all_inline, anchor });
                    i += 1; // consume underline
                    break;
                }
                if parse_ref_definition(l).is_some() { i += 1; continue; }
                // interrupters
                if is_fence_start(l).is_some() || atx_parse(l).is_some() || is_blockquote_start(l) || is_hr(l) {
                    break;
                }
                if parse_list_marker(l).is_some() { break; }
                if i + 1 < lines.len() && l.contains('|') && is_table_delimiter(lines[i + 1]).is_some() { break; }
            }
            para_lines.push(l);
            i += 1;
        }
        if let Some(hb) = heading_block {
            blocks.push(hb);
        } else if !para_lines.is_empty() {
            // build paragraph inline across lines
            let mut inline: Vec<Inline> = Vec::new();
            for (idx, pl) in para_lines.iter().enumerate() {
                let is_last = idx + 1 == para_lines.len();
                let (line_text, hard) = if !is_last {
                    let t = *pl;
                    if t.ends_with("  ") || t.ends_with('\\') {
                        (t.trim_end_matches('\\').trim_end().to_string(), true)
                    } else { (t.to_string(), false) }
                } else { (pl.to_string(), false) };
                let line_inline = parse_inline(line_text.trim_end(), refs);
                inline.extend(line_inline);
                if !is_last {
                    inline.push(Inline::Text { value: if hard { "\n".to_string() } else { " ".to_string() } });
                }
            }
            let content = content_from_inline(&inline);
            blocks.push(Block::Paragraph { content, inline });
        }
    }
    blocks
}

fn is_html_block_start(line: &str) -> bool {
    let t = line.trim_start();
    let indent = line.len() - t.len();
    if indent > 3 { return false; }
    if t.starts_with("<!--") || t.starts_with("<?") || t.starts_with("<![CDATA[") { return true; }
    if t.starts_with("<!") && t.chars().nth(2).map(|c| c.is_ascii_alphabetic()).unwrap_or(false) { return true; }
    // opening/closing tag with a block-level name
    let inner = if let Some(rest) = t.strip_prefix('<') { rest } else if let Some(rest) = t.strip_prefix("</") { rest } else { return false; };
    let name: String = inner.chars().take_while(|c| c.is_ascii_alphanumeric() || *c == '-').collect::<String>().to_lowercase();
    if name.is_empty() { return false; }
    const TAGS: &[&str] = &["address","article","aside","base","basefont","blockquote","body","caption","center","col","colgroup","dd","details","dialog","dir","div","dl","dt","fieldset","figcaption","figure","footer","form","frame","frameset","h1","h2","h3","h4","h5","h6","head","header","hr","html","iframe","legend","li","link","main","menu","menuitem","nav","noframes","ol","optgroup","option","p","param","section","source","summary","table","tbody","td","tfoot","th","thead","title","tr","track","ul","script","style","pre","textarea"];
    if TAGS.contains(&name.as_str()) {
        let after = inner[name.len()..].chars().next();
        match after { None => true, Some(c) => c.is_whitespace() || c == '>' || c == '/', }
    } else { false }
}

fn is_blockquote_start(line: &str) -> bool {
    let indent = line.chars().take_while(|&c| c == ' ').count();
    if indent > 3 { return false; }
    line[indent..].starts_with('>')
}
fn strip_blockquote_marker(line: &str) -> String {
    let indent = line.chars().take_while(|&c| c == ' ').count();
    let t = &line[indent..];
    if let Some(rest) = t.strip_prefix('>') {
        if let Some(r2) = rest.strip_prefix(' ') { r2.to_string() } else { rest.to_string() }
    } else { line.to_string() }
}

fn parse_blockquote_group(lines: &[&str], start: usize, section_line: usize, refs: &RefMap, _depth: usize) -> (Vec<Block>, usize) {
    let mut stripped: Vec<String> = Vec::new();
    let mut i = start;
    let mut raw_count = 0usize;
    while i < lines.len() {
        let l = lines[i];
        if is_blockquote_start(l) {
            stripped.push(strip_blockquote_marker(l));
            raw_count += 1;
            i += 1;
        } else if !l.trim().is_empty() && !stripped.is_empty() {
            // lazy continuation
            stripped.push(l.to_string());
            raw_count += 1;
            i += 1;
        } else { break; }
    }
    let mut out: Vec<Block> = Vec::new();
    // fence segments inside quote become top-level code; list segments become ghost list
    let mut text_accum: Vec<String> = Vec::new();
    let mut idx = 0usize;
    let mut flush_quote = |text_accum: &mut Vec<String>, out: &mut Vec<Block>| {
        if text_accum.iter().all(|s| s.trim().is_empty()) { text_accum.clear(); return; }
        // determine if a contiguous plain paragraph of >=2 lines (no blank) precedes => ghost paragraph
        let nonblank: Vec<&String> = text_accum.iter().filter(|s| !s.trim().is_empty()).collect();
        let has_blank = text_accum.iter().any(|s| s.trim().is_empty());
        let first_is_heading = nonblank.first().map(|s| atx_parse(s).is_some()).unwrap_or(false);
        let has_heading_line = nonblank.iter().any(|s| atx_parse(s).is_some());
        let mut text = String::new();
        for s in &*text_accum {
            if s.trim().is_empty() { continue; }
            let mut st = s.trim().to_string();
            if let Some((_, inner, _)) = atx_parse(&st) { st = inner; }
            // strip nested quote markers
            while st.starts_with('>') { st = strip_blockquote_marker(&st); }
            text.push_str(&st);
        }
        if !first_is_heading && !has_blank && nonblank.len() >= 2 {
            out.push(Block::Paragraph { content: " ".to_string(), inline: vec![Inline::Text { value: " ".to_string() }] });
        }
        let _ = has_heading_line;
        let inline = parse_inline(&text, refs);
        let content = content_from_inline(&inline);
        let inner_content = content.clone();
        out.push(Block::Blockquote {
            content: inner_content,
            blocks: vec![Block::Paragraph { content, inline }],
        });
        text_accum.clear();
    };
    while idx < stripped.len() {
        let l = stripped[idx].clone();
        if let Some((fc, flen, info)) = is_fence_start(&l) {
            flush_quote(&mut text_accum, &mut out);
            let lang = info.split_whitespace().next().map(|s| s.to_string());
            let mut content_lines: Vec<String> = Vec::new();
            idx += 1;
            while idx < stripped.len() {
                let cl = stripped[idx].clone();
                let t = cl.trim_start();
                let run = t.chars().take_while(|&c| c == fc).count();
                if run >= flen && t[run..].trim().is_empty() { idx += 1; break; }
                content_lines.push(cl);
                idx += 1;
            }
            out.push(Block::Code { language: lang.filter(|s| !s.is_empty()), content: content_lines.join("\n"), start_line: section_line, end_line: section_line });
            continue;
        }
        if parse_list_marker(&l).is_some() {
            // ghost list: gather consecutive list-ish / continuation lines
            let mut list_lines: Vec<String> = Vec::new();
            while idx < stripped.len() {
                let ll = stripped[idx].clone();
                if parse_list_marker(&ll).is_some() || (!ll.trim().is_empty()) {
                    // continuation lines that aren't markers still belong until blank?
                    list_lines.push(ll);
                    idx += 1;
                    // stop if next logic would need; keep simple: consume until end or fence
                    if idx < stripped.len() && is_fence_start(&stripped[idx]).is_some() { break; }
                    // if we have consumed all, break
                    if idx >= stripped.len() { break; }
                    // continue consuming marker lines only; non-marker breaks after including?
                    if parse_list_marker(&stripped[idx]).is_none() { break; }
                } else { break; }
            }
            // parse ghost list from list_lines
            let refs2: Vec<&str> = list_lines.iter().map(|s| s.as_str()).collect();
            if let Some(Block::List { ordered, items }) = parse_list(&refs2, 0, section_line, refs, 1).0.into() {
                let ghost_items: Vec<ListItem> = items.iter().map(|it| ListItem { checked: it.checked, content: String::new(), inline: Vec::new(), blocks: Vec::new() }).collect();
                // quote text is item contents concatenated
                for it in &items { text_accum.push(it.content.clone()); }
                out.push(Block::List { ordered, items: ghost_items });
            }
            continue;
        }
        text_accum.push(l);
        idx += 1;
    }
    flush_quote(&mut text_accum, &mut out);
    (out, i)
}

fn parse_list(lines: &[&str], start: usize, section_line: usize, refs: &RefMap, depth: usize) -> (Block, usize) {
    let first = parse_list_marker(lines[start]).unwrap();
    let ordered = first.ordered;
    let group_char = first.marker_char;
    let base_indent = first.indent;
    let mut items: Vec<ListItem> = Vec::new();
    let mut i = start;
    while i < lines.len() {
        let m = match parse_list_marker(lines[i]) { Some(m) => m, None => break };
        if m.indent != base_indent || m.ordered != ordered || m.marker_char != group_char { break; }
        let content_col = m.content_col;
        let (checked, first_content) = strip_task(&m.content);
        let mut item_lines: Vec<String> = vec![first_content];
        i += 1;
        // collect item body lines
        while i < lines.len() {
            let l = lines[i];
            if l.trim().is_empty() {
                // look ahead
                let mut k = i;
                while k < lines.len() && lines[k].trim().is_empty() { k += 1; }
                if k >= lines.len() { i = k; break; }
                let nl = lines[k];
                if let Some(nm) = parse_list_marker(nl) {
                    if nm.indent == base_indent && nm.ordered == ordered && nm.marker_char == group_char {
                        i = k; break; // next item (blanks consumed as separator)
                    }
                }
                let nindent = nl.chars().take_while(|&c| c == ' ').count();
                if nindent >= content_col {
                    item_lines.push(String::new());
                    i += 1;
                    continue;
                } else {
                    i = k; // list likely ends; leave i at next nonblank? outer will handle
                    // mark end by setting a flag via breaking outer loops
                    // use sentinel: push marker by breaking both
                    // We break item collection and end list: set i=k and signal below
                    // Determine: if next is a new item of different group or other block, list ends.
                    break;
                }
            }
            if let Some(nm) = parse_list_marker(l) {
                if nm.indent == base_indent && nm.ordered == ordered && nm.marker_char == group_char {
                    break; // next item
                }
                if nm.indent == base_indent && (nm.ordered != ordered || nm.marker_char != group_char) {
                    // different list starts; end this list item and list
                    // break item collection; outer check will break list
                    // we need to distinguish: break out and let outer loop fail marker match
                    // set a flag
                    // We'll break and outer loop will check marker mismatch and stop.
                    // To avoid infinite loop, mark by using goto-like flag:
                    // simplest: break item collection
                    // outer loop sees different marker and breaks.
                    // That's fine.
                    // but we are still inside item collection; break
                    // (outer while will try parse marker at i, mismatch -> break)
                    // good
                    // fallthrough
                    // NOTE: need to actually break
                    // handled below
                    // --
                    // break
                    // Rust: break inner while
                    // (this comment in code)
                    // Actually do break:
                    // (can't from nested if?) we can
                    // We'll use 'itemdone' label in real code path below
                    // This code branch is handled by the break after if chain
                    // To keep compiler simple we break here:
                    // --
                    break;
                }
                if nm.indent > base_indent {
                    // nested list line: strip (nm.indent) spaces? keep relative
                    let stripped: String = l.chars().skip(content_col.min(l.chars().count())).collect();
                    item_lines.push(stripped);
                    i += 1;
                    continue;
                }
            }
            let indent = l.chars().take_while(|&c| c == ' ').count();
            if indent >= content_col {
                let stripped: String = l.chars().skip(content_col.min(l.chars().count())).collect();
                item_lines.push(stripped);
                i += 1;
                continue;
            }
            // other block starters end list if at column 0 and item already has content?
            if is_fence_start(l).is_some() || atx_parse(l).is_some() || is_blockquote_start(l) || is_hr(l) {
                break;
            }
            // lazy continuation
            item_lines.push(l.trim_start().to_string());
            i += 1;
        }
        // Build item from item_lines
        let item = build_list_item(item_lines, checked, section_line, refs, depth);
        items.push(item);
        // loop continues if next line is a matching item; the while condition checks
        if i < lines.len() {
            match parse_list_marker(lines[i]) {
                Some(nm) if nm.indent == base_indent && nm.ordered == ordered && nm.marker_char == group_char => continue,
                _ => {
                    // Skip trailing blanks already handled; if next is blank skip? outer block loop will skip
                    break;
                }
            }
        }
    }
    (Block::List { ordered, items }, i)
}

fn build_list_item(item_lines: Vec<String>, checked: Option<bool>, section_line: usize, refs: &RefMap, depth: usize) -> ListItem {
    // detect structures in lines after first
    let text_lines: Vec<&str> = item_lines.iter().map(|s| s.as_str()).collect();
    let raw = item_lines.join("\n");
    let has_structure = text_lines.iter().skip(1).any(|l| {
        let t = l.trim_start();
        is_fence_start(l).is_some() || parse_list_marker(l).is_some() || is_blockquote_start(l) || atx_parse(l).is_some()
            || t.starts_with("```")
    }) || text_lines.first().map(|l| is_fence_start(l).is_some()).unwrap_or(false);
    if !has_structure {
        // plain paragraph item: inline per line concatenated
        let mut inline: Vec<Inline> = Vec::new();
        for (idx, l) in item_lines.iter().enumerate() {
            if l.trim().is_empty() { continue; }
            let ll = if idx == 0 { l.as_str() } else { l.trim() };
            inline.extend(parse_inline(ll, refs));
        }
        let content = content_from_inline(&inline);
        return ListItem { checked, content, inline, blocks: Vec::new() };
    }
    // structured: parse sub-blocks
    let sub = if depth > 8 { Vec::new() } else { parse_blocks_with_refs(&raw, section_line, refs, depth + 1) };
    let mut content = String::new();
    let mut inline: Vec<Inline> = Vec::new();
    let mut extra_blocks: Vec<Block> = Vec::new();
    let mut first = true;
    for b in sub {
        match b {
            Block::Paragraph { content: c, inline: il } if first => { content = c; inline = il; }
            Block::List { items: nested, .. } => {
                // flatten nested list into this item
                if first && content.is_empty() {
                    // no preceding paragraph
                }
                for nit in nested {
                    if !content.is_empty() || !inline.is_empty() {
                        content.push_str("\n  ");
                        content.push_str(&nit.content);
                    } else {
                        content = nit.content.clone();
                    }
                    inline.extend(nit.inline);
                }
            }
            other => { extra_blocks.push(other); }
        }
        first = false;
    }
    ListItem { checked, content, inline, blocks: extra_blocks }
}

// Conversion helper used in blockquote ghost list parsing
trait IntoBlockList { fn into(self) -> Option<Block>; }
impl IntoBlockList for Block {
    fn into(self) -> Option<Block> { Some(self) }
}

struct FlatHeading {
    level: u8,
    title: String,
    title_inline: Vec<Inline>,
    first_line: usize, // 0-based in processed content
    heading_start_byte: usize,
    content_start_byte: usize,
    nested: bool,
}

pub fn parse_document(content_in: &str) -> Document {
    let processed: String = if content_in.lines().any(|l| l.trim_start().starts_with('#')) {
        content_in.to_string()
    } else {
        format!("# Input\n\n{}", content_in)
    };
    let refs = collect_refs(&processed);
    // split processed into lines with byte offsets
    let mut line_starts: Vec<usize> = Vec::new();
    let mut line_texts: Vec<String> = Vec::new();
    let mut line_has_nl: Vec<bool> = Vec::new();
    {
        let bytes = processed.as_bytes();
        let mut start = 0usize;
        let mut idx = 0usize;
        while idx < bytes.len() {
            if bytes[idx] == b'\n' {
                line_starts.push(start);
                let mut txt = &processed[start..idx];
                if txt.ends_with('\r') { txt = &txt[..txt.len() - 1]; }
                line_texts.push(txt.to_string());
                line_has_nl.push(true);
                idx += 1;
                start = idx;
            } else { idx += 1; }
        }
        if start < bytes.len() || bytes.is_empty() {
            line_starts.push(start);
            let mut txt = &processed[start..];
            if txt.ends_with('\r') { txt = &txt[..txt.len() - 1]; }
            line_texts.push(txt.to_string());
            line_has_nl.push(false);
        }
    }
    let line_byte_end = |idx: usize| -> usize {
        if line_has_nl.get(idx).copied().unwrap_or(false) {
            let s = line_starts[idx];
            // start of next line
            if idx + 1 < line_starts.len() { line_starts[idx + 1] } else { processed.len() }
            // note s unused
            .max(s)
        } else { processed.len() }
    };
    // YAML front matter range
    let mut fm_end: Option<usize> = None;
    if !line_texts.is_empty() && line_texts[0].trim() == "---" {
        for j in 1..line_texts.len().min(200) {
            if line_texts[j].trim() == "---" || line_texts[j].trim() == "..." { fm_end = Some(j); break; }
        }
        if fm_end.is_none() { /* not front matter */ }
    }
    let mut flat_h: Vec<FlatHeading> = Vec::new();
    let mut in_fence = false;
    let mut fence_char = '`';
    let mut fence_len = 0usize;
    let mut para_start: Option<usize> = None;
    for idx in 0..line_texts.len() {
        let line = &line_texts[idx];
        if let Some(end) = fm_end {
            if idx <= end { continue; }
        }
        // fence tracking
        if let Some((fc, flen, _)) = is_fence_start(line) {
            if !in_fence { in_fence = true; fence_char = fc; fence_len = flen; }
            else if fc == fence_char && flen >= fence_len && line.trim_start()[flen..].trim().is_empty() { in_fence = false; }
            para_start = None;
            continue;
        }
        if in_fence { continue; }
        // setext underline
        if let Some(level) = setext_level(line) {
            if let Some(start) = para_start {
                // build title from para lines start..idx
                let mut all_inline: Vec<Inline> = Vec::new();
                for pl in &line_texts[start..idx] { all_inline.extend(parse_inline(pl.trim(), &refs)); }
                let title = title_from_inline(&all_inline);
                let heading_start_byte = line_starts[start];
                let content_start_byte = if line_has_nl[start] { line_byte_end(start) } else { processed.len() };
                flat_h.push(FlatHeading { level, title, title_inline: all_inline, first_line: start, heading_start_byte, content_start_byte, nested: false });
                para_start = None;
                continue;
            }
            // '---' alone is HR, not heading; '===' alone is paragraph
            if level == 2 {
                para_start = None;
                continue;
            }
        }
        // ATX at top-level
        let mut found_heading = false;
        if let Some((level, inner, indent)) = atx_parse(line) {
            let inline = parse_inline(&inner, &refs);
            let title = title_from_inline(&inline);
            flat_h.push(FlatHeading {
                level, title, title_inline: inline,
                first_line: idx,
                heading_start_byte: line_starts[idx] + indent,
                content_start_byte: line_byte_end(idx),
                nested: indent > 0,
            });
            found_heading = true;
        } else if is_blockquote_start(line) {
            // nested heading inside blockquote
            let mut rest = strip_blockquote_marker(line);
            while is_blockquote_start(&rest) { rest = strip_blockquote_marker(&rest); }
            if let Some((level, inner, indent)) = atx_parse(&rest) {
                let inline = parse_inline(&inner, &refs);
                let title = title_from_inline(&inline);
                // heading start byte: position of '#' in original line
                let hash_pos = line.find('#').unwrap_or(indent);
                flat_h.push(FlatHeading { level, title, title_inline: inline, first_line: idx, heading_start_byte: line_starts[idx] + hash_pos, content_start_byte: line_byte_end(idx), nested: true });
                found_heading = true;
            }
        } else if let Some(m) = parse_list_marker(line) {
            let rest = m.content.clone();
            if let Some((level, inner, _)) = atx_parse(&rest) {
                let inline = parse_inline(&inner, &refs);
                let title = title_from_inline(&inline);
                let hash_pos = line.find('#').unwrap_or(0);
                flat_h.push(FlatHeading { level, title, title_inline: inline, first_line: idx, heading_start_byte: line_starts[idx] + hash_pos, content_start_byte: line_byte_end(idx), nested: true });
                found_heading = true;
            }
        }
        if found_heading { para_start = None; continue; }
        // update paragraph tracker for setext
        if line.trim().is_empty() {
            para_start = None;
        } else if is_fence_start(line).is_some() || is_hr(line) || is_blockquote_start(line) || parse_list_marker(line).is_some() {
            para_start = None;
        } else if i_is_table_line(&line_texts, idx) {
            para_start = None;
        } else {
            if para_start.is_none() { para_start = Some(idx); }
        }
    }

    // Build sections (flat) with raw content
    let atx_boundary_lines: Vec<usize> = flat_h.iter().map(|h| h.first_line).collect();
    let mut sections_flat: Vec<Section> = Vec::new();
    for (hi, h) in flat_h.iter().enumerate() {
        // end = next ATX-type heading line after this one (all headings in our list whose
        // first_line > h.first_line and which are not setext?) Use next heading whose
        // first_line > h.first_line and (it is not a setext heading?) - approximate with
        // next heading in list that starts a new ATX line. Setext headings have
        // first_line being a paragraph line; including them as boundaries matches most.
        let mut end_line = line_texts.len();
        for (hj, other) in flat_h.iter().enumerate() {
            if hj == hi { continue; }
            if other.first_line > h.first_line && other.first_line < end_line {
                // skip setext headings as boundaries? original raw for a parent before a
                // setext child includes the setext text, so skip setext-type headings.
                // We can't easily know type here; heuristic: if the other heading's
                // first_line line itself is an ATX line or nested, it's a boundary.
                let oline = &line_texts[other.first_line];
                if atx_parse(oline).is_some() || is_blockquote_start(oline) || parse_list_marker(oline).map(|m| atx_parse(&m.content).is_some()).unwrap_or(false) {
                    end_line = other.first_line;
                }
            }
        }
        let _ = atx_boundary_lines;
        let start_content_line = h.first_line + 1;
        let raw_slice = if start_content_line <= end_line && start_content_line <= line_texts.len() {
            line_texts[start_content_line..end_line.min(line_texts.len())].join("\n")
        } else { String::new() };
        let raw = raw_slice.trim().to_string();
        // position
        let offset = if line_has_nl.get(h.first_line).copied().unwrap_or(false) {
            line_byte_end(h.first_line)
        } else {
            h.heading_start_byte
        };
        let mut line_no = h.first_line + 2;
        if h.nested { line_no += 1; }
        let pos_line_for_blocks = line_no;
        let blocks = parse_blocks(&raw, pos_line_for_blocks);
        let slug = slugify(&h.title);
        sections_flat.push(Section {
            id: slug.clone(),
            level: h.level,
            title: h.title.clone(),
            slug,
            position: Position { line: line_no, offset },
            content: SectionContent { raw, blocks },
            children: Vec::new(),
            line_idx: h.first_line,
            heading_start_byte: h.heading_start_byte,
            content_start_byte: h.content_start_byte,
            title_inline: h.title_inline.clone(),
        });
    }

    // build tree
    let mut parents: Vec<Option<usize>> = vec![None; sections_flat.len()];
    let mut stack: Vec<usize> = Vec::new();
    for i in 0..sections_flat.len() {
        while let Some(&top) = stack.last() {
            if sections_flat[top].level >= sections_flat[i].level { stack.pop(); } else { break; }
        }
        parents[i] = stack.last().copied();
        stack.push(i);
    }
    fn build(i: usize, flat: &[Section], parents: &[Option<usize>]) -> Section {
        let mut sec = flat[i].clone();
        sec.children = (0..flat.len()).filter(|&j| parents[j] == Some(i)).map(|j| build(j, flat, parents)).collect();
        sec
    }
    let roots: Vec<Section> = (0..sections_flat.len()).filter(|&i| parents[i].is_none()).map(|i| build(i, &sections_flat, &parents)).collect();
    let heading_count = sections_flat.len();
    fn depth(secs: &[Section], cur: usize) -> usize {
        let mut m = if secs.is_empty() { 0 } else { cur };
        for s in secs { m = m.max(depth(&s.children, cur + 1)); }
        m
    }
    let max_depth = depth(&roots, 1);
    let word_count = processed.split_whitespace().count();
    Document {
        content: processed,
        sections: roots,
        flat: sections_flat,
        word_count,
        heading_count,
        max_depth,
    }
}

fn i_is_table_line(line_texts: &[String], idx: usize) -> bool {
    idx + 1 < line_texts.len() && is_table_delimiter(&line_texts[idx + 1]).is_some()
}
RS
"}

