pub fn format_number(n: f64) -> String {
    if n == n.trunc() && n.abs() < 9.007_199_254_740_992e15 {
        format!("{}", n as i64)
    } else {
        format!("{}", n)
    }
}

pub fn text_of(v: &Value) -> String {
    match v {
        Value::Null => String::new(),
        Value::Bool(b) => b.to_string(),
        Value::Number(n) => format_number(*n),
        Value::String(s) => s.clone(),
        Value::Array(a) => a.iter().map(text_of).collect::<Vec<_>>().join("\n"),
        Value::Object(_) => format_plain(v),
        Value::Document { content, .. } => content.clone(),
        Value::Heading(h) => h.text.clone(),
        Value::Code(c) => c.content.clone(),
        Value::Link(l) => l.text.clone(),
        Value::Image(im) => im.alt.clone(),
        Value::Table(t) => format!("Table({}x{})", t.headers.len(), t.rows.len()),
        Value::List(l) => l.items.iter().map(|(c, _)| c.clone()).collect::<Vec<_>>().join("\n"),
        Value::Blockquote(c) => c.clone(),
    }
}

pub fn format_plain(v: &Value) -> String {
    match v {
        Value::Document { heading_count, word_count, .. } => format!("Document: {} headings, {} words", heading_count, word_count),
        Value::Heading(h) => format!("{} {}", "#".repeat(h.level as usize), h.text),
        Value::Code(c) => {
            let lang = c.language.clone().unwrap_or_default();
            format!("```{}\n{}\n```", lang, c.content)
        }
        Value::Link(l) => format!("[{}]({})", l.text, l.url),
        Value::Image(im) => format!("![{}]({})", im.alt, im.src),
        Value::Table(t) => {
            let mut lines = Vec::new();
            lines.push(format!("| {} |", t.headers.join(" | ")));
            lines.push(format!("| {} |", t.headers.iter().map(|_| "---").collect::<Vec<_>>().join(" | ")));
            for r in &t.rows { lines.push(format!("| {} |", r.join(" | "))); }
            lines.join("\n")
        }
        Value::List(l) => {
            let mut lines = Vec::new();
            for (idx, (content, checked)) in l.items.iter().enumerate() {
                if l.ordered {
                    lines.push(format!("{}. {}", idx + 1, content));
                } else {
                    let prefix = match checked { Some(true) => "[x] ", Some(false) => "[ ] ", None => "" };
                    lines.push(format!("- {}{}", prefix, content));
                }
            }
            lines.join("\n")
        }
        Value::Blockquote(c) => format!("> {}", c),
        Value::Array(a) => a.iter().map(format_plain).collect::<Vec<_>>().join("\n"),
        Value::Object(entries) => {
            let mut lines: Vec<String> = Vec::new();
            for (k, val) in entries {
                if let Value::Array(arr) = val {
                    if arr.is_empty() {
                        lines.push(format!("{}: ", k));
                    } else {
                        let plain = format_plain(val);
                        let mut plines = plain.lines();
                        let first = plines.next().unwrap_or("");
                        lines.push(format!("{}: {}", k, first));
                        for rest in plines { lines.push(rest.to_string()); }
                    }
                } else {
                    lines.push(format!("{}: {}", k, format_plain(val)));
                }
            }
            lines.join("\n")
        }
        other => text_of(other),
    }
}

pub fn format_md(v: &Value) -> String {
    match v {
        Value::Heading(h) => h.raw_md.clone(),
        Value::Document { content, .. } => content.clone(),
        _ => format_plain(v),
    }
}

pub fn value_to_json(v: &Value) -> serde_json::Value {
    match v {
        Value::Null => serde_json::Value::Null,
        Value::Bool(b) => serde_json::Value::Bool(*b),
        Value::Number(n) => serde_json::Number::from_f64(*n).map(serde_json::Value::Number).unwrap_or(serde_json::Value::Null),
        Value::String(s) => serde_json::Value::String(s.clone()),
        Value::Array(a) => serde_json::Value::Array(a.iter().map(value_to_json).collect()),
        Value::Object(entries) => {
            let mut map = serde_json::Map::new();
            for (k, val) in entries { map.insert(k.clone(), value_to_json(val)); }
            serde_json::Value::Object(map)
        }
        Value::Document { heading_count, word_count, .. } => {
            serde_json::json!({"type":"document","heading_count":heading_count,"word_count":word_count})
        }
        Value::Heading(h) => serde_json::json!({"type":"heading","level":h.level,"text":h.text,"line":h.line}),
        Value::Code(c) => serde_json::json!({"type":"code","language":c.language,"content":c.content,"start_line":c.start_line,"end_line":c.end_line}),
        Value::Link(l) => serde_json::json!({"type":"link","text":l.text,"url":l.url,"link_type":l.link_type.as_str()}),
        Value::Image(im) => serde_json::json!({"type":"image","alt":im.alt,"src":im.src}),
        Value::Table(t) => serde_json::json!({"type":"table","headers":t.headers,"rows":t.rows}),
        Value::List(l) => {
            let items: Vec<serde_json::Value> = l.items.iter().map(|(content, checked)| {
                serde_json::json!({"content":content,"checked":checked})
            }).collect();
            serde_json::json!({"type":"list","ordered":l.ordered,"items":items})
        }
        Value::Blockquote(c) => serde_json::json!({"type":"blockquote","content":c}),
    }
}

fn tree_value_lines(v: &Value) -> Vec<String> {
    match v {
        Value::Array(a) => {
            let mut lines = vec!["[".to_string()];
            lines.extend(render_tree_nodes(a, false));
            lines.push("]".to_string());
            lines
        }
        Value::Object(entries) => {
            let mut lines = vec!["{".to_string()];
            for (k, val) in entries {
                let sub = tree_value_lines(val);
                if sub.len() == 1 {
                    lines.push(format!("{}: {}", k, sub[0]));
                } else {
                    lines.push(format!("{}: ", k));
                    // indent sub lines by two spaces (approximation of original)
                    for s in sub { lines.push(format!("  {}", s)); }
                }
            }
            lines.push("}".to_string());
            lines
        }
        _ => format_plain(v).lines().map(|s| s.to_string()).collect::<Vec<_>>().into_iter().chain(if format_plain(v).is_empty() { vec![String::new()] } else { vec![] }).collect(),
    }
}

fn render_tree_nodes(values: &[Value], _root: bool) -> Vec<String> {
    let mut lines = Vec::new();
    for (i, v) in values.iter().enumerate() {
        let last = i + 1 == values.len();
        let connector = if last { "└──" } else { "├──" };
        let cont = if last { "   " } else { "│  " };
        let sub = tree_value_lines(v);
        if sub.is_empty() {
            lines.push(connector.to_string());
        } else {
            lines.push(format!("{}{}", connector, sub[0]));
            for rest in &sub[1..] { lines.push(format!("{}{}", cont, rest)); }
        }
    }
    lines
}

pub fn format_output(results: &[Value], fmt: &str) -> String {
    match fmt {
        "plain" => {
            let mut out = String::new();
            for v in results { out.push_str(&format_plain(v)); out.push('\n'); }
            out
        }
        "json" => {
            if results.is_empty() { String::new() }
            else if results.len() == 1 { format!("{}\n", serde_json::to_string(&value_to_json(&results[0])).unwrap()) }
            else {
                let arr: Vec<serde_json::Value> = results.iter().map(value_to_json).collect();
                format!("{}\n", serde_json::to_string(&arr).unwrap())
            }
        }
        "json-pretty" => {
            if results.is_empty() { String::new() }
            else if results.len() == 1 { format!("{}\n", serde_json::to_string_pretty(&value_to_json(&results[0])).unwrap()) }
            else {
                let arr: Vec<serde_json::Value> = results.iter().map(value_to_json).collect();
                format!("{}\n", serde_json::to_string_pretty(&arr).unwrap())
            }
        }
        "jsonl" => {
            let mut out = String::new();
            for v in results { out.push_str(&serde_json::to_string(&value_to_json(v)).unwrap()); out.push('\n'); }
            out
        }
        "md" => {
            if results.is_empty() { String::new() }
            else {
                let parts: Vec<String> = results.iter().map(format_md).collect();
                format!("{}\n", parts.join("\n\n"))
            }
        }
        "tree" => {
            if results.is_empty() { String::new() }
            else {
                let lines = render_tree_nodes(results, true);
                format!("{}\n\n", lines.join("\n"))
            }
        }
        _ => String::new(),
    }
}

// ---------- Query context ----------
pub struct QueryContext {
    pub doc_content: String,
    pub heading_count: usize,
    pub word_count: usize,
    pub headings: Vec<HeadingValue>,
    pub codes: Vec<CodeValue>,
    pub links: Vec<LinkValue>,
    pub tables: Vec<TableValue>,
    pub lists: Vec<ListValue>,
    pub parents: Vec<Option<usize>>,
    pub children_map: Vec<Vec<usize>>,
}

impl QueryContext {
    pub fn build(doc: &Document) -> Self {
        let content = doc.content.clone();
        let flat = doc.flat_sections();
        // parents among flat headings
        let mut parents: Vec<Option<usize>> = vec![None; flat.len()];
        let mut stack: Vec<usize> = Vec::new();
        for i in 0..flat.len() {
            while let Some(&top) = stack.last() {
                if flat[top].level >= flat[i].level { stack.pop(); } else { break; }
            }
            parents[i] = stack.last().copied();
            stack.push(i);
        }
        let mut children_map: Vec<Vec<usize>> = vec![Vec::new(); flat.len()];
        for (i, p) in parents.iter().enumerate() {
            if let Some(p) = p { children_map[*p].push(i); }
        }
        // heading values
        let mut headings: Vec<HeadingValue> = Vec::new();
        for (i, sec) in flat.iter().enumerate() {
            // next heading with level <= this
            let mut end = content.len();
            for (j, other) in flat.iter().enumerate().skip(i + 1) {
                if other.level <= sec.level { end = other.heading_start_byte; let _ = j; break; }
            }
            let raw_md = content[sec.heading_start_byte.min(content.len())..end].to_string();
            let content_slice = if sec.content_start_byte <= end {
                content[sec.content_start_byte..end].trim().to_string()
            } else { String::new() };
            headings.push(HeadingValue {
                level: sec.level, text: sec.title.clone(), offset: sec.heading_start_byte,
                line: sec.line_idx + 1, content: content_slice, raw_md, index: i,
            });
        }
        // elements
        let mut codes: Vec<CodeValue> = Vec::new();
        let mut links: Vec<LinkValue> = Vec::new();
        let mut tables: Vec<TableValue> = Vec::new();
        let mut lists: Vec<ListValue> = Vec::new();
        let mut link_cursor: usize = 0;
        let mut push_link = |links: &mut Vec<LinkValue>, text: &str, url: &str, content: &str, cursor: &mut usize| {
            let lt = classify_link(url);
            let pat = format!("[{}]({})", text, url);
            let offset = if let Some(pos) = content[*cursor..].find(&pat) { let p = *cursor + pos; *cursor = p + 1; p }
                else if let Some(pos) = content.find(&pat) { pos } else { 0 };
            links.push(LinkValue { text: text.to_string(), url: url.to_string(), link_type: lt, offset });
        };
        for sec in &flat {
            for inl in &sec.title_inline {
                if let Inline::Link { text, url, .. } = inl {
                    push_link(&mut links, text, url, &content, &mut link_cursor);
                }
            }
            collect_from_blocks(&sec.content.blocks, &mut codes, &mut links, &mut tables, &mut lists, &content, &mut link_cursor);
        }
        QueryContext {
            doc_content: content, heading_count: doc.heading_count, word_count: doc.word_count,
            headings, codes, links, tables, lists, parents, children_map,
        }
    }
    pub fn document_value(&self) -> Value {
        Value::Document { content: self.doc_content.clone(), heading_count: self.heading_count, word_count: self.word_count }
    }
    pub fn selector_elements(&self, name: &str) -> Option<Vec<Value>> {
        let headings_all: Vec<Value> = self.headings.iter().map(|h| Value::Heading(h.clone())).collect();
        match name {
            "h" | "heading" | "headings" | "headers" => Some(headings_all),
            "h1" | "h2" | "h3" | "h4" | "h5" | "h6" => {
                let lvl = name[1..].parse::<u8>().unwrap();
                Some(self.headings.iter().filter(|h| h.level == lvl).map(|h| Value::Heading(h.clone())).collect())
            }
            "code" | "pre" | "codeblock" | "codeblocks" => Some(self.codes.iter().map(|c| Value::Code(c.clone())).collect()),
            "link" | "links" | "a" => Some(self.links.iter().map(|l| Value::Link(l.clone())).collect()),
            "img" | "image" | "images" => Some(Vec::new()),
            "table" | "tables" => Some(self.tables.iter().map(|t| Value::Table(t.clone())).collect()),
            "list" | "lists" | "ul" | "ol" => Some(self.lists.iter().map(|l| Value::List(l.clone())).collect()),
            "blockquote" | "blockquotes" | "quote" | "quotes" => Some(Vec::new()),
            "p" | "para" | "paragraph" | "paragraphs" => Some(Vec::new()),
            "frontmatter" | "yaml" => Some(Vec::new()),
            _ => None,
        }
    }
    pub fn stats_object(&self) -> Value {
        Value::Object(vec![
            ("headings".to_string(), Value::Number(self.headings.len() as f64)),
            ("code_blocks".to_string(), Value::Number(self.codes.len() as f64)),
            ("links".to_string(), Value::Number(self.links.len() as f64)),
            ("images".to_string(), Value::Number(0.0)),
            ("tables".to_string(), Value::Number(self.tables.len() as f64)),
            ("lists".to_string(), Value::Number(self.lists.len() as f64)),
            ("words".to_string(), Value::Number(self.word_count as f64)),
        ])
    }
    pub fn levels_object(&self) -> Value {
        let mut counts: Vec<(u8, usize)> = Vec::new();
        for h in &self.headings {
            if let Some(e) = counts.iter_mut().find(|(l, _)| *l == h.level) { e.1 += 1; } else { counts.push((h.level, 1)); }
        }
        counts.sort_by_key(|(l, _)| *l);
        Value::Object(counts.iter().map(|(l, c)| (format!("h{}", l), Value::Number(*c as f64))).collect())
    }
    pub fn langs_object(&self) -> Value {
        let mut counts: Vec<(String, usize)> = Vec::new();
        for c in &self.codes {
            let k = c.language.clone().unwrap_or_else(|| "none".to_string());
            if let Some(e) = counts.iter_mut().find(|(l, _)| *l == k) { e.1 += 1; } else { counts.push((k, 1)); }
        }
        Value::Object(counts.iter().map(|(l, c)| (l.clone(), Value::Number(*c as f64))).collect())
    }
    pub fn types_object(&self) -> Value {
        let mut counts: Vec<(String, usize)> = Vec::new();
        for l in &self.links {
            let k = l.link_type.as_str().to_string();
            if let Some(e) = counts.iter_mut().find(|(x, _)| *x == k) { e.1 += 1; } else { counts.push((k, 1)); }
        }
        Value::Object(counts.iter().map(|(l, c)| (l.clone(), Value::Number(*c as f64))).collect())
    }
}

fn classify_link(url: &str) -> LinkType {
    if url.starts_with('#') { LinkType::Anchor }
    else if url.starts_with("http://") || url.starts_with("https://") || url.starts_with("mailto:") { LinkType::External }
    else { LinkType::Relative }
}

fn collect_from_blocks(
    blocks: &[crate::parser::Block],
    codes: &mut Vec<CodeValue>, links: &mut Vec<LinkValue>,
    tables: &mut Vec<TableValue>, lists: &mut Vec<ListValue>,
    doc_content: &str, link_cursor: &mut usize,
) {
    use crate::parser::Block;
    for b in blocks {
        match b {
            Block::Paragraph { inline, .. } => {
                for inl in inline { if let Inline::Link { text, url, .. } = inl { push_link_raw(links, text, url, doc_content, link_cursor); } }
            }
            Block::Heading { inline, .. } => {
                for inl in inline { if let Inline::Link { text, url, .. } = inl { push_link_raw(links, text, url, doc_content, link_cursor); } }
            }
            Block::Code { language, content, .. } => {
                codes.push(CodeValue { language: language.clone(), content: content.clone(), start_line: 1, end_line: 1 });
            }
            Block::List { ordered, items } => {
                lists.push(ListValue { ordered: *ordered, items: items.iter().map(|it| (it.content.clone(), it.checked)).collect() });
                for it in items {
                    for inl in &it.inline { if let Inline::Link { text, url, .. } = inl { push_link_raw(links, text, url, doc_content, link_cursor); } }
                    collect_from_blocks(&it.blocks, codes, links, tables, lists, doc_content, link_cursor);
                }
            }
            Block::Table { headers, alignments, rows } => {
                tables.push(TableValue { headers: headers.clone(), rows: rows.clone(), alignments: alignments.clone() });
                // links from cells: parse cell content strings as inline with empty refs
                let empty_refs = crate::parser::collect_refs("");
                for cell in headers.iter().chain(rows.iter().flatten()) {
                    let inls = crate::parser::parse_inline(cell, &empty_refs);
                    for inl in &inls { if let Inline::Link { text, url, .. } = inl { push_link_raw(links, text, url, doc_content, link_cursor); } }
                }
            }
            Block::Blockquote { blocks: inner, .. } => {
                collect_from_blocks(inner, codes, links, tables, lists, doc_content, link_cursor);
            }
            Block::HorizontalRule => {}
        }
    }
}

fn push_link_raw(links: &mut Vec<LinkValue>, text: &str, url: &str, content: &str, cursor: &mut usize) {
    let lt = classify_link(url);
    let pat = format!("[{}]({})", text, url);
    let offset = if let Some(pos) = content[*cursor..].find(&pat) { let p = *cursor + pos; *cursor = p + 1; p }
        else if let Some(pos) = content.find(&pat) { pos } else { 0 };
    links.push(LinkValue { text: text.to_string(), url: url.to_string(), link_type: lt, offset });
}

// ---------- Errors ----------
#[derive(Debug, Clone)]
pub struct QueryError { pub message: String }
impl fmt::Display for QueryError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result { write!(f, "{}", self.message) }
}
fn runtime_error(msg: impl Into<String>) -> QueryError { QueryError { message: format!("error: {}\n\n", msg.into()) } }

// ---------- Lexer ----------
#[derive(Debug, Clone, PartialEq)]
enum Tok {
    Dot, Pipe, Comma, LParen, RParen, LBracket, RBracket, LBrace, RBrace, Colon,
    Greater, Less, GreaterEq, LessEq, EqualEq, NotEq, Plus, Minus, Star, Slash, Percent,
    Ident(String), Number(f64, String), Str(String), Eof,
}
#[derive(Debug, Clone)]
struct Token { tok: Tok, start: usize, len: usize, text: String }

fn span_error(query: &str, msg: &str, start: usize, len: usize, label: &str, help: Option<&str>) -> QueryError {
    let mut caret_pad = String::new();
    for c in query.chars().take(start) { caret_pad.push(if c == '\t' { '\t' } else { ' ' }); }
    let carets = "^".repeat(len.max(1));
    let mut out = format!("error: {}\n  --> query\n  |\n1 | {}\n    {}{}  {}\n", msg, query, caret_pad, carets, label);
    if let Some(h) = help { out.push_str(&format!("  = help: {}\n", h)); }
    out.push('\n');
    QueryError { message: out }
}

fn token_found_display(t: &Token) -> String {
    match &t.tok {
        Tok::Eof => "end of input".to_string(),
        Tok::Ident(_) => "identifier".to_string(),
        Tok::Number(_, _) => "number".to_string(),
        Tok::Str(_) => "string".to_string(),
        Tok::Dot => "'.'".to_string(),
        Tok::Pipe => "'|'".to_string(),
        Tok::Comma => "','".to_string(),
        Tok::LParen => "'('".to_string(),
        Tok::RParen => "')'".to_string(),
        Tok::LBracket => "'['".to_string(),
        Tok::RBracket => "']'".to_string(),
        Tok::LBrace => "'{'".to_string(),
        Tok::RBrace => "'}'".to_string(),
        Tok::Colon => "':'".to_string(),
        Tok::Greater => "'>'".to_string(),
        Tok::Less => "'<'".to_string(),
        Tok::GreaterEq => "'>='".to_string(),
        Tok::LessEq => "'<='".to_string(),
        Tok::EqualEq => "'=='".to_string(),
        Tok::NotEq => "'!='".to_string(),
        Tok::Plus => "'+'".to_string(),
        Tok::Minus => "'-'".to_string(),
        Tok::Star => "'*'".to_string(),
        Tok::Slash => "'/'".to_string(),
        Tok::Percent => "'%'".to_string(),
    }
}

fn lex(query: &str) -> Result<Vec<Token>, QueryError> {
    let chars: Vec<char> = query.chars().collect();
    let mut toks: Vec<Token> = Vec::new();
    let mut i = 0usize;
    let push = |toks: &mut Vec<Token>, tok: Tok, start: usize, len: usize, text: String| toks.push(Token { tok, start, len, text });
    while i < chars.len() {
        let c = chars[i];
        if c.is_whitespace() { i += 1; continue; }
        let start = i;
        match c {
            '.' => { push(&mut toks, Tok::Dot, start, 1, ".".into()); i += 1; }
            '|' => { push(&mut toks, Tok::Pipe, start, 1, "|".into()); i += 1; }
            ',' => { push(&mut toks, Tok::Comma, start, 1, ",".into()); i += 1; }
            '(' => { push(&mut toks, Tok::LParen, start, 1, "(".into()); i += 1; }
            ')' => { push(&mut toks, Tok::RParen, start, 1, ")".into()); i += 1; }
            '[' => { push(&mut toks, Tok::LBracket, start, 1, "[".into()); i += 1; }
            ']' => { push(&mut toks, Tok::RBracket, start, 1, "]".into()); i += 1; }
            '{' => { push(&mut toks, Tok::LBrace, start, 1, "{".into()); i += 1; }
            '}' => { push(&mut toks, Tok::RBrace, start, 1, "}".into()); i += 1; }
            ':' => { push(&mut toks, Tok::Colon, start, 1, ":".into()); i += 1; }
            '>' => {
                if i + 1 < chars.len() && chars[i + 1] == '=' { push(&mut toks, Tok::GreaterEq, start, 2, ">=".into()); i += 2; }
                else { push(&mut toks, Tok::Greater, start, 1, ">".into()); i += 1; }
            }
            '<' => {
                if i + 1 < chars.len() && chars[i + 1] == '=' { push(&mut toks, Tok::LessEq, start, 2, "<=".into()); i += 2; }
                else { push(&mut toks, Tok::Less, start, 1, "<".into()); i += 1; }
            }
            '=' => {
                if i + 1 < chars.len() && chars[i + 1] == '=' { push(&mut toks, Tok::EqualEq, start, 2, "==".into()); i += 2; }
                else {
                    return Err(span_error(query, "Unexpected character '='", start, 1, "unexpected character", Some("Use '==' for equality comparison")));
                }
            }
            '!' => {
                if i + 1 < chars.len() && chars[i + 1] == '=' { push(&mut toks, Tok::NotEq, start, 2, "!=".into()); i += 2; }
                else {
                    return Err(span_error(query, "Unexpected character '!'", start, 1, "unexpected character", Some("Use 'not' for negation or '!=' for inequality")));
                }
            }
            '+' => { push(&mut toks, Tok::Plus, start, 1, "+".into()); i += 1; }
            '*' => { push(&mut toks, Tok::Star, start, 1, "*".into()); i += 1; }
            '/' => { push(&mut toks, Tok::Slash, start, 1, "/".into()); i += 1; }
            '%' => { push(&mut toks, Tok::Percent, start, 1, "%".into()); i += 1; }
            '-' => {
                if i + 1 < chars.len() && chars[i + 1].is_ascii_digit() {
                    // negative number literal
                    let mut j = i + 1;
                    let mut s = String::from("-");
                    while j < chars.len() && (chars[j].is_ascii_digit() || chars[j] == '.') { s.push(chars[j]); j += 1; }
                    if j < chars.len() && (chars[j] == 'e' || chars[j] == 'E') {
                        let mut k = j + 1;
                        if k < chars.len() && (chars[k] == '-' || chars[k] == '+') { k += 1; }
                        if k < chars.len() && chars[k].is_ascii_digit() {
                            while j < k { s.push(chars[j]); j += 1; }
                            while j < chars.len() && chars[j].is_ascii_digit() { s.push(chars[j]); j += 1; }
                        }
                    }
                    let val: f64 = s.parse().unwrap_or(0.0);
                    let len = j - i;
                    push(&mut toks, Tok::Number(val, s.clone()), start, len, s);
                    i = j;
                } else {
                    push(&mut toks, Tok::Minus, start, 1, "-".into());
                    i += 1;
                }
            }
            '"' | '\'' => {
                let quote = c;
                let mut j = i + 1;
                let mut value = String::new();
                let mut closed = false;
                while j < chars.len() {
                    let cj = chars[j];
                    if cj == '\\' && j + 1 < chars.len() {
                        let esc = chars[j + 1];
                        match esc {
                            'n' => value.push('\n'),
                            't' => value.push('\t'),
                            'r' => value.push('\r'),
                            '\\' => value.push('\\'),
                            '"' => value.push('"'),
                            '\'' => value.push('\''),
                            '0' => value.push('\0'),
                            other => { value.push('\\'); value.push(other); }
                        }
                        j += 2;
                        continue;
                    }
                    if cj == quote { closed = true; break; }
                    value.push(cj);
                    j += 1;
                }
                if !closed {
                    let raw_len = chars.len() - i;
                    return Err(span_error(query, "Unterminated string literal", start, raw_len, "string not closed", None));
                }
                let text: String = chars[i..=j].iter().collect();
                push(&mut toks, Tok::Str(value), start, j + 1 - i, text);
                i = j + 1;
            }
            _ if c.is_ascii_digit() => {
                let mut j = i;
                let mut s = String::new();
                while j < chars.len() && (chars[j].is_ascii_digit() || chars[j] == '.') { s.push(chars[j]); j += 1; }
                if j < chars.len() && (chars[j] == 'e' || chars[j] == 'E') {
                    let mut k = j + 1;
                    if k < chars.len() && (chars[k] == '-' || chars[k] == '+') { k += 1; }
                    if k < chars.len() && chars[k].is_ascii_digit() {
                        while j < k { s.push(chars[j]); j += 1; }
                        while j < chars.len() && chars[j].is_ascii_digit() { s.push(chars[j]); j += 1; }
                    }
                }
                // ensure parseable: trailing dot etc.
                let val: f64 = s.parse().unwrap_or_else(|_| s.trim_end_matches('.').parse().unwrap_or(0.0));
                push(&mut toks, Tok::Number(val, s.clone()), start, j - i, s);
                i = j;
            }
            _ if c.is_alphabetic() || c == '_' => {
                let mut j = i;
                let mut s = String::new();
                while j < chars.len() && (chars[j].is_alphanumeric() || chars[j] == '_') { s.push(chars[j]); j += 1; }
                push(&mut toks, Tok::Ident(s.clone()), start, j - i, s);
                i = j;
            }
            _ => {
                return Err(span_error(query, &format!("Unexpected character '{}'", c), start, 1, "unexpected character", None));
            }
        }
    }
    toks.push(Token { tok: Tok::Eof, start: chars.len(), len: 0, text: String::new() });
    Ok(toks)
}

// ---------- AST ----------
#[derive(Debug, Clone)]
enum Filter {
    Empty,
    Fuzzy(String),
    Exact(String),
    Index(i64, usize, usize), // value, span start, span len
    Slice(Option<i64>, Option<i64>, usize, usize),
}
impl Filter {
    fn span(&self) -> (usize, usize) {
        match self { Filter::Index(_, s, l) => (*s, *l), Filter::Slice(_, _, s, l) => (*s, *l), _ => (0, 0) }
    }
}

#[derive(Debug, Clone)]
enum Expr {
    Literal(Value),
    FunctionCall { name: String, args: Vec<Expr> },
    Property { name: String },
    Selector { name: String, filters: Vec<Filter> },
    Hierarchy { descendant: bool, left: Box<Expr>, right_name: String, right_filters: Vec<Filter> },
    Collection(Vec<Expr>),
    ObjectLit(Vec<(String, Expr)>),
    Union(Vec<Expr>),
    Pipe(Vec<Expr>),
    Not(Box<Expr>),
    Neg(Box<Expr>),
    Binary { op: String, left: Box<Expr>, right: Box<Expr> },
}

struct Parser {
    tokens: Vec<Token>,
    pos: usize,
    query: String,
}
impl Parser {
    fn cur(&self) -> &Token { &self.tokens[self.pos.min(self.tokens.len() - 1)] }
    fn advance(&mut self) -> Token { let t = self.cur().clone(); if self.pos < self.tokens.len() - 1 { self.pos += 1; } t }
    fn at_eof(&self) -> bool { matches!(self.cur().tok, Tok::Eof) }
    fn expect_err(&self, expected: &str) -> QueryError {
        let t = self.cur().clone();
        if matches!(t.tok, Tok::Eof) && self.query.is_empty() {
            return QueryError { message: format!("error: Expected {}, found end of input\n\n", expected) };
        }
        span_error(&self.query, &format!("Expected {}, found {}", expected, token_found_display(&t)), t.start, t.len.max(1), "unexpected token", None)
    }
    fn parse_query(&mut self) -> Result<Expr, QueryError> {
        if self.at_eof() {
            return Err(QueryError { message: "error: Expected expression, found end of input\n\n".to_string() });
        }
        let e = self.parse_union()?;
        if !self.at_eof() {
            return Err(self.expect_err("end of query"));
        }
        Ok(e)
    }
    fn parse_union(&mut self) -> Result<Expr, QueryError> {
        let mut branches = vec![self.parse_pipeline()?];
        while matches!(self.cur().tok, Tok::Comma) {
            self.advance();
            branches.push(self.parse_pipeline()?);
        }
        if branches.len() == 1 { Ok(branches.pop().unwrap()) } else { Ok(Expr::Union(branches)) }
    }
    fn parse_pipeline(&mut self) -> Result<Expr, QueryError> {
        let mut stages = vec![self.parse_binary()?];
        while matches!(self.cur().tok, Tok::Pipe) {
            self.advance();
            stages.push(self.parse_binary()?);
        }
        if stages.len() == 1 { Ok(stages.pop().unwrap()) } else { Ok(Expr::Pipe(stages)) }
    }
    fn parse_binary(&mut self) -> Result<Expr, QueryError> { self.parse_or() }
    fn parse_or(&mut self) -> Result<Expr, QueryError> {
        let mut left = self.parse_and()?;
        while matches!(&self.cur().tok, Tok::Ident(s) if s == "or") {
            self.advance();
            let right = self.parse_and()?;
            left = Expr::Binary { op: "or".into(), left: Box::new(left), right: Box::new(right) };
        }
        Ok(left)
    }
    fn parse_and(&mut self) -> Result<Expr, QueryError> {
        let mut left = self.parse_comparison()?;
        while matches!(&self.cur().tok, Tok::Ident(s) if s == "and") {
            self.advance();
            let right = self.parse_comparison()?;
            left = Expr::Binary { op: "and".into(), left: Box::new(left), right: Box::new(right) };
        }
        Ok(left)
    }
    fn is_hierarchy_ahead(&self) -> Option<bool> {
        // at current Greater token: check >> (two greaters) or >
        if matches!(self.cur().tok, Tok::Greater) {
            let next = self.tokens.get(self.pos + 1);
            let after_op_idx = if matches!(next.map(|t| &t.tok), Some(Tok::Greater)) { self.pos + 2 } else { self.pos + 1 };
            let descendant = after_op_idx == self.pos + 2;
            if let Some(t) = self.tokens.get(after_op_idx) {
                if matches!(t.tok, Tok::Dot) { return Some(descendant); }
            }
        }
        None
    }
    fn parse_comparison(&mut self) -> Result<Expr, QueryError> {
        let mut left = self.parse_add()?;
        loop {
            // hierarchy: left is selector/hierarchy and operator followed by '.'
            if matches!(self.cur().tok, Tok::Greater) {
                if let Some(descendant) = self.is_hierarchy_ahead() {
                    if matches!(left, Expr::Selector { .. } | Expr::Hierarchy { .. }) {
                        self.advance();
                        if descendant { self.advance(); }
                        // parse right selector
                        // expect dot
                        let (right_name, right_filters) = self.parse_hierarchy_right()?;
                        left = Expr::Hierarchy { descendant, left: Box::new(left), right_name, right_filters };
                        continue;
                    }
                }
            }
            let op = match &self.cur().tok {
                Tok::EqualEq => "==",
                Tok::NotEq => "!=",
                Tok::GreaterEq => ">=",
                Tok::LessEq => "<=",
                Tok::Greater => ">",
                Tok::Less => "<",
                _ => break,
            }.to_string();
            self.advance();
            let right = self.parse_add()?;
            left = Expr::Binary { op, left: Box::new(left), right: Box::new(right) };
        }
        Ok(left)
    }
    fn parse_hierarchy_right(&mut self) -> Result<(String, Vec<Filter>), QueryError> {
        // current should be Dot
        if !matches!(self.cur().tok, Tok::Dot) { return Err(self.expect_err("expression")); }
        self.advance(); // dot
        let name_tok = self.cur().clone();
        let name = match &name_tok.tok {
            Tok::Ident(s) => s.clone(),
            _ => return Err(self.expect_err("identifier")),
        };
        self.advance();
        let filters = self.parse_filters()?;
        // dotted continuation makes a bogus selector name (matches original returning empty)
        let mut full_name = name;
        while matches!(self.cur().tok, Tok::Dot) {
            // peek: if dot followed by identifier, consume as part of name
            let save = self.pos;
            self.advance();
            if let Tok::Ident(s) = &self.cur().tok {
                full_name = format!("{}.{}", full_name, s);
                self.advance();
                let _ = self.parse_filters()?;
            } else { self.pos = save; break; }
        }
        Ok((full_name, filters))
    }
    fn parse_add(&mut self) -> Result<Expr, QueryError> {
        let mut left = self.parse_mul()?;
        loop {
            let op = match &self.cur().tok { Tok::Plus => "+", Tok::Minus => "-", _ => break }.to_string();
            self.advance();
            let right = self.parse_mul()?;
            left = Expr::Binary { op, left: Box::new(left), right: Box::new(right) };
        }
        Ok(left)
    }
    fn parse_mul(&mut self) -> Result<Expr, QueryError> {
        let mut left = self.parse_unary()?;
        loop {
            let op = match &self.cur().tok { Tok::Star => "*", Tok::Slash => "/", Tok::Percent => "%", _ => break }.to_string();
            self.advance();
            let right = self.parse_unary()?;
            left = Expr::Binary { op, left: Box::new(left), right: Box::new(right) };
        }
        Ok(left)
    }
    fn parse_unary(&mut self) -> Result<Expr, QueryError> {
        if let Tok::Ident(s) = &self.cur().tok {
            if s == "not" {
                self.advance();
                let e = self.parse_unary()?;
                return Ok(Expr::Not(Box::new(e)));
            }
        }
        if matches!(self.cur().tok, Tok::Minus) {
            self.advance();
            let e = self.parse_unary()?;
            return Ok(Expr::Neg(Box::new(e)));
        }
        self.parse_primary()
    }
    fn parse_filters(&mut self) -> Result<Vec<Filter>, QueryError> {
        let mut filters = Vec::new();
        while matches!(self.cur().tok, Tok::LBracket) {
            let lb = self.advance(); // '['
            let start = lb.start;
            // empty
            if matches!(self.cur().tok, Tok::RBracket) { self.advance(); filters.push(Filter::Empty); continue; }
            match self.cur().tok.clone() {
                Tok::Str(s) => {
                    self.advance();
                    if !matches!(self.cur().tok, Tok::RBracket) { return Err(self.expect_err("']'")); }
                    let rb = self.advance();
                    let _ = rb;
                    filters.push(Filter::Exact(s));
                }
                Tok::Ident(s) => {
                    self.advance();
                    if !matches!(self.cur().tok, Tok::RBracket) { return Err(self.expect_err("']'")); }
                    self.advance();
                    filters.push(Filter::Fuzzy(s));
                }
                Tok::Number(_, _) | Tok::Minus => {
                    // parse signed number / slice
                    let first = self.parse_filter_signed_number(start)?;
                    if matches!(self.cur().tok, Tok::Colon) {
                        self.advance();
                        let second = if matches!(self.cur().tok, Tok::RBracket) { None } else { Some(self.parse_filter_signed_number(start)?) };
                        if !matches!(self.cur().tok, Tok::RBracket) { return Err(self.expect_err("']'")); }
                        let rb = self.advance();
                        let span_len = rb.start + 1 - start;
                        filters.push(Filter::Slice(first.map(|v| v), second, start, span_len));
                    } else if matches!(self.cur().tok, Tok::RBracket) {
                        let rb = self.advance();
                        let span_len = rb.start + 1 - start;
                        match first {
                            Some(v) => filters.push(Filter::Index(v, start, span_len)),
                            None => return Err(span_error(&self.query, "Invalid filter: expected filter pattern or index", start, span_len, "invalid filter", None)),
                        }
                    } else {
                        return Err(self.expect_err("']'"));
                    }
                }
                _ => {
                    // invalid filter: span to matching ] if present else 1
                    let mut len = 1usize;
                    // scan tokens for rbracket
                    let mut j = self.pos;
                    while j < self.tokens.len() {
                        if matches!(self.tokens[j].tok, Tok::RBracket) { len = self.tokens[j].start + 1 - start; break; }
                        if matches!(self.tokens[j].tok, Tok::Eof) { break; }
                        j += 1;
                    }
                    return Err(span_error(&self.query, "Invalid filter: expected filter pattern or index", start, len, "invalid filter", None));
                }
            }
        }
        Ok(filters)
    }
    fn parse_filter_signed_number(&mut self, bracket_start: usize) -> Result<Option<i64>, QueryError> {
        // handles Number token (may itself be negative), or Minus followed by Number
        let mut minuses = 0usize;
        while matches!(self.cur().tok, Tok::Minus) {
            minuses += 1;
            self.advance();
            if minuses > 1 {
                // invalid filter spanning bracket
                let mut len = 1usize;
                let mut j = self.pos;
                while j < self.tokens.len() {
                    if matches!(self.tokens[j].tok, Tok::RBracket) { len = self.tokens[j].start + 1 - bracket_start; break; }
                    if matches!(self.tokens[j].tok, Tok::Eof) { break; }
                    j += 1;
                }
                return Err(span_error(&self.query, "Invalid filter: expected filter pattern or index", bracket_start, len, "invalid filter", None));
            }
        }
        match self.cur().tok.clone() {
            Tok::Number(v, _) => {
                self.advance();
                let mut val = v;
                for _ in 0..minuses { val = -val; }
                Ok(Some(val as i64))
            }
            _ => Ok(None),
        }
    }
    fn parse_primary(&mut self) -> Result<Expr, QueryError> {
        let t = self.cur().clone();
        match t.tok {
            Tok::Number(v, _) => { self.advance(); Ok(Expr::Literal(Value::Number(v))) }
            Tok::Str(s) => { self.advance(); Ok(Expr::Literal(Value::String(s))) }
            Tok::LParen => {
                self.advance();
                let e = self.parse_pipeline()?;
                if !matches!(self.cur().tok, Tok::RParen) { return Err(self.expect_err("')'")); }
                self.advance();
                Ok(e)
            }
            Tok::LBracket => {
                self.advance();
                if matches!(self.cur().tok, Tok::RBracket) { self.advance(); return Ok(Expr::Collection(vec![])); }
                let inner = self.parse_union()?;
                if !matches!(self.cur().tok, Tok::RBracket) { return Err(self.expect_err("']'")); }
                self.advance();
                let branches = match inner { Expr::Union(b) => b, other => vec![other] };
                Ok(Expr::Collection(branches))
            }
            Tok::LBrace => {
                self.advance();
                let mut entries: Vec<(String, Expr)> = Vec::new();
                if matches!(self.cur().tok, Tok::RBrace) { self.advance(); return Ok(Expr::ObjectLit(entries)); }
                loop {
                    let key = match &self.cur().tok {
                        Tok::Ident(s) => { let k = s.clone(); self.advance(); k }
                        Tok::Str(s) => { let k = s.clone(); self.advance(); k }
                        _ => {
                            let tok = self.cur().clone();
                            return Err(span_error(&self.query, &format!("Expected one of identifier, string, found {}", token_found_display(&tok)), tok.start, tok.len.max(1), "unexpected token", None));
                        }
                    };
                    if !matches!(self.cur().tok, Tok::Colon) { return Err(self.expect_err("':'")); }
                    self.advance();
                    let val = self.parse_pipeline()?;
                    entries.push((key, val));
                    if matches!(self.cur().tok, Tok::Comma) { self.advance(); continue; }
                    break;
                }
                if !matches!(self.cur().tok, Tok::RBrace) { return Err(self.expect_err("'}'")); }
                self.advance();
                Ok(Expr::ObjectLit(entries))
            }
            Tok::Dot => {
                // dot chain
                // If next token is not ident, identity (or error for '.'?)
                let next = self.tokens.get(self.pos + 1).cloned();
                match next.map(|nt| nt.tok) {
                    Some(Tok::Ident(_)) => {
                        let mut segments: Vec<(String, Vec<Filter>)> = Vec::new();
                        loop {
                            self.advance(); // dot
                            let name_tok = self.cur().clone();
                            let name = match &name_tok.tok {
                                Tok::Ident(s) => s.clone(),
                                _ => return Err(self.expect_err("identifier")),
                            };
                            self.advance();
                            let filters = self.parse_filters()?;
                            segments.push((name, filters));
                            if matches!(self.cur().tok, Tok::Dot) {
                                // another segment follows only if dot+ident
                                let nn = self.tokens.get(self.pos + 1).cloned();
                                if matches!(nn.map(|x| x.tok), Some(Tok::Ident(_))) { continue; }
                                // dot followed by non-ident: will be handled by outer? treat as error in next loop iteration
                                // To match .h..text error, continue loop will attempt: dot then '.' -> expected identifier found '.'
                                // Force continuation:
                                // Peek if next is Dot, continue
                                let nn2 = self.tokens.get(self.pos + 1).cloned();
                                if matches!(nn2.map(|x| x.tok), Some(Tok::Dot)) { continue; }
                                break;
                            }
                            break;
                        }
                        if segments.len() == 1 {
                            let (name, filters) = segments.into_iter().next().unwrap();
                            if is_selector_name(&name) {
                                Ok(Expr::Selector { name, filters })
                            } else {
                                // property with possible filters attached? Filters on a property are ignored like selector application?
                                // Represent as Selector with unknown handling? Use Property if no filters; if filters exist, still Property (filters ignored)
                                let _ = filters;
                                Ok(Expr::Property { name })
                            }
                        } else {
                            let (name, _) = segments.into_iter().last().unwrap();
                            Ok(Expr::Property { name })
                        }
                    }
                    Some(Tok::Dot) => {
                        // '..' -> expected identifier found '.'
                        self.advance(); // first dot
                        Err(self.expect_err("identifier"))
                    }
                    _ => {
                        self.advance(); // consume dot as identity
                        Ok(Expr::Literal(Value::Null)) // placeholder replaced below
                        // identity handled via special marker: use Property with empty name
                    }
                }
            }
            Tok::Ident(name) => {
                match name.as_str() {
                    "true" => { self.advance(); Ok(Expr::Literal(Value::Bool(true))) }
                    "false" => { self.advance(); Ok(Expr::Literal(Value::Bool(false))) }
                    "null" => { self.advance(); Ok(Expr::Literal(Value::Null)) }
                    _ => {
                        self.advance();
                        let mut args: Vec<Expr> = Vec::new();
                        if matches!(self.cur().tok, Tok::LParen) {
                            self.advance();
                            if matches!(self.cur().tok, Tok::RParen) { self.advance(); }
                            else {
                                loop {
                                    let a = self.parse_pipeline()?;
                                    args.push(a);
                                    if matches!(self.cur().tok, Tok::Comma) { self.advance(); continue; }
                                    break;
                                }
                                if !matches!(self.cur().tok, Tok::RParen) { return Err(self.expect_err("')'")); }
                                self.advance();
                            }
                        }
                        Ok(Expr::FunctionCall { name, args })
                    }
                }
            }
            _ => Err(self.expect_err("expression")),
        }
    }
}

// identity placeholder: Expr::Literal(Null) from '.' needs special handling.
// We detect it in evaluation by a thread-local? Instead, parser replaces '.' identity with FunctionCall "identity" internally.
fn is_selector_name(name: &str) -> bool {
    matches!(name,
        "h" | "heading" | "headings" | "headers" | "h1" | "h2" | "h3" | "h4" | "h5" | "h6"
        | "code" | "pre" | "codeblock" | "codeblocks"
        | "link" | "links" | "a"
        | "img" | "image" | "images"
        | "table" | "tables"
        | "list" | "lists" | "ul" | "ol"
        | "blockquote" | "blockquotes" | "quote" | "quotes"
        | "p" | "para" | "paragraph" | "paragraphs"
        | "frontmatter" | "yaml")
}

const FUNCTION_NAMES: &[&str] = &[
    "count","length","len","size","first","last","head","limit","take","skip","drop","nth","reverse","sort","sort_by","unique","flatten","group_by","min","max","add","stats","levels","langs","types","text","upper","lower","trim","split","join","replace","slugify","lines","words","chars","select","where","filter","contains","includes","startswith","endswith","matches","any","all","not","content","md","url","href","src","lang","language","type","keys","values","has","empty","debug","ascii_downcase","ascii_upcase",
];

fn function_arity(name: &str) -> Option<(usize, usize)> {
    match name {
        "count"|"length"|"len"|"size"|"first"|"last"|"head"|"reverse"|"sort"|"unique"|"flatten"|"min"|"max"|"add"|"stats"|"levels"|"langs"|"types"|"text"|"upper"|"lower"|"trim"|"slugify"|"lines"|"words"|"chars"|"content"|"md"|"url"|"href"|"src"|"lang"|"language"|"type"|"keys"|"values"|"empty"|"debug"|"ascii_downcase"|"ascii_upcase" => Some((0,0)),
        "limit"|"take"|"skip"|"drop"|"nth"|"sort_by"|"group_by"|"split"|"join"|"select"|"where"|"filter"|"contains"|"includes"|"startswith"|"endswith"|"matches"|"any"|"all"|"has" => Some((1,1)),
        "replace" => Some((2,2)),
        _ => None,
    }
}

fn levenshtein(a: &str, b: &str) -> usize {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    let mut prev: Vec<usize> = (0..=b.len()).collect();
    let mut cur = vec![0usize; b.len() + 1];
    for i in 1..=a.len() {
        cur[0] = i;
        for j in 1..=b.len() {
            let cost = if a[i - 1] == b[j - 1] { 0 } else { 1 };
            cur[j] = (prev[j] + 1).min(cur[j - 1] + 1).min(prev[j - 1] + cost);
        }
        std::mem::swap(&mut prev, &mut cur);
    }
    prev[b.len()]
}

fn unknown_function_error(name: &str) -> QueryError {
    let mut candidates: Vec<(usize, &str)> = FUNCTION_NAMES.iter()
        .map(|&f| (levenshtein(name, f), f))
        .filter(|(d, _)| *d <= 2)
        .collect();
    candidates.sort_by(|a, b| a.0.cmp(&b.0).then(a.1.cmp(b.1)));
    candidates.truncate(3);
    // Also include "null" keyword for very close names
    let mut names: Vec<String> = candidates.iter().map(|(_, f)| f.to_string()).collect();
    if levenshtein(name, "null") <= 2 && !names.iter().any(|x| x == "null") {
        // insert keeping distance order roughly
        if names.len() < 3 { names.push("null".to_string()); }
    }
    if names.is_empty() {
        runtime_error(format!("Unknown function '{}'", name))
    } else {
        let joined = names.iter().map(|n| format!("'{}'", n)).collect::<Vec<_>>().join(" or ");
        QueryError { message: format!("error: Unknown function '{}'\n  |\n  = help: did you mean {}?\n\n", name, joined) }
    }
}

// ---------- Evaluation ----------
pub struct Evaluator<'a> { ctx: &'a QueryContext }

pub fn run_query(doc: &Document, query: &str) -> Result<Vec<Value>, QueryError> {
    let ctx = QueryContext::build(doc);
    let tokens = lex(query)?;
    let mut parser = Parser { tokens, pos: 0, query: query.to_string() };
    let expr = parser.parse_query()?;
    // replace '.' identity literal placeholder: our parser returns Literal(Null) for '.' alone;
    // handle by checking if query trimmed segments... Instead evaluation treats a Literal(Null)
    // that came from '.' – ambiguous with null literal. We intercept: if expr is Literal(Null)
    // and query contains a '.' that isn't part of number/string, hard. Simpler: Parser already
    // cannot distinguish. We handle top-level by re-checking: if the parsed expr is a Pipe etc.
    // it may contain identity stages. To fix, evaluator's eval for Literal(Null) returns Null,
    // but identity stages are represented as Property with empty name – see parser patch below.
    let ev = Evaluator { ctx: &ctx };
    let input = ctx.document_value();
    ev.eval_vec(&expr, &input)
}

impl<'a> Evaluator<'a> {
    fn eval_vec(&self, expr: &Expr, input: &Value) -> Result<Vec<Value>, QueryError> {
        match expr {
            Expr::Pipe(stages) => {
                let mut current = vec![input.clone()];
                for stage in stages {
                    let mut next = Vec::new();
                    for v in &current { next.extend(self.eval_vec(stage, v)?); }
                    current = next;
                }
                Ok(current)
            }
            Expr::Union(branches) => {
                let mut out = Vec::new();
                for b in branches { out.extend(self.eval_vec(b, input)?); }
                Ok(out)
            }
            Expr::Collection(branches) => {
                let mut items = Vec::new();
                for b in branches { items.extend(self.eval_vec(b, input)?); }
                Ok(vec![Value::Array(items)])
            }
            Expr::ObjectLit(entries) => {
                let mut obj: Vec<(String, Value)> = Vec::new();
                for (k, e) in entries {
                    let v = self.eval_scalar(e, input)?;
                    obj.push((k.clone(), v));
                }
                Ok(vec![Value::Object(obj)])
            }
            Expr::Selector { name, filters } => {
                let base = self.ctx.selector_elements(name).unwrap_or_default();
                let filtered = self.apply_filters(base, filters)?;
                Ok(filtered)
            }
            Expr::Hierarchy { descendant, left, right_name, right_filters } => {
                let left_vals = self.eval_vec(left, input)?;
                let mut out = Vec::new();
                for lv in &left_vals {
                    if let Value::Heading(h) = lv {
                        // heading right?
                        if let Some(mut elems) = self.ctx.selector_elements(right_name) {
                            let is_heading_selector = self.ctx.selector_elements(right_name).is_some()
                                && matches!(elems.first(), Some(Value::Heading(_)) | None)
                                && (is_heading_selector_name(right_name));
                            if is_heading_selector {
                                let candidate_idxs: Vec<usize> = if *descendant {
                                    self.descendants_of(h.index)
                                } else {
                                    self.ctx.children_map.get(h.index).cloned().unwrap_or_default()
                                };
                                let cand: Vec<Value> = candidate_idxs.iter().map(|&i| Value::Heading(self.ctx.headings[i].clone())).collect();
                                elems = cand;
                            }
                            out.extend(self.apply_filters(elems, right_filters)?);
                        } else {
                            // unknown selector on right: no output
                        }
                    }
                }
                Ok(out)
            }
            Expr::Property { name } => {
                if name.is_empty() { return Ok(vec![input.clone()]); }
                let v = self.get_property(input, name)?;
                Ok(vec![v])
            }
            Expr::FunctionCall { name, args } => {
                match self.apply_function(name, args, input)? {
                    Some(v) => Ok(vec![v]),
                    None => Ok(vec![]),
                }
            }
            Expr::Literal(v) => {
                // '.' identity was encoded as Literal(Null) by parser when alone; distinguish
                // by a hack: if v is Null and the original token was '.', the parser actually
                // returns Property with empty name (see below). Literal Null here is genuine null.
                Ok(vec![v.clone()])
            }
            Expr::Not(e) => {
                let v = self.eval_scalar(e, input)?;
                Ok(vec![Value::Bool(!v.is_truthy())])
            }
            Expr::Neg(e) => {
                let v = self.eval_scalar(e, input)?;
                match v { Value::Number(n) => Ok(vec![Value::Number(-n)]), _ => Ok(vec![Value::Null]) }
            }
            Expr::Binary { op, left, right } => {
                let v = self.eval_binary(op, left, right, input)?;
                Ok(vec![v])
            }
        }
    }
    fn descendants_of(&self, idx: usize) -> Vec<usize> {
        let mut out = Vec::new();
        let mut stack: Vec<usize> = self.ctx.children_map.get(idx).cloned().unwrap_or_default();
        // preorder: children in order, each followed by its descendants
        let mut result = Vec::new();
        fn walk(i: usize, ctx: &QueryContext, out: &mut Vec<usize>) {
            out.push(i);
            if let Some(ch) = ctx.children_map.get(i) { for &c in ch { walk(c, ctx, out); } }
        }
        for c in stack.drain(..) { walk(c, self.ctx, &mut result); }
        let _ = &mut out;
        result
    }
    fn eval_scalar(&self, expr: &Expr, input: &Value) -> Result<Value, QueryError> {
        // special case: identity '.' literal placeholder handling is via Property empty.
        let vals = self.eval_vec(expr, input)?;
        Ok(vals.into_iter().next().unwrap_or(Value::Null))
    }
    fn eval_binary(&self, op: &str, left: &Expr, right: &Expr, input: &Value) -> Result<Value, QueryError> {
        match op {
            "and" => {
                let l = self.eval_scalar(left, input)?;
                if !l.is_truthy() { return Ok(Value::Bool(false)); }
                let r = self.eval_scalar(right, input)?;
                Ok(Value::Bool(r.is_truthy()))
            }
            "or" => {
                let l = self.eval_scalar(left, input)?;
                if l.is_truthy() { return Ok(Value::Bool(true)); }
                let r = self.eval_scalar(right, input)?;
                Ok(Value::Bool(r.is_truthy()))
            }
            "+" => {
                let l = self.eval_scalar(left, input)?;
                let r = self.eval_scalar(right, input)?;
                match (&l, &r) {
                    (Value::Number(a), Value::Number(b)) => Ok(Value::Number(a + b)),
                    (Value::Array(a), Value::Array(b)) => { let mut x = a.clone(); x.extend(b.clone()); Ok(Value::Array(x)) }
                    (Value::String(_), _) | (_, Value::String(_)) => Ok(Value::String(format!("{}{}", text_of(&l), text_of(&r)))),
                    _ => Ok(Value::Null),
                }
            }
            "-" | "*" | "/" | "%" => {
                let l = self.eval_scalar(left, input)?;
                let r = self.eval_scalar(right, input)?;
                // string repetition
                if op == "*" {
                    if let (Value::String(s), Value::Number(n)) = (&l, &r) {
                        if *n <= 0.0 { return Ok(Value::String(String::new())); }
                        return Ok(Value::String(s.repeat(*n as usize)));
                    }
                }
                match (&l, &r) {
                    (Value::Number(a), Value::Number(b)) => {
                        if (op == "/" || op == "%") && *b == 0.0 { return Err(runtime_error("Division by zero")); }
                        Ok(Value::Number(match op { "-" => a - b, "*" => a * b, "/" => a / b, "%" => a % b, _ => unreachable!() }))
                    }
                    _ => Ok(Value::Null),
                }
            }
            "==" | "!=" => {
                let l = self.eval_scalar(left, input)?;
                let r = self.eval_scalar(right, input)?;
                let eq = values_equal(&l, &r);
                Ok(Value::Bool(if op == "==" { eq } else { !eq }))
            }
            ">" | "<" | ">=" | "<=" => {
                let l = self.eval_scalar(left, input)?;
                let r = self.eval_scalar(right, input)?;
                let ord = match (&l, &r) {
                    (Value::Number(a), Value::Number(b)) => a.partial_cmp(b),
                    (Value::String(a), Value::String(b)) => Some(a.cmp(b)),
                    _ => None,
                };
                let res = match (ord, op) {
                    (Some(Ordering::Greater), ">") => true,
                    (Some(Ordering::Less), "<") => true,
                    (Some(Ordering::Greater), ">=") => true,
                    (Some(Ordering::Less), "<=") => true,
                    (Some(Ordering::Equal), ">=") => true,
                    (Some(Ordering::Equal), "<=") => true,
                    _ => false,
                };
                Ok(Value::Bool(res))
            }
            _ => Ok(Value::Null),
        }
    }
    fn apply_filters(&self, base: Vec<Value>, filters: &[Filter]) -> Result<Vec<Value>, QueryError> {
        let mut patterned = base.clone();
        let mut selection: Option<Filter> = None;
        let mut seen_indexing = false;
        for f in filters {
            match f {
                Filter::Empty => { patterned = base.clone(); selection = None; seen_indexing = false; }
                Filter::Fuzzy(p) | Filter::Exact(p) => {
                    if seen_indexing {
                        let (s, l) = (f.span().0, f.span().1);
                        // span for pattern-after-index needs the bracket group; stored span is 0 for fuzzy/exact.
                        // We stored bracket span in Index/Slice only; approximate using filter's own storage:
                        let _ = (s, l);
                        return Err(runtime_error("Invalid filter: expected index, got filter"));
                        // NOTE: replaced below in apply_filters_with_query when query available
                    }
                    let exact = matches!(f, Filter::Exact(_));
                    patterned.retain(|el| filter_matches(el, p, exact));
                }
                Filter::Index(_, _, _) | Filter::Slice(_, _, _, _) => { selection = Some(f.clone()); seen_indexing = true; }
            }
        }
        let result = match selection {
            Some(Filter::Index(idx, _, _)) => {
                let len = patterned.len() as i64;
                let resolved = if idx < 0 { len + idx } else { idx };
                if resolved >= 0 && resolved < len { vec![patterned[resolved as usize].clone()] } else { vec![] }
            }
            Some(Filter::Slice(a, b, _, _)) => slice_values(&patterned, a, b),
            _ => patterned,
        };
        Ok(result)
    }
    fn get_property(&self, input: &Value, name: &str) -> Result<Value, QueryError> {
        match input {
            Value::Document { content, heading_count, word_count } => {
                match name {
                    "text" | "content" => Ok(Value::String(content.clone())),
                    "headings" => Ok(Value::Number(*heading_count as f64)),
                    "words" | "word_count" => Ok(Value::Number(*word_count as f64)),
                    _ => Err(runtime_error(format!("Property '{}' not found on document", name))),
                }
            }
            Value::Heading(h) => {
                match name {
                    "text" => Ok(Value::String(h.text.clone())),
                    "content" => Ok(Value::String(h.content.clone())),
                    "md" => Ok(Value::String(h.raw_md.clone())),
                    "level" => Ok(Value::Number(h.level as f64)),
                    "line" => Ok(Value::Number(h.line as f64)),
                    "slug" => Ok(Value::String(slugify(&h.text))),
                    _ => Err(runtime_error(format!("Property '{}' not found on heading", name))),
                }
            }
            Value::Code(c) => {
                match name {
                    "text" | "content" => Ok(Value::String(c.content.clone())),
                    "lang" | "language" => Ok(Value::String(c.language.clone().unwrap_or_default())),
                    "start_line" => Ok(Value::Number(c.start_line as f64)),
                    "end_line" => Ok(Value::Number(c.end_line as f64)),
                    _ => Err(runtime_error(format!("Property '{}' not found on code", name))),
                }
            }
            Value::Link(l) => {
                match name {
                    "text" => Ok(Value::String(l.text.clone())),
                    "url" => Ok(Value::String(l.url.clone())),
                    "type" => Ok(Value::String(l.link_type.as_str().to_string())),
                    _ => Err(runtime_error(format!("Property '{}' not found on link", name))),
                }
            }
            Value::Image(im) => {
                match name {
                    "text" | "alt" => Ok(Value::String(im.alt.clone())),
                    "src" | "url" => Ok(Value::String(im.src.clone())),
                    _ => Err(runtime_error(format!("Property '{}' not found on image", name))),
                }
            }
            Value::Table(t) => {
                match name {
                    "headers" => Ok(Value::Array(t.headers.iter().map(|s| Value::String(s.clone())).collect())),
                    "rows" => Ok(Value::Array(t.rows.iter().map(|r| Value::Array(r.iter().map(|s| Value::String(s.clone())).collect())).collect())),
                    _ => Err(runtime_error(format!("Property '{}' not found on table", name))),
                }
            }
            Value::List(l) => {
                match name {
                    "items" => Ok(Value::Array(l.items.iter().map(|(c, _)| Value::String(c.clone())).collect())),
                    "ordered" => Ok(Value::Bool(l.ordered)),
                    _ => Err(runtime_error(format!("Property '{}' not found on list", name))),
                }
            }
            Value::Object(entries) => {
                for (k, v) in entries { if k == name { return Ok(v.clone()); } }
                Err(runtime_error(format!("Property '{}' not found on object", name)))
            }
            other => Err(runtime_error(format!("Property '{}' not found on {}", name, other.type_name()))),
        }
    }
    fn eval_arg_values(&self, args: &[Expr], input: &Value) -> Result<Vec<Value>, QueryError> {
        let mut out = Vec::new();
        for a in args { out.push(self.eval_scalar(a, input)?); }
        Ok(out)
    }
    fn apply_function(&self, name: &str, args: &[Expr], input: &Value) -> Result<Option<Value>, QueryError> {
        let arity = match function_arity(name) {
            Some(a) => a,
            None => return Err(unknown_function_error(name)),
        };
        if args.len() < arity.0 || args.len() > arity.1 {
            return Err(runtime_error(format!("Function '{}' expects {}..={} arguments, got {}", name, arity.0, arity.1, args.len())));
        }
        // helper closures not possible easily; inline arg evaluation
        match name {
            "count" | "length" | "len" | "size" => {
                let n = match input {
                    Value::Array(a) => a.len(),
                    Value::String(s) => s.chars().count(),
                    Value::Object(e) => e.len(),
                    _ => 1,
                };
                Ok(Some(Value::Number(n as f64)))
            }
            "first" | "head" => {
                match input { Value::Array(a) => Ok(Some(a.first().cloned().unwrap_or(Value::Null))), _ => Ok(Some(input.clone())) }
            }
            "last" => {
                match input { Value::Array(a) => Ok(Some(a.last().cloned().unwrap_or(Value::Null))), _ => Ok(Some(input.clone())) }
            }
            "limit" | "take" => {
                let arg = self.eval_scalar(&args[0], input)?;
                if let Value::Array(a) = input {
                    let n = to_usize(&arg);
                    Ok(Some(Value::Array(a.iter().take(n).cloned().collect())))
                } else { Ok(Some(input.clone())) }
            }
            "skip" | "drop" => {
                let arg = self.eval_scalar(&args[0], input)?;
                if let Value::Array(a) = input {
                    let n = to_usize(&arg);
                    Ok(Some(Value::Array(a.iter().skip(n).cloned().collect())))
                } else { Ok(Some(input.clone())) }
            }
            "nth" => {
                let arg = self.eval_scalar(&args[0], input)?;
                if let Value::Array(a) = input {
                    let idx = to_i64(&arg);
                    let len = a.len() as i64;
                    let resolved = if idx < 0 { len + idx } else { idx };
                    if resolved >= 0 && resolved < len { Ok(Some(a[resolved as usize].clone())) } else { Ok(None) }
                } else { Ok(None) }
            }
            "reverse" => {
                if let Value::Array(a) = input { let mut x = a.clone(); x.reverse(); Ok(Some(Value::Array(x))) }
                else { Ok(Some(input.clone())) }
            }
            "sort" => {
                if let Value::Array(a) = input { let mut x = a.clone(); sort_values(&mut x); Ok(Some(Value::Array(x))) }
                else { Ok(Some(input.clone())) }
            }
            "sort_by" => {
                let arg = self.eval_scalar(&args[0], input)?;
                let key = if let Value::String(s) = &arg { s.clone() } else { text_of(&arg) };
                if let Value::Array(a) = input {
                    let mut x = a.clone();
                    if key == "level" {
                        x.sort_by_key(|v| match v { Value::Heading(h) => h.level as i64, _ => 0 });
                    } else {
                        sort_values(&mut x);
                    }
                    Ok(Some(Value::Array(x)))
                } else { Ok(Some(input.clone())) }
            }
            "group_by" => {
                let _arg = self.eval_scalar(&args[0], input)?;
                if let Value::Array(a) = input {
                    let mut groups: Vec<(String, Vec<Value>)> = Vec::new();
                    for el in a {
                        let key = group_key(el);
                        if let Some(g) = groups.iter_mut().find(|(k, _)| *k == key) { g.1.push(el.clone()); }
                        else { groups.push((key, vec![el.clone()])); }
                    }
                    Ok(Some(Value::Object(groups.into_iter().map(|(k, v)| (k, Value::Array(v))).collect())))
                } else { Ok(Some(input.clone())) }
            }
            "unique" => {
                if let Value::Array(a) = input {
                    let mut seen: Vec<String> = Vec::new();
                    let mut out: Vec<Value> = Vec::new();
                    for el in a {
                        let k = serde_json::to_string(&value_to_json(el)).unwrap();
                        if !seen.contains(&k) { seen.push(k); out.push(el.clone()); }
                    }
                    Ok(Some(Value::Array(out)))
                } else { Ok(Some(input.clone())) }
            }
            "flatten" => {
                if let Value::Array(a) = input {
                    fn flat(a: &[Value], out: &mut Vec<Value>) { for v in a { if let Value::Array(inner) = v { flat(inner, out); } else { out.push(v.clone()); } } }
                    let mut out = Vec::new(); flat(a, &mut out);
                    Ok(Some(Value::Array(out)))
                } else { Ok(Some(input.clone())) }
            }
            "min" => {
                if let Value::Array(a) = input {
                    let nums: Vec<f64> = a.iter().filter_map(|v| if let Value::Number(n) = v { Some(*n) } else { None }).collect();
                    if nums.len() == a.len() && !nums.is_empty() { Ok(Some(Value::Number(nums.iter().cloned().fold(f64::INFINITY, f64::min)))) }
                    else { Ok(Some(Value::Null)) }
                } else { Ok(Some(Value::Null)) }
            }
            "max" => {
                if let Value::Array(a) = input {
                    let nums: Vec<f64> = a.iter().filter_map(|v| if let Value::Number(n) = v { Some(*n) } else { None }).collect();
                    if nums.len() == a.len() && !nums.is_empty() { Ok(Some(Value::Number(nums.iter().cloned().fold(f64::NEG_INFINITY, f64::max)))) }
                    else { Ok(Some(Value::Null)) }
                } else { Ok(Some(Value::Null)) }
            }
            "add" => {
                if let Value::Array(a) = input {
                    if !a.is_empty() && a.iter().all(|v| matches!(v, Value::Number(_))) {
                        let sum: f64 = a.iter().map(|v| if let Value::Number(n) = v { *n } else { 0.0 }).sum();
                        Ok(Some(Value::Number(sum)))
                    } else {
                        Ok(Some(Value::String(a.iter().map(text_of).collect::<Vec<_>>().join(""))))
                    }
                } else { Ok(Some(input.clone())) }
            }
            "stats" => Ok(Some(self.ctx.stats_object())),
            "levels" => Ok(Some(self.ctx.levels_object())),
            "langs" => Ok(Some(self.ctx.langs_object())),
            "types" => Ok(Some(self.ctx.types_object())),
            "text" => Ok(Some(Value::String(text_of(input)))),
            "upper" => Ok(Some(Value::String(text_of(input).to_uppercase()))),
            "lower" => Ok(Some(Value::String(text_of(input).to_lowercase()))),
            "ascii_upcase" => Ok(Some(Value::String(text_of(input).to_ascii_uppercase()))),
            "ascii_downcase" => Ok(Some(Value::String(text_of(input).to_ascii_lowercase()))),
            "trim" => Ok(Some(Value::String(text_of(input).trim().to_string()))),
            "slugify" => Ok(Some(Value::String(slugify(&text_of(input))))),
            "lines" => Ok(Some(Value::Number(text_of(input).lines().count() as f64))),
            "words" => Ok(Some(Value::Number(text_of(input).split_whitespace().count() as f64))),
            "chars" => Ok(Some(Value::Number(text_of(input).chars().count() as f64))),
            "content" => {
                match input {
                    Value::Heading(h) => Ok(Some(Value::String(h.content.clone()))),
                    Value::Document { content, .. } => Ok(Some(Value::String(content.clone()))),
                    _ => Ok(Some(Value::String(text_of(input)))),
                }
            }
            "md" => {
                match input {
                    Value::Heading(h) => Ok(Some(Value::String(h.raw_md.clone()))),
                    Value::Document { content, .. } => Ok(Some(Value::String(content.clone()))),
                    _ => Ok(Some(Value::String(text_of(input)))),
                }
            }
            "url" | "href" => {
                match input { Value::Link(l) => Ok(Some(Value::String(l.url.clone()))), Value::Image(im) => Ok(Some(Value::String(im.src.clone()))), _ => Ok(Some(Value::Null)) }
            }
            "src" => {
                match input { Value::Image(im) => Ok(Some(Value::String(im.src.clone()))), _ => Ok(Some(Value::Null)) }
            }
            "lang" | "language" => {
                match input { Value::Code(c) => Ok(Some(Value::String(c.language.clone().unwrap_or_default()))), _ => Ok(Some(Value::Null)) }
            }
            "type" => Ok(Some(Value::String(input.type_name().to_string()))),
            "keys" => {
                match input {
                    Value::Object(e) => Ok(Some(Value::Array(e.iter().map(|(k, _)| Value::String(k.clone())).collect()))),
                    Value::Array(a) => Ok(Some(Value::Array((0..a.len()).map(|i| Value::Number(i as f64)).collect()))),
                    _ => Ok(Some(Value::Array(vec![]))),
                }
            }
            "values" => {
                match input {
                    Value::Object(e) => Ok(Some(Value::Array(e.iter().map(|(_, v)| v.clone()).collect()))),
                    Value::Array(a) => Ok(Some(Value::Array(a.clone()))),
                    _ => Ok(Some(Value::Array(vec![]))),
                }
            }
            "has" => {
                let arg = self.eval_scalar(&args[0], input)?;
                let key = text_of(&arg);
                match input { Value::Object(e) => Ok(Some(Value::Bool(e.iter().any(|(k, _)| *k == key)))), _ => Ok(Some(Value::Bool(false))) }
            }
            "empty" => {
                let e = match input {
                    Value::String(s) => s.is_empty(),
                    Value::Array(a) => a.is_empty(),
                    Value::Object(e) => e.is_empty(),
                    Value::Null => true,
                    _ => false,
                };
                Ok(Some(Value::Bool(e)))
            }
            "debug" => {
                eprintln!("[DEBUG] {}", debug_value(input));
                Ok(Some(input.clone()))
            }
            "split" => {
                let arg = self.eval_scalar(&args[0], input)?;
                let sep = text_of(&arg);
                let text = text_of(input);
                if sep.is_empty() {
                    Ok(Some(Value::Array(text.chars().map(|c| Value::String(c.to_string())).collect())))
                } else {
                    Ok(Some(Value::Array(text.split(&sep).map(|s| Value::String(s.to_string())).collect())))
                }
            }
            "join" => {
                let arg = self.eval_scalar(&args[0], input)?;
                let sep = text_of(&arg);
                if let Value::Array(a) = input {
                    Ok(Some(Value::String(a.iter().map(text_of).collect::<Vec<_>>().join(&sep))))
                } else { Ok(Some(Value::String(text_of(input)))) }
            }
            "replace" => {
                let args_v = self.eval_arg_values(args, input)?;
                let from = text_of(&args_v[0]);
                let to = text_of(&args_v[1]);
                Ok(Some(Value::String(text_of(input).replace(&from, &to))))
            }
            "select" | "where" | "filter" => {
                let cond = self.eval_scalar(&args[0], input)?;
                if cond.is_truthy() { Ok(Some(input.clone())) } else { Ok(None) }
            }
            "contains" | "includes" => {
                let arg = self.eval_scalar(&args[0], input)?;
                let needle = text_of(&arg).to_lowercase();
                Ok(Some(Value::Bool(text_of(input).to_lowercase().contains(&needle))))
            }
            "startswith" => {
                let arg = self.eval_scalar(&args[0], input)?;
                Ok(Some(Value::Bool(text_of(input).to_lowercase().starts_with(&text_of(&arg).to_lowercase()))))
            }
            "endswith" => {
                let arg = self.eval_scalar(&args[0], input)?;
                Ok(Some(Value::Bool(text_of(input).to_lowercase().ends_with(&text_of(&arg).to_lowercase()))))
            }
            "matches" => {
                let arg = self.eval_scalar(&args[0], input)?;
                let pat = text_of(&arg);
                match Regex::new(&pat) { Ok(re) => Ok(Some(Value::Bool(re.is_match(&text_of(input))))), Err(_) => Ok(Some(Value::Bool(false))) }
            }
            "any" => {
                let arg_val = self.eval_scalar(&args[0], input)?;
                if let Value::Array(a) = input {
                    Ok(Some(Value::Bool(a.iter().any(|v| v.is_truthy()))))
                } else { Ok(Some(Value::Bool(arg_val.is_truthy()))) }
            }
            "all" => {
                let _arg_val = self.eval_scalar(&args[0], input)?;
                if let Value::Array(a) = input {
                    Ok(Some(Value::Bool(a.iter().all(|v| v.is_truthy()))))
                } else { Ok(Some(Value::Bool(input.is_truthy()))) }
            }
            _ => Err(unknown_function_error(name)),
        }
    }
}

fn is_heading_selector_name(name: &str) -> bool {
    matches!(name, "h" | "heading" | "headings" | "headers" | "h1" | "h2" | "h3" | "h4" | "h5" | "h6")
}

fn filter_matches(el: &Value, pattern: &str, exact: bool) -> bool {
    if let Value::Link(l) = el {
        if !exact {
            let p = pattern.to_lowercase();
            if p == "external" || p == "anchor" || p == "relative" { return l.link_type.as_str() == p; }
        }
    }
    let text = text_of(el);
    if exact { text.eq_ignore_ascii_case(pattern) } else { text.to_lowercase().contains(&pattern.to_lowercase()) }
}

fn slice_values(values: &[Value], start: Option<i64>, end: Option<i64>) -> Vec<Value> {
    let len = values.len() as i64;
    let resolve = |v: i64| -> i64 { if v < 0 { (len + v).max(0) } else { v.min(len) } };
    let s = start.map(resolve).unwrap_or(0);
    let e = end.map(resolve).unwrap_or(len);
    if s >= e || s >= len { return Vec::new(); }
    values[s as usize..e as usize].to_vec()
}

fn to_usize(v: &Value) -> usize {
    match v { Value::Number(n) => *n as usize, _ => 0 }
}
fn to_i64(v: &Value) -> i64 {
    match v { Value::Number(n) => *n as i64, _ => 0 }
}

fn sort_values(values: &mut [Value]) {
    values.sort_by(|a, b| {
        if let (Value::Number(x), Value::Number(y)) = (a, b) { return x.partial_cmp(y).unwrap_or(Ordering::Equal); }
        text_of(a).cmp(&text_of(b))
    });
}

fn group_key(v: &Value) -> String {
    match v {
        Value::Heading(h) => format!("h{}", h.level),
        Value::Code(c) => c.language.clone().unwrap_or_else(|| "none".to_string()),
        _ => text_of(v),
    }
}

fn values_equal(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Number(x), Value::Number(y)) => x == y,
        (Value::Number(x), Value::String(s)) | (Value::String(s), Value::Number(x)) => {
            s.trim().parse::<f64>().map(|y| *x == y).unwrap_or(false)
        }
        (Value::String(x), Value::String(y)) => x == y,
        (Value::Bool(x), Value::Bool(y)) => x == y,
        (Value::Null, Value::Null) => true,
        (Value::Array(x), Value::Array(y)) => x.len() == y.len() && x.iter().zip(y.iter()).all(|(u, v)| values_equal(u, v)),
        _ => {
            // elements/objects compared by json representation
            if a.type_name() != b.type_name() { return false; }
            serde_json::to_string(&value_to_json(a)).unwrap_or_default() == serde_json::to_string(&value_to_json(b)).unwrap_or_default()
        }
    }
}

fn debug_value(v: &Value) -> String {
    match v {
        Value::Heading(h) => format!("Heading(HeadingValue {{ level: {}, text: {:?}, offset: {}, line: {}, content: {:?}, raw_md: {:?}, index: {} }})", h.level, h.text, h.offset, h.line, h.content, h.raw_md, h.index),
        Value::Code(c) => format!("Code(CodeValue {{ language: {}, content: {:?}, start_line: {}, end_line: {} }})", match &c.language { Some(l) => format!("Some({:?})", l), None => "None".to_string() }, c.content, c.start_line, c.end_line),
        Value::Link(l) => format!("Link(LinkValue {{ text: {:?}, url: {:?}, link_type: {}, offset: {} }})", l.text, l.url, l.link_type.debug_name(), l.offset),
        Value::Table(t) => format!("Table(TableValue {{ headers: {:?}, rows: {:?}, alignments: {:?} }})", t.headers, t.rows, t.alignments),
        Value::List(l) => {
            let items: Vec<String> = l.items.iter().map(|(c, checked)| format!("ListItemValue {{ content: {:?}, checked: {} }}", c, match checked { Some(true) => "Some(true)".to_string(), Some(false) => "Some(false)".to_string(), None => "None".to_string() })).collect();
            format!("List(ListValue {{ ordered: {}, items: [{}] }})", l.ordered, items.join(", "))
        }
        Value::Document { content, heading_count, word_count } => format!("Document(DocumentValue {{ content: {:?}, heading_count: {}, word_count: {} }})", content, heading_count, word_count),
        Value::String(s) => format!("String({:?})", s),
        Value::Number(n) => format!("Number({:?})", n),
        Value::Bool(b) => format!("Bool({:?})", b),
        Value::Null => "Null".to_string(),
        Value::Array(a) => format!("Array([{}])", a.iter().map(debug_value).collect::<Vec<_>>().join(", ")),
        Value::Object(e) => format!("Object({{{}}})", e.iter().map(|(k, v)| format!("{:?}: {}", k, debug_value(v))).collect::<Vec<_>>().join(", ")),
        Value::Image(im) => format!("Image(ImageValue {{ alt: {:?}, src: {:?} }})", im.alt, im.src),
        Value::Blockquote(c) => format!("Blockquote({:?})", c),
    }
}
RS
"}

actions.command:
cat > src/query.rs <<'RS'
use crate::parser::{slugify, Document, Inline};
use regex::Regex;
use std::cmp::Ordering;
use std::fmt;

#[derive(Clone, Debug)]
pub enum LinkType { External, Relative, Anchor }
impl LinkType {
    pub fn as_str(&self) -> &'static str {
        match self { LinkType::External => "external", LinkType::Relative => "relative", LinkType::Anchor => "anchor" }
    }
    pub fn debug_name(&self) -> &'static str {
        match self { LinkType::External => "External", LinkType::Relative => "Relative", LinkType::Anchor => "Anchor" }
    }
}

#[derive(Clone, Debug)]
pub struct HeadingValue {
    pub level: u8, pub text: String, pub offset: usize, pub line: usize,
    pub content: String, pub raw_md: String, pub index: usize,
}
#[derive(Clone, Debug)]
pub struct CodeValue { pub language: Option<String>, pub content: String, pub start_line: usize, pub end_line: usize }
#[derive(Clone, Debug)]
pub struct LinkValue { pub text: String, pub url: String, pub link_type: LinkType, pub offset: usize }
#[derive(Clone, Debug)]
pub struct TableValue { pub headers: Vec<String>, pub rows: Vec<Vec<String>>, pub alignments: Vec<String> }
#[derive(Clone, Debug)]
pub struct ListValue { pub ordered: bool, pub items: Vec<(String, Option<bool>)> }
#[derive(Clone, Debug)]
pub struct ImageValue { pub alt: String, pub src: String }

#[derive(Clone, Debug)]
pub enum Value {
    Null,
    Bool(bool),
    Number(f64),
    String(String),
    Array(Vec<Value>),
    Object(Vec<(String, Value)>),
    Document { content: String, heading_count: usize, word_count: usize },
    Heading(HeadingValue),
    Code(CodeValue),
    Link(LinkValue),
    Image(ImageValue),
    Table(TableValue),
    List(ListValue),
    Blockquote(String),
}

impl Value {
    pub fn type_name(&self) -> &'static str {
        match self {
            Value::Null => "null", Value::Bool(_) => "boolean", Value::Number(_) => "number",
            Value::String(_) => "string", Value::Array(_) => "array", Value::Object(_) => "object",
            Value::Document { .. } => "document", Value::Heading(_) => "heading", Value::Code(_) => "code",
            Value::Link(_) => "link", Value::Image(_) => "image", Value::Table(_) => "table",
            Value::List(_) => "list", Value::Blockquote(_) => "blockquote",
        }
    }
    pub fn is_truthy(&self) -> bool {
        match self {
            Value::Bool(b) => *b,
            Value::Number(n) => *n != 0.0,
            Value::String(s) => !s.is_empty(),
            Value::Null => false,
            Value::Array(a) => !a.is_empty(),
            _ => true,
        }
    }
}

pub fn format_number(n: f64) -> String {
    if n == n.trunc() && n.abs() < 9.007_199_254_740_992e15 {
        format!("{}", n as i64)
    } else {
        format!("{}", n)
    }
}

pub fn text_of(v: &Value) -> String {
    match v {
        Value::Null => String::new(),
        Value::Bool(b) => b.to_string(),
        Value::Number(n) => format_number(*n),
        Value::String(s) => s.clone(),
        Value::Array(a) => a.iter().map(text_of).collect::<Vec<_>>().join("\n"),
        Value::Object(_) => format_plain(v),
        Value::Document { content, .. } => content.clone(),
        Value::Heading(h) => h.text.clone(),
        Value::Code(c) => c.content.clone(),
        Value::Link(l) => l.text.clone(),
        Value::Image(im) => im.alt.clone(),
        Value::Table(t) => format!("Table({}x{})", t.headers.len(), t.rows.len()),
        Value::List(l) => l.items.iter().map(|(c, _)| c.clone()).collect::<Vec<_>>().join("\n"),
        Value::Blockquote(c) => c.clone(),
    }
}

pub fn format_plain(v: &Value) -> String {
    match v {
        Value::Document { heading_count, word_count, .. } => format!("Document: {} headings, {} words", heading_count, word_count),
        Value::Heading(h) => format!("{} {}", "#".repeat(h.level as usize), h.text),
        Value::Code(c) => {
            let lang = c.language.clone().unwrap_or_default();
            format!("```{}\n{}\n```", lang, c.content)
        }
        Value::Link(l) => format!("[{}]({})", l.text, l.url),
        Value::Image(im) => format!("![{}]({})", im.alt, im.src),
        Value::Table(t) => {
            let mut lines = Vec::new();
            lines.push(format!("| {} |", t.headers.join(" | ")));
            lines.push(format!("| {} |", t.headers.iter().map(|_| "---").collect::<Vec<_>>().join(" | ")));
            for r in &t.rows { lines.push(format!("| {} |", r.join(" | "))); }
            lines.join("\n")
        }
        Value::List(l) => {
            let mut lines = Vec::new();
            for (idx, (content, checked)) in l.items.iter().enumerate() {
                if l.ordered {
                    lines.push(format!("{}. {}", idx + 1, content));
                } else {
                    let prefix = match checked { Some(true) => "[x] ", Some(false) => "[ ] ", None => "" };
                    lines.push(format!("- {}{}", prefix, content));
                }
            }
            lines.join("\n")
        }
        Value::Blockquote(c) => format!("> {}", c),
        Value::Array(a) => a.iter().map(format_plain).collect::<Vec<_>>().join("\n"),
        Value::Object(entries) => {
            let mut lines: Vec<String> = Vec::new();
            for (k, val) in entries {
                if let Value::Array(arr) = val {
                    if arr.is_empty() {
                        lines.push(format!("{}: ", k));
                    } else {
                        let plain = format_plain(val);
                        let mut plines = plain.lines();
                        let first = plines.next().unwrap_or("");
                        lines.push(format!("{}: {}", k, first));
                        for rest in plines { lines.push(rest.to_string()); }
                    }
                } else {
                    lines.push(format!("{}: {}", k, format_plain(val)));
                }
            }
            lines.join("\n")
        }
        other => text_of(other),
    }
}

pub fn format_md(v: &Value) -> String {
    match v {
        Value::Heading(h) => h.raw_md.clone(),
        Value::Document { content, .. } => content.clone(),
        _ => format_plain(v),
    }
}

pub fn value_to_json(v: &Value) -> serde_json::Value {
    match v {
        Value::Null => serde_json::Value::Null,
        Value::Bool(b) => serde_json::Value::Bool(*b),
        Value::Number(n) => serde_json::Number::from_f64(*n).map(serde_json::Value::Number).unwrap_or(serde_json::Value::Null),
        Value::String(s) => serde_json::Value::String(s.clone()),
        Value::Array(a) => serde_json::Value::Array(a.iter().map(value_to_json).collect()),
        Value::Object(entries) => {
            let mut map = serde_json::Map::new();
            for (k, val) in entries { map.insert(k.clone(), value_to_json(val)); }
            serde_json::Value::Object(map)
        }
        Value::Document { heading_count, word_count, .. } => {
            serde_json::json!({"type":"document","heading_count":heading_count,"word_count":word_count})
        }
        Value::Heading(h) => serde_json::json!({"type":"heading","level":h.level,"text":h.text,"line":h.line}),
        Value::Code(c) => serde_json::json!({"type":"code","language":c.language,"content":c.content,"start_line":c.start_line,"end_line":c.end_line}),
        Value::Link(l) => serde_json::json!({"type":"link","text":l.text,"url":l.url,"link_type":l.link_type.as_str()}),
        Value::Image(im) => serde_json::json!({"type":"image","alt":im.alt,"src":im.src}),
        Value::Table(t) => serde_json::json!({"type":"table","headers":t.headers,"rows":t.rows}),
        Value::List(l) => {
            let items: Vec<serde_json::Value> = l.items.iter().map(|(content, checked)| {
                serde_json::json!({"content":content,"checked":checked})
            }).collect();
            serde_json::json!({"type":"list","ordered":l.ordered,"items":items})
        }
        Value::Blockquote(c) => serde_json::json!({"type":"blockquote","content":c}),
    }
}

fn tree_value_lines(v: &Value) -> Vec<String> {
    match v {
        Value::Array(a) => {
            let mut lines = vec!["[".to_string()];
            lines.extend(render_tree_nodes(a, false));
            lines.push("]".to_string());
            lines
        }
        Value::Object(entries) => {
            let mut lines = vec!["{".to_string()];
            for (k, val) in entries {
                let sub = tree_value_lines(val);
                if sub.len() == 1 {
                    lines.push(format!("{}: {}", k, sub[0]));
                } else {
                    lines.push(format!("{}: ", k));
                    // indent sub lines by two spaces (approximation of original)
                    for s in sub { lines.push(format!("  {}", s)); }
                }
            }
            lines.push("}".to_string());
            lines
        }
        _ => format_plain(v).lines().map(|s| s.to_string()).collect::<Vec<_>>().into_iter().chain(if format_plain(v).is_empty() { vec![String::new()] } else { vec![] }).collect(),
    }
}

fn render_tree_nodes(values: &[Value], _root: bool) -> Vec<String> {
    let mut lines = Vec::new();
    for (i, v) in values.iter().enumerate() {
        let last = i + 1 == values.len();
        let connector = if last { "└──" } else { "├──" };
        let cont = if last { "   " } else { "│  " };
        let sub = tree_value_lines(v);
        if sub.is_empty() {
            lines.push(connector.to_string());
        } else {
            lines.push(format!("{}{}", connector, sub[0]));
            for rest in &sub[1..] { lines.push(format!("{}{}", cont, rest)); }
        }
    }
    lines
}

pub fn format_output(results: &[Value], fmt: &str) -> String {
    match fmt {
        "plain" => {
            let mut out = String::new();
            for v in results { out.push_str(&format_plain(v)); out.push('\n'); }
            out
        }
        "json" => {
            if results.is_empty() { String::new() }
            else if results.len() == 1 { format!("{}\n", serde_json::to_string(&value_to_json(&results[0])).unwrap()) }
            else {
                let arr: Vec<serde_json::Value> = results.iter().map(value_to_json).collect();
                format!("{}\n", serde_json::to_string(&arr).unwrap())
            }
        }
        "json-pretty" => {
            if results.is_empty() { String::new() }
            else if results.len() == 1 { format!("{}\n", serde_json::to_string_pretty(&value_to_json(&results[0])).unwrap()) }
            else {
                let arr: Vec<serde_json::Value> = results.iter().map(value_to_json).collect();
                format!("{}\n", serde_json::to_string_pretty(&arr).unwrap())
            }
        }
        "jsonl" => {
            let mut out = String::new();
            for v in results { out.push_str(&serde_json::to_string(&value_to_json(v)).unwrap()); out.push('\n'); }
            out
        }
        "md" => {
            if results.is_empty() { String::new() }
            else {
                let parts: Vec<String> = results.iter().map(format_md).collect();
                format!("{}\n", parts.join("\n\n"))
            }
        }
        "tree" => {
            if results.is_empty() { String::new() }
            else {
                let lines = render_tree_nodes(results, true);
                format!("{}\n\n", lines.join("\n"))
            }
        }
        _ => String::new(),
    }
}

// ---------- Query context ----------
pub struct QueryContext {
    pub doc_content: String,
    pub heading_count: usize,
    pub word_count: usize,
    pub headings: Vec<HeadingValue>,
    pub codes: Vec<CodeValue>,
    pub links: Vec<LinkValue>,
    pub tables: Vec<TableValue>,
    pub lists: Vec<ListValue>,
    pub parents: Vec<Option<usize>>,
    pub children_map: Vec<Vec<usize>>,
}

impl QueryContext {
    pub fn build(doc: &Document) -> Self {
        let content = doc.content.clone();
        let flat = doc.flat_sections();
        // parents among flat headings
        let mut parents: Vec<Option<usize>> = vec![None; flat.len()];
        let mut stack: Vec<usize> = Vec::new();
        for i in 0..flat.len() {
            while let Some(&top) = stack.last() {
                if flat[top].level >= flat[i].level { stack.pop(); } else { break; }
            }
            parents[i] = stack.last().copied();
            stack.push(i);
        }
        let mut children_map: Vec<Vec<usize>> = vec![Vec::new(); flat.len()];
        for (i, p) in parents.iter().enumerate() {
            if let Some(p) = p { children_map[*p].push(i); }
        }
        // heading values
        let mut headings: Vec<HeadingValue> = Vec::new();
        for (i, sec) in flat.iter().enumerate() {
            // next heading with level <= this
            let mut end = content.len();
            for (j, other) in flat.iter().enumerate().skip(i + 1) {
                if other.level <= sec.level { end = other.heading_start_byte; let _ = j; break; }
            }
            let raw_md = content[sec.heading_start_byte.min(content.len())..end].to_string();
            let content_slice = if sec.content_start_byte <= end {
                content[sec.content_start_byte..end].trim().to_string()
            } else { String::new() };
            headings.push(HeadingValue {
                level: sec.level, text: sec.title.clone(), offset: sec.heading_start_byte,
                line: sec.line_idx + 1, content: content_slice, raw_md, index: i,
            });
        }
        // elements
        let mut codes: Vec<CodeValue> = Vec::new();
        let mut links: Vec<LinkValue> = Vec::new();
        let mut tables: Vec<TableValue> = Vec::new();
        let mut lists: Vec<ListValue> = Vec::new();
        let mut link_cursor: usize = 0;
        let mut push_link = |links: &mut Vec<LinkValue>, text: &str, url: &str, content: &str, cursor: &mut usize| {
            let lt = classify_link(url);
            let pat = format!("[{}]({})", text, url);
            let offset = if let Some(pos) = content[*cursor..].find(&pat) { let p = *cursor + pos; *cursor = p + 1; p }
                else if let Some(pos) = content.find(&pat) { pos } else { 0 };
            links.push(LinkValue { text: text.to_string(), url: url.to_string(), link_type: lt, offset });
        };
        for sec in &flat {
            for inl in &sec.title_inline {
                if let Inline::Link { text, url, .. } = inl {
                    push_link(&mut links, text, url, &content, &mut link_cursor);
                }
            }
            collect_from_blocks(&sec.content.blocks, &mut codes, &mut links, &mut tables, &mut lists, &content, &mut link_cursor);
        }
        QueryContext {
            doc_content: content, heading_count: doc.heading_count, word_count: doc.word_count,
            headings, codes, links, tables, lists, parents, children_map,
        }
    }
    pub fn document_value(&self) -> Value {
        Value::Document { content: self.doc_content.clone(), heading_count: self.heading_count, word_count: self.word_count }
    }
    pub fn selector_elements(&self, name: &str) -> Option<Vec<Value>> {
        let headings_all: Vec<Value> = self.headings.iter().map(|h| Value::Heading(h.clone())).collect();
        match name {
            "h" | "heading" | "headings" | "headers" => Some(headings_all),
            "h1" | "h2" | "h3" | "h4" | "h5" | "h6" => {
                let lvl = name[1..].parse::<u8>().unwrap();
                Some(self.headings.iter().filter(|h| h.level == lvl).map(|h| Value::Heading(h.clone())).collect())
            }
            "code" | "pre" | "codeblock" | "codeblocks" => Some(self.codes.iter().map(|c| Value::Code(c.clone())).collect()),
            "link" | "links" | "a" => Some(self.links.iter().map(|l| Value::Link(l.clone())).collect()),
            "img" | "image" | "images" => Some(Vec::new()),
            "table" | "tables" => Some(self.tables.iter().map(|t| Value::Table(t.clone())).collect()),
            "list" | "lists" | "ul" | "ol" => Some(self.lists.iter().map(|l| Value::List(l.clone())).collect()),
            "blockquote" | "blockquotes" | "quote" | "quotes" => Some(Vec::new()),
            "p" | "para" | "paragraph" | "paragraphs" => Some(Vec::new()),
            "frontmatter" | "yaml" => Some(Vec::new()),
            _ => None,
        }
    }
    pub fn stats_object(&self) -> Value {
        Value::Object(vec![
            ("headings".to_string(), Value::Number(self.headings.len() as f64)),
            ("code_blocks".to_string(), Value::Number(self.codes.len() as f64)),
            ("links".to_string(), Value::Number(self.links.len() as f64)),
            ("images".to_string(), Value::Number(0.0)),
            ("tables".to_string(), Value::Number(self.tables.len() as f64)),
            ("lists".to_string(), Value::Number(self.lists.len() as f64)),
            ("words".to_string(), Value::Number(self.word_count as f64)),
        ])
    }
    pub fn levels_object(&self) -> Value {
        let mut counts: Vec<(u8, usize)> = Vec::new();
        for h in &self.headings {
            if let Some(e) = counts.iter_mut().find(|(l, _)| *l == h.level) { e.1 += 1; } else { counts.push((h.level, 1)); }
        }
        counts.sort_by_key(|(l, _)| *l);
        Value::Object(counts.iter().map(|(l, c)| (format!("h{}", l), Value::Number(*c as f64))).collect())
    }
    pub fn langs_object(&self) -> Value {
        let mut counts: Vec<(String, usize)> = Vec::new();
        for c in &self.codes {
            let k = c.language.clone().unwrap_or_else(|| "none".to_string());
            if let Some(e) = counts.iter_mut().find(|(l, _)| *l == k) { e.1 += 1; } else { counts.push((k, 1)); }
        }
        Value::Object(counts.iter().map(|(l, c)| (l.clone(), Value::Number(*c as f64))).collect())
    }
    pub fn types_object(&self) -> Value {
        let mut counts: Vec<(String, usize)> = Vec::new();
        for l in &self.links {
            let k = l.link_type.as_str().to_string();
            if let Some(e) = counts.iter_mut().find(|(x, _)| *x == k) { e.1 += 1; } else { counts.push((k, 1)); }
        }
        Value::Object(counts.iter().map(|(l, c)| (l.clone(), Value::Number(*c as f64))).collect())
    }
}

fn classify_link(url: &str) -> LinkType {
    if url.starts_with('#') { LinkType::Anchor }
    else if url.starts_with("http://") || url.starts_with("https://") || url.starts_with("mailto:") { LinkType::External }
    else { LinkType::Relative }
}

fn collect_from_blocks(
    blocks: &[crate::parser::Block],
    codes: &mut Vec<CodeValue>, links: &mut Vec<LinkValue>,
    tables: &mut Vec<TableValue>, lists: &mut Vec<ListValue>,
    doc_content: &str, link_cursor: &mut usize,
) {
    use crate::parser::Block;
    for b in blocks {
        match b {
            Block::Paragraph { inline, .. } => {
                for inl in inline { if let Inline::Link { text, url, .. } = inl { push_link_raw(links, text, url, doc_content, link_cursor); } }
            }
            Block::Heading { inline, .. } => {
                for inl in inline { if let Inline::Link { text, url, .. } = inl { push_link_raw(links, text, url, doc_content, link_cursor); } }
            }
            Block::Code { language, content, .. } => {
                codes.push(CodeValue { language: language.clone(), content: content.clone(), start_line: 1, end_line: 1 });
            }
            Block::List { ordered, items } => {
                lists.push(ListValue { ordered: *ordered, items: items.iter().map(|it| (it.content.clone(), it.checked)).collect() });
                for it in items {
                    for inl in &it.inline { if let Inline::Link { text, url, .. } = inl { push_link_raw(links, text, url, doc_content, link_cursor); } }
                    collect_from_blocks(&it.blocks, codes, links, tables, lists, doc_content, link_cursor);
                }
            }
            Block::Table { headers, alignments, rows } => {
                tables.push(TableValue { headers: headers.clone(), rows: rows.clone(), alignments: alignments.clone() });
                // links from cells: parse cell content strings as inline with empty refs
                let empty_refs = crate::parser::collect_refs("");
                for cell in headers.iter().chain(rows.iter().flatten()) {
                    let inls = crate::parser::parse_inline(cell, &empty_refs);
                    for inl in &inls { if let Inline::Link { text, url, .. } = inl { push_link_raw(links, text, url, doc_content, link_cursor); } }
                }
            }
            Block::Blockquote { blocks: inner, .. } => {
                collect_from_blocks(inner, codes, links, tables, lists, doc_content, link_cursor);
            }
            Block::HorizontalRule => {}
        }
    }
}

fn push_link_raw(links: &mut Vec<LinkValue>, text: &str, url: &str, content: &str, cursor: &mut usize) {
    let lt = classify_link(url);
    let pat = format!("[{}]({})", text, url);
    let offset = if let Some(pos) = content[*cursor..].find(&pat) { let p = *cursor + pos; *cursor = p + 1; p }
        else if let Some(pos) = content.find(&pat) { pos } else { 0 };
    links.push(LinkValue { text: text.to_string(), url: url.to_string(), link_type: lt, offset });
}

// ---------- Errors ----------
#[derive(Debug, Clone)]
pub struct QueryError { pub message: String }
impl fmt::Display for QueryError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result { write!(f, "{}", self.message) }
}
fn runtime_error(msg: impl Into<String>) -> QueryError { QueryError { message: format!("error: {}\n\n", msg.into()) } }

// ---------- Lexer ----------
#[derive(Debug, Clone, PartialEq)]
enum Tok {
    Dot, Pipe, Comma, LParen, RParen, LBracket, RBracket, LBrace, RBrace, Colon,
    Greater, Less, GreaterEq, LessEq, EqualEq, NotEq, Plus, Minus, Star, Slash, Percent,
    Ident(String), Number(f64, String), Str(String), Eof,
}
#[derive(Debug, Clone)]
struct Token { tok: Tok, start: usize, len: usize, text: String }

fn span_error(query: &str, msg: &str, start: usize, len: usize, label: &str, help: Option<&str>) -> QueryError {
    let mut caret_pad = String::new();
    for c in query.chars().take(start) { caret_pad.push(if c == '\t' { '\t' } else { ' ' }); }
    let carets = "^".repeat(len.max(1));
    let mut out = format!("error: {}\n  --> query\n  |\n1 | {}\n    {}{}  {}\n", msg, query, caret_pad, carets, label);
    if let Some(h) = help { out.push_str(&format!("  = help: {}\n", h)); }
    out.push('\n');
    QueryError { message: out }
}

fn token_found_display(t: &Token) -> String {
    match &t.tok {
        Tok::Eof => "end of input".to_string(),
        Tok::Ident(_) => "identifier".to_string(),
        Tok::Number(_, _) => "number".to_string(),
        Tok::Str(_) => "string".to_string(),
        Tok::Dot => "'.'".to_string(),
        Tok::Pipe => "'|'".to_string(),
        Tok::Comma => "','".to_string(),
        Tok::LParen => "'('".to_string(),
        Tok::RParen => "')'".to_string(),
        Tok::LBracket => "'['".to_string(),
        Tok::RBracket => "']'".to_string(),
        Tok::LBrace => "'{'".to_string(),
        Tok::RBrace => "'}'".to_string(),
        Tok::Colon => "':'".to_string(),
        Tok::Greater => "'>'".to_string(),
        Tok::Less => "'<'".to_string(),
        Tok::GreaterEq => "'>='".to_string(),
        Tok::LessEq => "'<='".to_string(),
        Tok::EqualEq => "'=='".to_string(),
        Tok::NotEq => "'!='".to_string(),
        Tok::Plus => "'+'".to_string(),
        Tok::Minus => "'-'".to_string(),
        Tok::Star => "'*'".to_string(),
        Tok::Slash => "'/'".to_string(),
        Tok::Percent => "'%'".to_string(),
    }
}

fn lex(query: &str) -> Result<Vec<Token>, QueryError> {
    let chars: Vec<char> = query.chars().collect();
    let mut toks: Vec<Token> = Vec::new();
    let mut i = 0usize;
    let push = |toks: &mut Vec<Token>, tok: Tok, start: usize, len: usize, text: String| toks.push(Token { tok, start, len, text });
    while i < chars.len() {
        let c = chars[i];
        if c.is_whitespace() { i += 1; continue; }
        let start = i;
        match c {
            '.' => { push(&mut toks, Tok::Dot, start, 1, ".".into()); i += 1; }
            '|' => { push(&mut toks, Tok::Pipe, start, 1, "|".into()); i += 1; }
            ',' => { push(&mut toks, Tok::Comma, start, 1, ",".into()); i += 1; }
            '(' => { push(&mut toks, Tok::LParen, start, 1, "(".into()); i += 1; }
            ')' => { push(&mut toks, Tok::RParen, start, 1, ")".into()); i += 1; }
            '[' => { push(&mut toks, Tok::LBracket, start, 1, "[".into()); i += 1; }
            ']' => { push(&mut toks, Tok::RBracket, start, 1, "]".into()); i += 1; }
            '{' => { push(&mut toks, Tok::LBrace, start, 1, "{".into()); i += 1; }
            '}' => { push(&mut toks, Tok::RBrace, start, 1, "}".into()); i += 1; }
            ':' => { push(&mut toks, Tok::Colon, start, 1, ":".into()); i += 1; }
            '>' => {
                if i + 1 < chars.len() && chars[i + 1] == '=' { push(&mut toks, Tok::GreaterEq, start, 2, ">=".into()); i += 2; }
                else { push(&mut toks, Tok::Greater, start, 1, ">".into()); i += 1; }
            }
            '<' => {
                if i + 1 < chars.len() && chars[i + 1] == '=' { push(&mut toks, Tok::LessEq, start, 2, "<=".into()); i += 2; }
                else { push(&mut toks, Tok::Less, start, 1, "<".into()); i += 1; }
            }
            '=' => {
                if i + 1 < chars.len() && chars[i + 1] == '=' { push(&mut toks, Tok::EqualEq, start, 2, "==".into()); i += 2; }
                else {
                    return Err(span_error(query, "Unexpected character '='", start, 1, "unexpected character", Some("Use '==' for equality comparison")));
                }
            }
            '!' => {
                if i + 1 < chars.len() && chars[i + 1] == '=' { push(&mut toks, Tok::NotEq, start, 2, "!=".into()); i += 2; }
                else {
                    return Err(span_error(query, "Unexpected character '!'", start, 1, "unexpected character", Some("Use 'not' for negation or '!=' for inequality")));
                }
            }
            '+' => { push(&mut toks, Tok::Plus, start, 1, "+".into()); i += 1; }
            '*' => { push(&mut toks, Tok::Star, start, 1, "*".into()); i += 1; }
            '/' => { push(&mut toks, Tok::Slash, start, 1, "/".into()); i += 1; }
            '%' => { push(&mut toks, Tok::Percent, start, 1, "%".into()); i += 1; }
            '-' => {
                if i + 1 < chars.len() && chars[i + 1].is_ascii_digit() {
                    // negative number literal
                    let mut j = i + 1;
                    let mut s = String::from("-");
                    while j < chars.len() && (chars[j].is_ascii_digit() || chars[j] == '.') { s.push(chars[j]); j += 1; }
                    if j < chars.len() && (chars[j] == 'e' || chars[j] == 'E') {
                        let mut k = j + 1;
                        if k < chars.len() && (chars[k] == '-' || chars[k] == '+') { k += 1; }
                        if k < chars.len() && chars[k].is_ascii_digit() {
                            while j < k { s.push(chars[j]); j += 1; }
                            while j < chars.len() && chars[j].is_ascii_digit() { s.push(chars[j]); j += 1; }
                        }
                    }
                    let val: f64 = s.parse().unwrap_or(0.0);
                    let len = j - i;
                    push(&mut toks, Tok::Number(val, s.clone()), start, len, s);
                    i = j;
                } else {
                    push(&mut toks, Tok::Minus, start, 1, "-".into());
                    i += 1;
                }
            }
            '"' | '\'' => {
                let quote = c;
                let mut j = i + 1;
                let mut value = String::new();
                let mut closed = false;
                while j < chars.len() {
                    let cj = chars[j];
                    if cj == '\\' && j + 1 < chars.len() {
                        let esc = chars[j + 1];
                        match esc {
                            'n' => value.push('\n'),
                            't' => value.push('\t'),
                            'r' => value.push('\r'),
                            '\\' => value.push('\\'),
                            '"' => value.push('"'),
                            '\'' => value.push('\''),
                            '0' => value.push('\0'),
                            other => { value.push('\\'); value.push(other); }
                        }
                        j += 2;
                        continue;
                    }
                    if cj == quote { closed = true; break; }
                    value.push(cj);
                    j += 1;
                }
                if !closed {
                    let raw_len = chars.len() - i;
                    return Err(span_error(query, "Unterminated string literal", start, raw_len, "string not closed", None));
                }
                let text: String = chars[i..=j].iter().collect();
                push(&mut toks, Tok::Str(value), start, j + 1 - i, text);
                i = j + 1;
            }
            _ if c.is_ascii_digit() => {
                let mut j = i;
                let mut s = String::new();
                while j < chars.len() && (chars[j].is_ascii_digit() || chars[j] == '.') { s.push(chars[j]); j += 1; }
                if j < chars.len() && (chars[j] == 'e' || chars[j] == 'E') {
                    let mut k = j + 1;
                    if k < chars.len() && (chars[k] == '-' || chars[k] == '+') { k += 1; }
                    if k < chars.len() && chars[k].is_ascii_digit() {
                        while j < k { s.push(chars[j]); j += 1; }
                        while j < chars.len() && chars[j].is_ascii_digit() { s.push(chars[j]); j += 1; }
                    }
                }
                // ensure parseable: trailing dot etc.
                let val: f64 = s.parse().unwrap_or_else(|_| s.trim_end_matches('.').parse().unwrap_or(0.0));
                push(&mut toks, Tok::Number(val, s.clone()), start, j - i, s);
                i = j;
            }
            _ if c.is_alphabetic() || c == '_' => {
                let mut j = i;
                let mut s = String::new();
                while j < chars.len() && (chars[j].is_alphanumeric() || chars[j] == '_') { s.push(chars[j]); j += 1; }
                push(&mut toks, Tok::Ident(s.clone()), start, j - i, s);
                i = j;
            }
            _ => {
                return Err(span_error(query, &format!("Unexpected character '{}'", c), start, 1, "unexpected character", None));
            }
        }
    }
    toks.push(Token { tok: Tok::Eof, start: chars.len(), len: 0, text: String::new() });
    Ok(toks)
}

// ---------- AST ----------
#[derive(Debug, Clone)]
enum Filter {
    Empty,
    Fuzzy(String),
    Exact(String),
    Index(i64, usize, usize), // value, span start, span len
    Slice(Option<i64>, Option<i64>, usize, usize),
}
impl Filter {
    fn span(&self) -> (usize, usize) {
        match self { Filter::Index(_, s, l) => (*s, *l), Filter::Slice(_, _, s, l) => (*s, *l), _ => (0, 0) }
    }
}

#[derive(Debug, Clone)]
enum Expr {
    Literal(Value),
    FunctionCall { name: String, args: Vec<Expr> },
    Property { name: String },
    Selector { name: String, filters: Vec<Filter> },
    Hierarchy { descendant: bool, left: Box<Expr>, right_name: String, right_filters: Vec<Filter> },
    Collection(Vec<Expr>),
    ObjectLit(Vec<(String, Expr)>),
    Union(Vec<Expr>),
    Pipe(Vec<Expr>),
    Not(Box<Expr>),
    Neg(Box<Expr>),
    Binary { op: String, left: Box<Expr>, right: Box<Expr> },
}

struct Parser {
    tokens: Vec<Token>,
    pos: usize,
    query: String,
}
impl Parser {
    fn cur(&self) -> &Token { &self.tokens[self.pos.min(self.tokens.len() - 1)] }
    fn advance(&mut self) -> Token { let t = self.cur().clone(); if self.pos < self.tokens.len() - 1 { self.pos += 1; } t }
    fn at_eof(&self) -> bool { matches!(self.cur().tok, Tok::Eof) }
    fn expect_err(&self, expected: &str) -> QueryError {
        let t = self.cur().clone();
        if matches!(t.tok, Tok::Eof) && self.query.is_empty() {
            return QueryError { message: format!("error: Expected {}, found end of input\n\n", expected) };
        }
        span_error(&self.query, &format!("Expected {}, found {}", expected, token_found_display(&t)), t.start, t.len.max(1), "unexpected token", None)
    }
    fn parse_query(&mut self) -> Result<Expr, QueryError> {
        if self.at_eof() {
            return Err(QueryError { message: "error: Expected expression, found end of input\n\n".to_string() });
        }
        let e = self.parse_union()?;
        if !self.at_eof() {
            return Err(self.expect_err("end of query"));
        }
        Ok(e)
    }
    fn parse_union(&mut self) -> Result<Expr, QueryError> {
        let mut branches = vec![self.parse_pipeline()?];
        while matches!(self.cur().tok, Tok::Comma) {
            self.advance();
            branches.push(self.parse_pipeline()?);
        }
        if branches.len() == 1 { Ok(branches.pop().unwrap()) } else { Ok(Expr::Union(branches)) }
    }
    fn parse_pipeline(&mut self) -> Result<Expr, QueryError> {
        let mut stages = vec![self.parse_binary()?];
        while matches!(self.cur().tok, Tok::Pipe) {
            self.advance();
            stages.push(self.parse_binary()?);
        }
        if stages.len() == 1 { Ok(stages.pop().unwrap()) } else { Ok(Expr::Pipe(stages)) }
    }
    fn parse_binary(&mut self) -> Result<Expr, QueryError> { self.parse_or() }
    fn parse_or(&mut self) -> Result<Expr, QueryError> {
        let mut left = self.parse_and()?;
        while matches!(&self.cur().tok, Tok::Ident(s) if s == "or") {
            self.advance();
            let right = self.parse_and()?;
            left = Expr::Binary { op: "or".into(), left: Box::new(left), right: Box::new(right) };
        }
        Ok(left)
    }
    fn parse_and(&mut self) -> Result<Expr, QueryError> {
        let mut left = self.parse_comparison()?;
        while matches!(&self.cur().tok, Tok::Ident(s) if s == "and") {
            self.advance();
            let right = self.parse_comparison()?;
            left = Expr::Binary { op: "and".into(), left: Box::new(left), right: Box::new(right) };
        }
        Ok(left)
    }
    fn is_hierarchy_ahead(&self) -> Option<bool> {
        // at current Greater token: check >> (two greaters) or >
        if matches!(self.cur().tok, Tok::Greater) {
            let next = self.tokens.get(self.pos + 1);
            let after_op_idx = if matches!(next.map(|t| &t.tok), Some(Tok::Greater)) { self.pos + 2 } else { self.pos + 1 };
            let descendant = after_op_idx == self.pos + 2;
            if let Some(t) = self.tokens.get(after_op_idx) {
                if matches!(t.tok, Tok::Dot) { return Some(descendant); }
            }
        }
        None
    }
    fn parse_comparison(&mut self) -> Result<Expr, QueryError> {
        let mut left = self.parse_add()?;
        loop {
            // hierarchy: left is selector/hierarchy and operator followed by '.'
            if matches!(self.cur().tok, Tok::Greater) {
                if let Some(descendant) = self.is_hierarchy_ahead() {
                    if matches!(left, Expr::Selector { .. } | Expr::Hierarchy { .. }) {
                        self.advance();
                        if descendant { self.advance(); }
                        // parse right selector
                        // expect dot
                        let (right_name, right_filters) = self.parse_hierarchy_right()?;
                        left = Expr::Hierarchy { descendant, left: Box::new(left), right_name, right_filters };
                        continue;
                    }
                }
            }
            let op = match &self.cur().tok {
                Tok::EqualEq => "==",
                Tok::NotEq => "!=",
                Tok::GreaterEq => ">=",
                Tok::LessEq => "<=",
                Tok::Greater => ">",
                Tok::Less => "<",
                _ => break,
            }.to_string();
            self.advance();
            let right = self.parse_add()?;
            left = Expr::Binary { op, left: Box::new(left), right: Box::new(right) };
        }
        Ok(left)
    }
    fn parse_hierarchy_right(&mut self) -> Result<(String, Vec<Filter>), QueryError> {
        // current should be Dot
        if !matches!(self.cur().tok, Tok::Dot) { return Err(self.expect_err("expression")); }
        self.advance(); // dot
        let name_tok = self.cur().clone();
        let name = match &name_tok.tok {
            Tok::Ident(s) => s.clone(),
            _ => return Err(self.expect_err("identifier")),
        };
        self.advance();
        let filters = self.parse_filters()?;
        // dotted continuation makes a bogus selector name (matches original returning empty)
        let mut full_name = name;
        while matches!(self.cur().tok, Tok::Dot) {
            // peek: if dot followed by identifier, consume as part of name
            let save = self.pos;
            self.advance();
            if let Tok::Ident(s) = &self.cur().tok {
                full_name = format!("{}.{}", full_name, s);
                self.advance();
                let _ = self.parse_filters()?;
            } else { self.pos = save; break; }
        }
        Ok((full_name, filters))
    }
    fn parse_add(&mut self) -> Result<Expr, QueryError> {
        let mut left = self.parse_mul()?;
        loop {
            let op = match &self.cur().tok { Tok::Plus => "+", Tok::Minus => "-", _ => break }.to_string();
            self.advance();
            let right = self.parse_mul()?;
            left = Expr::Binary { op, left: Box::new(left), right: Box::new(right) };
        }
        Ok(left)
    }
    fn parse_mul(&mut self) -> Result<Expr, QueryError> {
        let mut left = self.parse_unary()?;
        loop {
            let op = match &self.cur().tok { Tok::Star => "*", Tok::Slash => "/", Tok::Percent => "%", _ => break }.to_string();
            self.advance();
            let right = self.parse_unary()?;
            left = Expr::Binary { op, left: Box::new(left), right: Box::new(right) };
        }
        Ok(left)
    }
    fn parse_unary(&mut self) -> Result<Expr, QueryError> {
        if let Tok::Ident(s) = &self.cur().tok {
            if s == "not" {
                self.advance();
                let e = self.parse_unary()?;
                return Ok(Expr::Not(Box::new(e)));
            }
        }
        if matches!(self.cur().tok, Tok::Minus) {
            self.advance();
            let e = self.parse_unary()?;
            return Ok(Expr::Neg(Box::new(e)));
        }
        self.parse_primary()
    }
    fn parse_filters(&mut self) -> Result<Vec<Filter>, QueryError> {
        let mut filters = Vec::new();
        while matches!(self.cur().tok, Tok::LBracket) {
            let lb = self.advance(); // '['
            let start = lb.start;
            // empty
            if matches!(self.cur().tok, Tok::RBracket) { self.advance(); filters.push(Filter::Empty); continue; }
            match self.cur().tok.clone() {
                Tok::Str(s) => {
                    self.advance();
                    if !matches!(self.cur().tok, Tok::RBracket) { return Err(self.expect_err("']'")); }
                    let rb = self.advance();
                    let _ = rb;
                    filters.push(Filter::Exact(s));
                }
                Tok::Ident(s) => {
                    self.advance();
                    if !matches!(self.cur().tok, Tok::RBracket) { return Err(self.expect_err("']'")); }
                    self.advance();
                    filters.push(Filter::Fuzzy(s));
                }
                Tok::Number(_, _) | Tok::Minus => {
                    // parse signed number / slice
                    let first = self.parse_filter_signed_number(start)?;
                    if matches!(self.cur().tok, Tok::Colon) {
                        self.advance();
                        let second = if matches!(self.cur().tok, Tok::RBracket) { None } else { Some(self.parse_filter_signed_number(start)?) };
                        if !matches!(self.cur().tok, Tok::RBracket) { return Err(self.expect_err("']'")); }
                        let rb = self.advance();
                        let span_len = rb.start + 1 - start;
                        filters.push(Filter::Slice(first.map(|v| v), second, start, span_len));
                    } else if matches!(self.cur().tok, Tok::RBracket) {
                        let rb = self.advance();
                        let span_len = rb.start + 1 - start;
                        match first {
                            Some(v) => filters.push(Filter::Index(v, start, span_len)),
                            None => return Err(span_error(&self.query, "Invalid filter: expected filter pattern or index", start, span_len, "invalid filter", None)),
                        }
                    } else {
                        return Err(self.expect_err("']'"));
                    }
                }
                _ => {
                    // invalid filter: span to matching ] if present else 1
                    let mut len = 1usize;
                    // scan tokens for rbracket
                    let mut j = self.pos;
                    while j < self.tokens.len() {
                        if matches!(self.tokens[j].tok, Tok::RBracket) { len = self.tokens[j].start + 1 - start; break; }
                        if matches!(self.tokens[j].tok, Tok::Eof) { break; }
                        j += 1;
                    }
                    return Err(span_error(&self.query, "Invalid filter: expected filter pattern or index", start, len, "invalid filter", None));
                }
            }
        }
        Ok(filters)
    }
    fn parse_filter_signed_number(&mut self, bracket_start: usize) -> Result<Option<i64>, QueryError> {
        // handles Number token (may itself be negative), or Minus followed by Number
        let mut minuses = 0usize;
        while matches!(self.cur().tok, Tok::Minus) {
            minuses += 1;
            self.advance();
            if minuses > 1 {
                // invalid filter spanning bracket
                let mut len = 1usize;
                let mut j = self.pos;
                while j < self.tokens.len() {
                    if matches!(self.tokens[j].tok, Tok::RBracket) { len = self.tokens[j].start + 1 - bracket_start; break; }
                    if matches!(self.tokens[j].tok, Tok::Eof) { break; }
                    j += 1;
                }
                return Err(span_error(&self.query, "Invalid filter: expected filter pattern or index", bracket_start, len, "invalid filter", None));
            }
        }
        match self.cur().tok.clone() {
            Tok::Number(v, _) => {
                self.advance();
                let mut val = v;
                for _ in 0..minuses { val = -val; }
                Ok(Some(val as i64))
            }
            _ => Ok(None),
        }
    }
    fn parse_primary(&mut self) -> Result<Expr, QueryError> {
        let t = self.cur().clone();
        match t.tok {
            Tok::Number(v, _) => { self.advance(); Ok(Expr::Literal(Value::Number(v))) }
            Tok::Str(s) => { self.advance(); Ok(Expr::Literal(Value::String(s))) }
            Tok::LParen => {
                self.advance();
                let e = self.parse_pipeline()?;
                if !matches!(self.cur().tok, Tok::RParen) { return Err(self.expect_err("')'")); }
                self.advance();
                Ok(e)
            }
            Tok::LBracket => {
                self.advance();
                if matches!(self.cur().tok, Tok::RBracket) { self.advance(); return Ok(Expr::Collection(vec![])); }
                let inner = self.parse_union()?;
                if !matches!(self.cur().tok, Tok::RBracket) { return Err(self.expect_err("']'")); }
                self.advance();
                let branches = match inner { Expr::Union(b) => b, other => vec![other] };
                Ok(Expr::Collection(branches))
            }
            Tok::LBrace => {
                self.advance();
                let mut entries: Vec<(String, Expr)> = Vec::new();
                if matches!(self.cur().tok, Tok::RBrace) { self.advance(); return Ok(Expr::ObjectLit(entries)); }
                loop {
                    let key = match &self.cur().tok {
                        Tok::Ident(s) => { let k = s.clone(); self.advance(); k }
                        Tok::Str(s) => { let k = s.clone(); self.advance(); k }
                        _ => {
                            let tok = self.cur().clone();
                            return Err(span_error(&self.query, &format!("Expected one of identifier, string, found {}", token_found_display(&tok)), tok.start, tok.len.max(1), "unexpected token", None));
                        }
                    };
                    if !matches!(self.cur().tok, Tok::Colon) { return Err(self.expect_err("':'")); }
                    self.advance();
                    let val = self.parse_pipeline()?;
                    entries.push((key, val));
                    if matches!(self.cur().tok, Tok::Comma) { self.advance(); continue; }
                    break;
                }
                if !matches!(self.cur().tok, Tok::RBrace) { return Err(self.expect_err("'}'")); }
                self.advance();
                Ok(Expr::ObjectLit(entries))
            }
            Tok::Dot => {
                // dot chain
                // If next token is not ident, identity (or error for '.'?)
                let next = self.tokens.get(self.pos + 1).cloned();
                match next.map(|nt| nt.tok) {
                    Some(Tok::Ident(_)) => {
                        let mut segments: Vec<(String, Vec<Filter>)> = Vec::new();
                        loop {
                            self.advance(); // dot
                            let name_tok = self.cur().clone();
                            let name = match &name_tok.tok {
                                Tok::Ident(s) => s.clone(),
                                _ => return Err(self.expect_err("identifier")),
                            };
                            self.advance();
                            let filters = self.parse_filters()?;
                            segments.push((name, filters));
                            if matches!(self.cur().tok, Tok::Dot) {
                                // another segment follows only if dot+ident
                                let nn = self.tokens.get(self.pos + 1).cloned();
                                if matches!(nn.map(|x| x.tok), Some(Tok::Ident(_))) { continue; }
                                // dot followed by non-ident: will be handled by outer? treat as error in next loop iteration
                                // To match .h..text error, continue loop will attempt: dot then '.' -> expected identifier found '.'
                                // Force continuation:
                                // Peek if next is Dot, continue
                                let nn2 = self.tokens.get(self.pos + 1).cloned();
                                if matches!(nn2.map(|x| x.tok), Some(Tok::Dot)) { continue; }
                                break;
                            }
                            break;
                        }
                        if segments.len() == 1 {
                            let (name, filters) = segments.into_iter().next().unwrap();
                            if is_selector_name(&name) {
                                Ok(Expr::Selector { name, filters })
                            } else {
                                // property with possible filters attached? Filters on a property are ignored like selector application?
                                // Represent as Selector with unknown handling? Use Property if no filters; if filters exist, still Property (filters ignored)
                                let _ = filters;
                                Ok(Expr::Property { name })
                            }
                        } else {
                            let (name, _) = segments.into_iter().last().unwrap();
                            Ok(Expr::Property { name })
                        }
                    }
                    Some(Tok::Dot) => {
                        // '..' -> expected identifier found '.'
                        self.advance(); // first dot
                        Err(self.expect_err("identifier"))
                    }
                    _ => {
                        self.advance(); // consume dot as identity
                        Ok(Expr::Literal(Value::Null)) // placeholder replaced below
                        // identity handled via special marker: use Property with empty name
                    }
                }
            }
            Tok::Ident(name) => {
                match name.as_str() {
                    "true" => { self.advance(); Ok(Expr::Literal(Value::Bool(true))) }
                    "false" => { self.advance(); Ok(Expr::Literal(Value::Bool(false))) }
                    "null" => { self.advance(); Ok(Expr::Literal(Value::Null)) }
                    _ => {
                        self.advance();
                        let mut args: Vec<Expr> = Vec::new();
                        if matches!(self.cur().tok, Tok::LParen) {
                            self.advance();
                            if matches!(self.cur().tok, Tok::RParen) { self.advance(); }
                            else {
                                loop {
                                    let a = self.parse_pipeline()?;
                                    args.push(a);
                                    if matches!(self.cur().tok, Tok::Comma) { self.advance(); continue; }
                                    break;
                                }
                                if !matches!(self.cur().tok, Tok::RParen) { return Err(self.expect_err("')'")); }
                                self.advance();
                            }
                        }
                        Ok(Expr::FunctionCall { name, args })
                    }
                }
            }
            _ => Err(self.expect_err("expression")),
        }
    }
}

// identity placeholder: Expr::Literal(Null) from '.' needs special handling.
// We detect it in evaluation by a thread-local? Instead, parser replaces '.' identity with FunctionCall "identity" internally.
fn is_selector_name(name: &str) -> bool {
    matches!(name,
        "h" | "heading" | "headings" | "headers" | "h1" | "h2" | "h3" | "h4" | "h5" | "h6"
        | "code" | "pre" | "codeblock" | "codeblocks"
        | "link" | "links" | "a"
        | "img" | "image" | "images"
        | "table" | "tables"
        | "list" | "lists" | "ul" | "ol"
        | "blockquote" | "blockquotes" | "quote" | "quotes"
        | "p" | "para" | "paragraph" | "paragraphs"
        | "frontmatter" | "yaml")
}

const FUNCTION_NAMES: &[&str] = &[
    "count","length","len","size","first","last","head","limit","take","skip","drop","nth","reverse","sort","sort_by","unique","flatten","group_by","min","max","add","stats","levels","langs","types","text","upper","lower","trim","split","join","replace","slugify","lines","words","chars","select","where","filter","contains","includes","startswith","endswith","matches","any","all","not","content","md","url","href","src","lang","language","type","keys","values","has","empty","debug","ascii_downcase","ascii_upcase",
];

fn function_arity(name: &str) -> Option<(usize, usize)> {
    match name {
        "count"|"length"|"len"|"size"|"first"|"last"|"head"|"reverse"|"sort"|"unique"|"flatten"|"min"|"max"|"add"|"stats"|"levels"|"langs"|"types"|"text"|"upper"|"lower"|"trim"|"slugify"|"lines"|"words"|"chars"|"content"|"md"|"url"|"href"|"src"|"lang"|"language"|"type"|"keys"|"values"|"empty"|"debug"|"ascii_downcase"|"ascii_upcase" => Some((0,0)),
        "limit"|"take"|"skip"|"drop"|"nth"|"sort_by"|"group_by"|"split"|"join"|"select"|"where"|"filter"|"contains"|"includes"|"startswith"|"endswith"|"matches"|"any"|"all"|"has" => Some((1,1)),
        "replace" => Some((2,2)),
        _ => None,
    }
}

fn levenshtein(a: &str, b: &str) -> usize {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    let mut prev: Vec<usize> = (0..=b.len()).collect();
    let mut cur = vec![0usize; b.len() + 1];
    for i in 1..=a.len() {
        cur[0] = i;
        for j in 1..=b.len() {
            let cost = if a[i - 1] == b[j - 1] { 0 } else { 1 };
            cur[j] = (prev[j] + 1).min(cur[j - 1] + 1).min(prev[j - 1] + cost);
        }
        std::mem::swap(&mut prev, &mut cur);
    }
    prev[b.len()]
}

fn unknown_function_error(name: &str) -> QueryError {
    let mut candidates: Vec<(usize, &str)> = FUNCTION_NAMES.iter()
        .map(|&f| (levenshtein(name, f), f))
        .filter(|(d, _)| *d <= 2)
        .collect();
    candidates.sort_by(|a, b| a.0.cmp(&b.0).then(a.1.cmp(b.1)));
    candidates.truncate(3);
    // Also include "null" keyword for very close names
    let mut names: Vec<String> = candidates.iter().map(|(_, f)| f.to_string()).collect();
    if levenshtein(name, "null") <= 2 && !names.iter().any(|x| x == "null") {
        // insert keeping distance order roughly
        if names.len() < 3 { names.push("null".to_string()); }
    }
    if names.is_empty() {
        runtime_error(format!("Unknown function '{}'", name))
    } else {
        let joined = names.iter().map(|n| format!("'{}'", n)).collect::<Vec<_>>().join(" or ");
        QueryError { message: format!("error: Unknown function '{}'\n  |\n  = help: did you mean {}?\n\n", name, joined) }
    }
}

// ---------- Evaluation ----------
pub struct Evaluator<'a> { ctx: &'a QueryContext }

pub fn run_query(doc: &Document, query: &str) -> Result<Vec<Value>, QueryError> {
    let ctx = QueryContext::build(doc);
    let tokens = lex(query)?;
    let mut parser = Parser { tokens, pos: 0, query: query.to_string() };
    let expr = parser.parse_query()?;
    // replace '.' identity literal placeholder: our parser returns Literal(Null) for '.' alone;
    // handle by checking if query trimmed segments... Instead evaluation treats a Literal(Null)
    // that came from '.' – ambiguous with null literal. We intercept: if expr is Literal(Null)
    // and query contains a '.' that isn't part of number/string, hard. Simpler: Parser already
    // cannot distinguish. We handle top-level by re-checking: if the parsed expr is a Pipe etc.
    // it may contain identity stages. To fix, evaluator's eval for Literal(Null) returns Null,
    // but identity stages are represented as Property with empty name – see parser patch below.
    let ev = Evaluator { ctx: &ctx };
    let input = ctx.document_value();
    ev.eval_vec(&expr, &input)
}

impl<'a> Evaluator<'a> {
    fn eval_vec(&self, expr: &Expr, input: &Value) -> Result<Vec<Value>, QueryError> {
        match expr {
            Expr::Pipe(stages) => {
                let mut current = vec![input.clone()];
                for stage in stages {
                    let mut next = Vec::new();
                    for v in &current { next.extend(self.eval_vec(stage, v)?); }
                    current = next;
                }
                Ok(current)
            }
            Expr::Union(branches) => {
                let mut out = Vec::new();
                for b in branches { out.extend(self.eval_vec(b, input)?); }
                Ok(out)
            }
            Expr::Collection(branches) => {
                let mut items = Vec::new();
                for b in branches { items.extend(self.eval_vec(b, input)?); }
                Ok(vec![Value::Array(items)])
            }
            Expr::ObjectLit(entries) => {
                let mut obj: Vec<(String, Value)> = Vec::new();
                for (k, e) in entries {
                    let v = self.eval_scalar(e, input)?;
                    obj.push((k.clone(), v));
                }
                Ok(vec![Value::Object(obj)])
            }
            Expr::Selector { name, filters } => {
                let base = self.ctx.selector_elements(name).unwrap_or_default();
                let filtered = self.apply_filters(base, filters)?;
                Ok(filtered)
            }
            Expr::Hierarchy { descendant, left, right_name, right_filters } => {
                let left_vals = self.eval_vec(left, input)?;
                let mut out = Vec::new();
                for lv in &left_vals {
                    if let Value::Heading(h) = lv {
                        // heading right?
                        if let Some(mut elems) = self.ctx.selector_elements(right_name) {
                            let is_heading_selector = self.ctx.selector_elements(right_name).is_some()
                                && matches!(elems.first(), Some(Value::Heading(_)) | None)
                                && (is_heading_selector_name(right_name));
                            if is_heading_selector {
                                let candidate_idxs: Vec<usize> = if *descendant {
                                    self.descendants_of(h.index)
                                } else {
                                    self.ctx.children_map.get(h.index).cloned().unwrap_or_default()
                                };
                                let cand: Vec<Value> = candidate_idxs.iter().map(|&i| Value::Heading(self.ctx.headings[i].clone())).collect();
                                elems = cand;
                            }
                            out.extend(self.apply_filters(elems, right_filters)?);
                        } else {
                            // unknown selector on right: no output
                        }
                    }
                }
                Ok(out)
            }
            Expr::Property { name } => {
                if name.is_empty() { return Ok(vec![input.clone()]); }
                let v = self.get_property(input, name)?;
                Ok(vec![v])
            }
            Expr::FunctionCall { name, args } => {
                match self.apply_function(name, args, input)? {
                    Some(v) => Ok(vec![v]),
                    None => Ok(vec![]),
                }
            }
            Expr::Literal(v) => {
                // '.' identity was encoded as Literal(Null) by parser when alone; distinguish
                // by a hack: if v is Null and the original token was '.', the parser actually
                // returns Property with empty name (see below). Literal Null here is genuine null.
                Ok(vec![v.clone()])
            }
            Expr::Not(e) => {
                let v = self.eval_scalar(e, input)?;
                Ok(vec![Value::Bool(!v.is_truthy())])
            }
            Expr::Neg(e) => {
                let v = self.eval_scalar(e, input)?;
                match v { Value::Number(n) => Ok(vec![Value::Number(-n)]), _ => Ok(vec![Value::Null]) }
            }
            Expr::Binary { op, left, right } => {
                let v = self.eval_binary(op, left, right, input)?;
                Ok(vec![v])
            }
        }
    }
    fn descendants_of(&self, idx: usize) -> Vec<usize> {
        let mut out = Vec::new();
        let mut stack: Vec<usize> = self.ctx.children_map.get(idx).cloned().unwrap_or_default();
        // preorder: children in order, each followed by its descendants
        let mut result = Vec::new();
        fn walk(i: usize, ctx: &QueryContext, out: &mut Vec<usize>) {
            out.push(i);
            if let Some(ch) = ctx.children_map.get(i) { for &c in ch { walk(c, ctx, out); } }
        }
        for c in stack.drain(..) { walk(c, self.ctx, &mut result); }
        let _ = &mut out;
        result
    }
    fn eval_scalar(&self, expr: &Expr, input: &Value) -> Result<Value, QueryError> {
        // special case: identity '.' literal placeholder handling is via Property empty.
        let vals = self.eval_vec(expr, input)?;
        Ok(vals.into_iter().next().unwrap_or(Value::Null))
    }
    fn eval_binary(&self, op: &str, left: &Expr, right: &Expr, input: &Value) -> Result<Value, QueryError> {
        match op {
            "and" => {
                let l = self.eval_scalar(left, input)?;
                if !l.is_truthy() { return Ok(Value::Bool(false)); }
                let r = self.eval_scalar(right, input)?;
                Ok(Value::Bool(r.is_truthy()))
            }
            "or" => {
                let l = self.eval_scalar(left, input)?;
                if l.is_truthy() { return Ok(Value::Bool(true)); }
                let r = self.eval_scalar(right, input)?;
                Ok(Value::Bool(r.is_truthy()))
            }
            "+" => {
                let l = self.eval_scalar(left, input)?;
                let r = self.eval_scalar(right, input)?;
                match (&l, &r) {
                    (Value::Number(a), Value::Number(b)) => Ok(Value::Number(a + b)),
                    (Value::Array(a), Value::Array(b)) => { let mut x = a.clone(); x.extend(b.clone()); Ok(Value::Array(x)) }
                    (Value::String(_), _) | (_, Value::String(_)) => Ok(Value::String(format!("{}{}", text_of(&l), text_of(&r)))),
                    _ => Ok(Value::Null),
                }
            }
            "-" | "*" | "/" | "%" => {
                let l = self.eval_scalar(left, input)?;
                let r = self.eval_scalar(right, input)?;
                // string repetition
                if op == "*" {
                    if let (Value::String(s), Value::Number(n)) = (&l, &r) {
                        if *n <= 0.0 { return Ok(Value::String(String::new())); }
                        return Ok(Value::String(s.repeat(*n as usize)));
                    }
                }
                match (&l, &r) {
                    (Value::Number(a), Value::Number(b)) => {
                        if (op == "/" || op == "%") && *b == 0.0 { return Err(runtime_error("Division by zero")); }
                        Ok(Value::Number(match op { "-" => a - b, "*" => a * b, "/" => a / b, "%" => a % b, _ => unreachable!() }))
                    }
                    _ => Ok(Value::Null),
                }
            }
            "==" | "!=" => {
                let l = self.eval_scalar(left, input)?;
                let r = self.eval_scalar(right, input)?;
                let eq = values_equal(&l, &r);
                Ok(Value::Bool(if op == "==" { eq } else { !eq }))
            }
            ">" | "<" | ">=" | "<=" => {
                let l = self.eval_scalar(left, input)?;
                let r = self.eval_scalar(right, input)?;
                let ord = match (&l, &r) {
                    (Value::Number(a), Value::Number(b)) => a.partial_cmp(b),
                    (Value::String(a), Value::String(b)) => Some(a.cmp(b)),
                    _ => None,
                };
                let res = match (ord, op) {
                    (Some(Ordering::Greater), ">") => true,
                    (Some(Ordering::Less), "<") => true,
                    (Some(Ordering::Greater), ">=") => true,
                    (Some(Ordering::Less), "<=") => true,
                    (Some(Ordering::Equal), ">=") => true,
                    (Some(Ordering::Equal), "<=") => true,
                    _ => false,
                };
                Ok(Value::Bool(res))
            }
            _ => Ok(Value::Null),
        }
    }
    fn apply_filters(&self, base: Vec<Value>, filters: &[Filter]) -> Result<Vec<Value>, QueryError> {
        let mut patterned = base.clone();
        let mut selection: Option<Filter> = None;
        let mut seen_indexing = false;
        for f in filters {
            match f {
                Filter::Empty => { patterned = base.clone(); selection = None; seen_indexing = false; }
                Filter::Fuzzy(p) | Filter::Exact(p) => {
                    if seen_indexing {
                        let (s, l) = (f.span().0, f.span().1);
                        // span for pattern-after-index needs the bracket group; stored span is 0 for fuzzy/exact.
                        // We stored bracket span in Index/Slice only; approximate using filter's own storage:
                        let _ = (s, l);
                        return Err(runtime_error("Invalid filter: expected index, got filter"));
                        // NOTE: replaced below in apply_filters_with_query when query available
                    }
                    let exact = matches!(f, Filter::Exact(_));
                    patterned.retain(|el| filter_matches(el, p, exact));
                }
                Filter::Index(_, _, _) | Filter::Slice(_, _, _, _) => { selection = Some(f.clone()); seen_indexing = true; }
            }
        }
        let result = match selection {
            Some(Filter::Index(idx, _, _)) => {
                let len = patterned.len() as i64;
                let resolved = if idx < 0 { len + idx } else { idx };
                if resolved >= 0 && resolved < len { vec![patterned[resolved as usize].clone()] } else { vec![] }
            }
            Some(Filter::Slice(a, b, _, _)) => slice_values(&patterned, a, b),
            _ => patterned,
        };
        Ok(result)
    }
    fn get_property(&self, input: &Value, name: &str) -> Result<Value, QueryError> {
        match input {
            Value::Document { content, heading_count, word_count } => {
                match name {
                    "text" | "content" => Ok(Value::String(content.clone())),
                    "headings" => Ok(Value::Number(*heading_count as f64)),
                    "words" | "word_count" => Ok(Value::Number(*word_count as f64)),
                    _ => Err(runtime_error(format!("Property '{}' not found on document", name))),
                }
            }
            Value::Heading(h) => {
                match name {
                    "text" => Ok(Value::String(h.text.clone())),
                    "content" => Ok(Value::String(h.content.clone())),
                    "md" => Ok(Value::String(h.raw_md.clone())),
                    "level" => Ok(Value::Number(h.level as f64)),
                    "line" => Ok(Value::Number(h.line as f64)),
                    "slug" => Ok(Value::String(slugify(&h.text))),
                    _ => Err(runtime_error(format!("Property '{}' not found on heading", name))),
                }
            }
            Value::Code(c) => {
                match name {
                    "text" | "content" => Ok(Value::String(c.content.clone())),
                    "lang" | "language" => Ok(Value::String(c.language.clone().unwrap_or_default())),
                    "start_line" => Ok(Value::Number(c.start_line as f64)),
                    "end_line" => Ok(Value::Number(c.end_line as f64)),
                    _ => Err(runtime_error(format!("Property '{}' not found on code", name))),
                }
            }
            Value::Link(l) => {
                match name {
                    "text" => Ok(Value::String(l.text.clone())),
                    "url" => Ok(Value::String(l.url.clone())),
                    "type" => Ok(Value::String(l.link_type.as_str().to_string())),
                    _ => Err(runtime_error(format!("Property '{}' not found on link", name))),
                }
            }
            Value::Image(im) => {
                match name {
                    "text" | "alt" => Ok(Value::String(im.alt.clone())),
                    "src" | "url" => Ok(Value::String(im.src.clone())),
                    _ => Err(runtime_error(format!("Property '{}' not found on image", name))),
                }
            }
            Value::Table(t) => {
                match name {
                    "headers" => Ok(Value::Array(t.headers.iter().map(|s| Value::String(s.clone())).collect())),
                    "rows" => Ok(Value::Array(t.rows.iter().map(|r| Value::Array(r.iter().map(|s| Value::String(s.clone())).collect())).collect())),
                    _ => Err(runtime_error(format!("Property '{}' not found on table", name))),
                }
            }
            Value::List(l) => {
                match name {
                    "items" => Ok(Value::Array(l.items.iter().map(|(c, _)| Value::String(c.clone())).collect())),
                    "ordered" => Ok(Value::Bool(l.ordered)),
                    _ => Err(runtime_error(format!("Property '{}' not found on list", name))),
                }
            }
            Value::Object(entries) => {
                for (k, v) in entries { if k == name { return Ok(v.clone()); } }
                Err(runtime_error(format!("Property '{}' not found on object", name)))
            }
            other => Err(runtime_error(format!("Property '{}' not found on {}", name, other.type_name()))),
        }
    }
    fn eval_arg_values(&self, args: &[Expr], input: &Value) -> Result<Vec<Value>, QueryError> {
        let mut out = Vec::new();
        for a in args { out.push(self.eval_scalar(a, input)?); }
        Ok(out)
    }
    fn apply_function(&self, name: &str, args: &[Expr], input: &Value) -> Result<Option<Value>, QueryError> {
        let arity = match function_arity(name) {
            Some(a) => a,
            None => return Err(unknown_function_error(name)),
        };
        if args.len() < arity.0 || args.len() > arity.1 {
            return Err(runtime_error(format!("Function '{}' expects {}..={} arguments, got {}", name, arity.0, arity.1, args.len())));
        }
        // helper closures not possible easily; inline arg evaluation
        match name {
            "count" | "length" | "len" | "size" => {
                let n = match input {
                    Value::Array(a) => a.len(),
                    Value::String(s) => s.chars().count(),
                    Value::Object(e) => e.len(),
                    _ => 1,
                };
                Ok(Some(Value::Number(n as f64)))
            }
            "first" | "head" => {
                match input { Value::Array(a) => Ok(Some(a.first().cloned().unwrap_or(Value::Null))), _ => Ok(Some(input.clone())) }
            }
            "last" => {
                match input { Value::Array(a) => Ok(Some(a.last().cloned().unwrap_or(Value::Null))), _ => Ok(Some(input.clone())) }
            }
            "limit" | "take" => {
                let arg = self.eval_scalar(&args[0], input)?;
                if let Value::Array(a) = input {
                    let n = to_usize(&arg);
                    Ok(Some(Value::Array(a.iter().take(n).cloned().collect())))
                } else { Ok(Some(input.clone())) }
            }
            "skip" | "drop" => {
                let arg = self.eval_scalar(&args[0], input)?;
                if let Value::Array(a) = input {
                    let n = to_usize(&arg);
                    Ok(Some(Value::Array(a.iter().skip(n).cloned().collect())))
                } else { Ok(Some(input.clone())) }
            }
            "nth" => {
                let arg = self.eval_scalar(&args[0], input)?;
                if let Value::Array(a) = input {
                    let idx = to_i64(&arg);
                    let len = a.len() as i64;
                    let resolved = if idx < 0 { len + idx } else { idx };
                    if resolved >= 0 && resolved < len { Ok(Some(a[resolved as usize].clone())) } else { Ok(None) }
                } else { Ok(None) }
            }
            "reverse" => {
                if let Value::Array(a) = input { let mut x = a.clone(); x.reverse(); Ok(Some(Value::Array(x))) }
                else { Ok(Some(input.clone())) }
            }
            "sort" => {
                if let Value::Array(a) = input { let mut x = a.clone(); sort_values(&mut x); Ok(Some(Value::Array(x))) }
                else { Ok(Some(input.clone())) }
            }
            "sort_by" => {
                let arg = self.eval_scalar(&args[0], input)?;
                let key = if let Value::String(s) = &arg { s.clone() } else { text_of(&arg) };
                if let Value::Array(a) = input {
                    let mut x = a.clone();
                    if key == "level" {
                        x.sort_by_key(|v| match v { Value::Heading(h) => h.level as i64, _ => 0 });
                    } else {
                        sort_values(&mut x);
                    }
                    Ok(Some(Value::Array(x)))
                } else { Ok(Some(input.clone())) }
            }
            "group_by" => {
                let _arg = self.eval_scalar(&args[0], input)?;
                if let Value::Array(a) = input {
                    let mut groups: Vec<(String, Vec<Value>)> = Vec::new();
                    for el in a {
                        let key = group_key(el);
                        if let Some(g) = groups.iter_mut().find(|(k, _)| *k == key) { g.1.push(el.clone()); }
                        else { groups.push((key, vec![el.clone()])); }
                    }
                    Ok(Some(Value::Object(groups.into_iter().map(|(k, v)| (k, Value::Array(v))).collect())))
                } else { Ok(Some(input.clone())) }
            }
            "unique" => {
                if let Value::Array(a) = input {
                    let mut seen: Vec<String> = Vec::new();
                    let mut out: Vec<Value> = Vec::new();
                    for el in a {
                        let k = serde_json::to_string(&value_to_json(el)).unwrap();
                        if !seen.contains(&k) { seen.push(k); out.push(el.clone()); }
                    }
                    Ok(Some(Value::Array(out)))
                } else { Ok(Some(input.clone())) }
            }
            "flatten" => {
                if let Value::Array(a) = input {
                    fn flat(a: &[Value], out: &mut Vec<Value>) { for v in a { if let Value::Array(inner) = v { flat(inner, out); } else { out.push(v.clone()); } } }
                    let mut out = Vec::new(); flat(a, &mut out);
                    Ok(Some(Value::Array(out)))
                } else { Ok(Some(input.clone())) }
            }
            "min" => {
                if let Value::Array(a) = input {
                    let nums: Vec<f64> = a.iter().filter_map(|v| if let Value::Number(n) = v { Some(*n) } else { None }).collect();
                    if nums.len() == a.len() && !nums.is_empty() { Ok(Some(Value::Number(nums.iter().cloned().fold(f64::INFINITY, f64::min)))) }
                    else { Ok(Some(Value::Null)) }
                } else { Ok(Some(Value::Null)) }
            }
            "max" => {
                if let Value::Array(a) = input {
                    let nums: Vec<f64> = a.iter().filter_map(|v| if let Value::Number(n) = v { Some(*n) } else { None }).collect();
                    if nums.len() == a.len() && !nums.is_empty() { Ok(Some(Value::Number(nums.iter().cloned().fold(f64::NEG_INFINITY, f64::max)))) }
                    else { Ok(Some(Value::Null)) }
                } else { Ok(Some(Value::Null)) }
            }
            "add" => {
                if let Value::Array(a) = input {
                    if !a.is_empty() && a.iter().all(|v| matches!(v, Value::Number(_))) {
                        let sum: f64 = a.iter().map(|v| if let Value::Number(n) = v { *n } else { 0.0 }).sum();
                        Ok(Some(Value::Number(sum)))
                    } else {
                        Ok(Some(Value::String(a.iter().map(text_of).collect::<Vec<_>>().join(""))))
                    }
                } else { Ok(Some(input.clone())) }
            }
            "stats" => Ok(Some(self.ctx.stats_object())),
            "levels" => Ok(Some(self.ctx.levels_object())),
            "langs" => Ok(Some(self.ctx.langs_object())),
            "types" => Ok(Some(self.ctx.types_object())),
            "text" => Ok(Some(Value::String(text_of(input)))),
            "upper" => Ok(Some(Value::String(text_of(input).to_uppercase()))),
            "lower" => Ok(Some(Value::String(text_of(input).to_lowercase()))),
            "ascii_upcase" => Ok(Some(Value::String(text_of(input).to_ascii_uppercase()))),
            "ascii_downcase" => Ok(Some(Value::String(text_of(input).to_ascii_lowercase()))),
            "trim" => Ok(Some(Value::String(text_of(input).trim().to_string()))),
            "slugify" => Ok(Some(Value::String(slugify(&text_of(input))))),
            "lines" => Ok(Some(Value::Number(text_of(input).lines().count() as f64))),
            "words" => Ok(Some(Value::Number(text_of(input).split_whitespace().count() as f64))),
            "chars" => Ok(Some(Value::Number(text_of(input).chars().count() as f64))),
            "content" => {
                match input {
                    Value::Heading(h) => Ok(Some(Value::String(h.content.clone()))),
                    Value::Document { content, .. } => Ok(Some(Value::String(content.clone()))),
                    _ => Ok(Some(Value::String(text_of(input)))),
                }
            }
            "md" => {
                match input {
                    Value::Heading(h) => Ok(Some(Value::String(h.raw_md.clone()))),
                    Value::Document { content, .. } => Ok(Some(Value::String(content.clone()))),
                    _ => Ok(Some(Value::String(text_of(input)))),
                }
            }
            "url" | "href" => {
                match input { Value::Link(l) => Ok(Some(Value::String(l.url.clone()))), Value::Image(im) => Ok(Some(Value::String(im.src.clone()))), _ => Ok(Some(Value::Null)) }
            }
            "src" => {
                match input { Value::Image(im) => Ok(Some(Value::String(im.src.clone()))), _ => Ok(Some(Value::Null)) }
            }
            "lang" | "language" => {
                match input { Value::Code(c) => Ok(Some(Value::String(c.language.clone().unwrap_or_default()))), _ => Ok(Some(Value::Null)) }
            }
            "type" => Ok(Some(Value::String(input.type_name().to_string()))),
            "keys" => {
                match input {
                    Value::Object(e) => Ok(Some(Value::Array(e.iter().map(|(k, _)| Value::String(k.clone())).collect()))),
                    Value::Array(a) => Ok(Some(Value::Array((0..a.len()).map(|i| Value::Number(i as f64)).collect()))),
                    _ => Ok(Some(Value::Array(vec![]))),
                }
            }
            "values" => {
                match input {
                    Value::Object(e) => Ok(Some(Value::Array(e.iter().map(|(_, v)| v.clone()).collect()))),
                    Value::Array(a) => Ok(Some(Value::Array(a.clone()))),
                    _ => Ok(Some(Value::Array(vec![]))),
                }
            }
            "has" => {
                let arg = self.eval_scalar(&args[0], input)?;
                let key = text_of(&arg);
                match input { Value::Object(e) => Ok(Some(Value::Bool(e.iter().any(|(k, _)| *k == key)))), _ => Ok(Some(Value::Bool(false))) }
            }
            "empty" => {
                let e = match input {
                    Value::String(s) => s.is_empty(),
                    Value::Array(a) => a.is_empty(),
                    Value::Object(e) => e.is_empty(),
                    Value::Null => true,
                    _ => false,
                };
                Ok(Some(Value::Bool(e)))
            }
            "debug" => {
                eprintln!("[DEBUG] {}", debug_value(input));
                Ok(Some(input.clone()))
            }
            "split" => {
                let arg = self.eval_scalar(&args[0], input)?;
                let sep = text_of(&arg);
                let text = text_of(input);
                if sep.is_empty() {
                    Ok(Some(Value::Array(text.chars().map(|c| Value::String(c.to_string())).collect())))
                } else {
                    Ok(Some(Value::Array(text.split(&sep).map(|s| Value::String(s.to_string())).collect())))
                }
            }
            "join" => {
                let arg = self.eval_scalar(&args[0], input)?;
                let sep = text_of(&arg);
                if let Value::Array(a) = input {
                    Ok(Some(Value::String(a.iter().map(text_of).collect::<Vec<_>>().join(&sep))))
                } else { Ok(Some(Value::String(text_of(input)))) }
            }
            "replace" => {
                let args_v = self.eval_arg_values(args, input)?;
                let from = text_of(&args_v[0]);
                let to = text_of(&args_v[1]);
                Ok(Some(Value::String(text_of(input).replace(&from, &to))))
            }
            "select" | "where" | "filter" => {
                let cond = self.eval_scalar(&args[0], input)?;
                if cond.is_truthy() { Ok(Some(input.clone())) } else { Ok(None) }
            }
            "contains" | "includes" => {
                let arg = self.eval_scalar(&args[0], input)?;
                let needle = text_of(&arg).to_lowercase();
                Ok(Some(Value::Bool(text_of(input).to_lowercase().contains(&needle))))
            }
            "startswith" => {
                let arg = self.eval_scalar(&args[0], input)?;
                Ok(Some(Value::Bool(text_of(input).to_lowercase().starts_with(&text_of(&arg).to_lowercase()))))
            }
            "endswith" => {
                let arg = self.eval_scalar(&args[0], input)?;
                Ok(Some(Value::Bool(text_of(input).to_lowercase().ends_with(&text_of(&arg).to_lowercase()))))
            }
            "matches" => {
                let arg = self.eval_scalar(&args[0], input)?;
                let pat = text_of(&arg);
                match Regex::new(&pat) { Ok(re) => Ok(Some(Value::Bool(re.is_match(&text_of(input))))), Err(_) => Ok(Some(Value::Bool(false))) }
            }
            "any" => {
                let arg_val = self.eval_scalar(&args[0], input)?;
                if let Value::Array(a) = input {
                    Ok(Some(Value::Bool(a.iter().any(|v| v.is_truthy()))))
                } else { Ok(Some(Value::Bool(arg_val.is_truthy()))) }
            }
            "all" => {
                let _arg_val = self.eval_scalar(&args[0], input)?;
                if let Value::Array(a) = input {
                    Ok(Some(Value::Bool(a.iter().all(|v| v.is_truthy()))))
                } else { Ok(Some(Value::Bool(input.is_truthy()))) }
            }
            _ => Err(unknown_function_error(name)),
        }
    }
}

fn is_heading_selector_name(name: &str) -> bool {
    matches!(name, "h" | "heading" | "headings" | "headers" | "h1" | "h2" | "h3" | "h4" | "h5" | "h6")
}

fn filter_matches(el: &Value, pattern: &str, exact: bool) -> bool {
    if let Value::Link(l) = el {
        if !exact {
            let p = pattern.to_lowercase();
            if p == "external" || p == "anchor" || p == "relative" { return l.link_type.as_str() == p; }
        }
    }
    let text = text_of(el);
    if exact { text.eq_ignore_ascii_case(pattern) } else { text.to_lowercase().contains(&pattern.to_lowercase()) }
}

fn slice_values(values: &[Value], start: Option<i64>, end: Option<i64>) -> Vec<Value> {
    let len = values.len() as i64;
    let resolve = |v: i64| -> i64 { if v < 0 { (len + v).max(0) } else { v.min(len) } };
    let s = start.map(resolve).unwrap_or(0);
    let e = end.map(resolve).unwrap_or(len);
    if s >= e || s >= len { return Vec::new(); }
    values[s as usize..e as usize].to_vec()
}

fn to_usize(v: &Value) -> usize {
    match v { Value::Number(n) => *n as usize, _ => 0 }
}
fn to_i64(v: &Value) -> i64 {
    match v { Value::Number(n) => *n as i64, _ => 0 }
}

fn sort_values(values: &mut [Value]) {
    values.sort_by(|a, b| {
        if let (Value::Number(x), Value::Number(y)) = (a, b) { return x.partial_cmp(y).unwrap_or(Ordering::Equal); }
        text_of(a).cmp(&text_of(b))
    });
}

fn group_key(v: &Value) -> String {
    match v {
        Value::Heading(h) => format!("h{}", h.level),
        Value::Code(c) => c.language.clone().unwrap_or_else(|| "none".to_string()),
        _ => text_of(v),
    }
}

fn values_equal(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Number(x), Value::Number(y)) => x == y,
        (Value::Number(x), Value::String(s)) | (Value::String(s), Value::Number(x)) => {
            s.trim().parse::<f64>().map(|y| *x == y).unwrap_or(false)
        }
        (Value::String(x), Value::String(y)) => x == y,
        (Value::Bool(x), Value::Bool(y)) => x == y,
        (Value::Null, Value::Null) => true,
        (Value::Array(x), Value::Array(y)) => x.len() == y.len() && x.iter().zip(y.iter()).all(|(u, v)| values_equal(u, v)),
        _ => {
            // elements/objects compared by json representation
            if a.type_name() != b.type_name() { return false; }
            serde_json::to_string(&value_to_json(a)).unwrap_or_default() == serde_json::to_string(&value_to_json(b)).unwrap_or_default()
        }
    }
}

fn debug_value(v: &Value) -> String {
    match v {
        Value::Heading(h) => format!("Heading(HeadingValue {{ level: {}, text: {:?}, offset: {}, line: {}, content: {:?}, raw_md: {:?}, index: {} }})", h.level, h.text, h.offset, h.line, h.content, h.raw_md, h.index),
        Value::Code(c) => format!("Code(CodeValue {{ language: {}, content: {:?}, start_line: {}, end_line: {} }})", match &c.language { Some(l) => format!("Some({:?})", l), None => "None".to_string() }, c.content, c.start_line, c.end_line),
        Value::Link(l) => format!("Link(LinkValue {{ text: {:?}, url: {:?}, link_type: {}, offset: {} }})", l.text, l.url, l.link_type.debug_name(), l.offset),
        Value::Table(t) => format!("Table(TableValue {{ headers: {:?}, rows: {:?}, alignments: {:?} }})", t.headers, t.rows, t.alignments),
        Value::List(l) => {
            let items: Vec<String> = l.items.iter().map(|(c, checked)| format!("ListItemValue {{ content: {:?}, checked: {} }}", c, match checked { Some(true) => "Some(true)".to_string(), Some(false) => "Some(false)".to_string(), None => "None".to_string() })).collect();
            format!("List(ListValue {{ ordered: {}, items: [{}] }})", l.ordered, items.join(", "))
        }
        Value::Document { content, heading_count, word_count } => format!("Document(DocumentValue {{ content: {:?}, heading_count: {}, word_count: {} }})", content, heading_count, word_count),
        Value::String(s) => format!("String({:?})", s),
        Value::Number(n) => format!("Number({:?})", n),
        Value::Bool(b) => format!("Bool({:?})", b),
        Value::Null => "Null".to_string(),
        Value::Array(a) => format!("Array([{}])", a.iter().map(debug_value).collect::<Vec<_>>().join(", ")),
        Value::Object(e) => format!("Object({{{}}})", e.iter().map(|(k, v)| format!("{:?}: {}", k, debug_value(v))).collect::<Vec<_>>().join(", ")),
        Value::Image(im) => format!("Image(ImageValue {{ alt: {:?}, src: {:?} }})", im.alt, im.src),
        Value::Blockquote(c) => format!("Blockquote({:?})", c),
    }
}
