    pub query_output: Option<String>,

    /// Markdown file(s) to view (.md or .markdown), directory, or '-' for stdin
    #[arg(value_name = "FILE", help = "Markdown file(s) to view (.md or .markdown), directory, or '-' for stdin", long_help = "Markdown file(s) to view (.md or .markdown), directory, or '-' for stdin\n\nPath to the markdown file(s) to open. Use '-' to read from stdin. If a directory is specified, opens file picker in that directory. Multiple files can be specified for the file picker. If no file is specified and stdin is piped, input is read from stdin.\n\nExamples: treemd README.md         # Open file treemd .                 # Open file picker in current directory treemd docs/             # Open file picker in docs directory treemd *.md              # Open file picker with matched files treemd -                 # Read from stdin cat doc.md | treemd -l   # Pipe markdown")]
