#[derive(Subcommand, Debug)]
pub enum Commands {
    /// Show heading at specific line number
    #[command(about = "Show heading at specific line number", long_about = "Show heading at specific line number\n\nFinds and displays the heading that appears at or before the given line number. Useful for jumping to a specific location in the document structure.")]
    AtLine {
        /// Line number in the markdown file
        #[arg(value_name = "LINE", help = "Line number in the markdown file", long_help = "Line number in the markdown file\n\nThe line number to search for. Returns the heading at or immediately before this line.")]
