            Err(e) => return Err(format!("Error reading input: I/O error: {}\n", e)),
        }
        if buf.is_empty() {
            return Err("Error reading input: Empty input provided\n".to_string());
        }
        return Ok(LoadedInput {
            document: parser::parse_document(&buf),
            source_name: None, source_path: None,
            picker_files: vec![], picker_dir: None,
            raw_content: buf, is_stdin: true,
        });
    }
    match std::fs::read_to_string(first_path) {
        Ok(buf) => {
            let name = first_path.file_name().map(|s| s.to_string_lossy().to_string());
            // multiple files -> picker (used by TUI)
            let mut picker_files = vec![];
            if cli.files.len() > 1 {
                for f in &cli.files { picker_files.push(Path::new(f).to_path_buf()); }
            }
            Ok(LoadedInput {
                document: parser::parse_document(&buf),
                source_name: name, source_path: Some(first_path.to_path_buf()),
                picker_files, picker_dir: None,
                raw_content: buf, is_stdin: false,
            })
        }
        Err(e) => Err(format!("Error reading input: I/O error: {}\n", e)),
    }
}

fn print_tree(sections: &[parser::Section], prefix: &str, out: &mut String) {
    let n = sections.len();
    for (i, sec) in sections.iter().enumerate() {
        let last = i + 1 == n;
        let connector = if last { "└──" } else { "├──" };
        out.push_str(&format!("{}{}{} {}\n", prefix, connector, "#".repeat(sec.level as usize), sec.title));
        let child_prefix = format!("{}{}", prefix, if last { "   " } else { "│  " });
        print_tree(&sec.children, &child_prefix, out);
    }
}

fn flat_headings(doc: &Document) -> Vec<(u8, String)> {
    doc.flat_sections().iter().map(|s| (s.level, s.title.clone())).collect()
}

fn run_cli_modes(cli: &Cli, loaded: &LoadedInput) -> Option<ExitCode> {
    let doc = &loaded.document;
    // query mode
    if let Some(q) = &cli.query {
        let fmt_raw = cli.query_output.clone().unwrap_or_else(|| "plain".to_string());
        let fmt_lower = fmt_raw.to_lowercase();
        let fmt = match fmt_lower.as_str() {
            "plain" => "plain",
            "json" => "json",
            "json-pretty" => "json-pretty",
            "jsonl" => "jsonl",
            "md" => "md",
            "tree" => "tree",
            _ => {
                eprint!("Error: Unknown output format: {}\n", fmt_raw);
                return Some(ExitCode::from(1));
            }
        };
        match query::run_query(doc, q) {
            Ok(results) => {
                print!("{}", query::format_output(&results, fmt));
                let _ = std::io::stdout().flush();
                return Some(ExitCode::SUCCESS);
            }
            Err(e) => {
                eprint!("{}", e.message);
                return Some(ExitCode::from(1));
            }
        }
    }
    if cli.count {
        let mut counts: Vec<(u8, usize)> = Vec::new();
        for (lvl, _) in flat_headings(doc) {
            if let Some(e) = counts.iter_mut().find(|(l, _)| *l == lvl) { e.1 += 1; } else { counts.push((lvl, 1)); }
        }
        counts.sort_by_key(|(l, _)| *l);
        let mut out = String::from("Heading counts:\n");
        for (lvl, c) in &counts {
            out.push_str(&format!("  {}: {}\n", "#".repeat(*lvl as usize), c));
        }
        out.push_str(&format!("\nTotal: {}\n", doc.heading_count));
        print!("{}", out);
        return Some(ExitCode::SUCCESS);
    }
    if let Some(section_name) = &cli.section {
        let flat = doc.flat_sections();
        let found = flat.iter().enumerate().find(|(_, s)| s.title.to_lowercase() == section_name.to_lowercase());
        match found {
            None => {
                eprintln!("Section '{}' not found", section_name);
                return Some(ExitCode::from(1));
            }
            Some((idx, sec)) => {
                let level = sec.level;
                let title = sec.title.clone();
                let marker = format!("{} {}", "#".repeat(level as usize), title);
                if let Some(start) = doc.content.find(&marker) {
                    let mut end = doc.content.len();
                    for other in flat.iter().skip(idx + 1) {
                        if other.level <= level {
                            let m2 = format!("{} {}", "#".repeat(other.level as usize), other.title);
                            if let Some(pos) = doc.content.find(&m2) { end = pos; break; }
                        }
                    }
                    if end <= start {
                        print!("\n");
                    } else {
                        let slice = &doc.content[start..end];
                        print!("{}\n", slice.trim_end());
                    }
                } else {
                    // marker not found: print nothing
                }
                return Some(ExitCode::SUCCESS);
            }
        }
    }
    if cli.list || cli.tree {
        match cli.output {
            OutputFormat::Json => {
                if cli.tree {
                    let items: Vec<serde_json::Value> = flat_headings(doc).iter().map(|(l, t)| {
                        serde_json::json!({"level": l, "text": t})
                    }).collect();
                    println!("{}", serde_json::to_string_pretty(&serde_json::Value::Array(items)).unwrap());
                } else {
                    let data = serde_json::json!({"document": serde_json::to_value(doc.data()).unwrap()});
                    println!("{}", serde_json::to_string_pretty(&data).unwrap());
                }
                return Some(ExitCode::SUCCESS);
            }
            OutputFormat::Tree => {
                if cli.tree {
                    let mut out = String::new();
                    print_tree(&doc.sections, "", &mut out);
                    print!("{}", out);
                    return Some(ExitCode::SUCCESS);
                } else {
                    eprint!("Use --tree for tree output\n");
                    return Some(ExitCode::from(1));
                }
            }
            OutputFormat::Plain => {
                if cli.tree {
                    let mut out = String::new();
                    print_tree(&doc.sections, "", &mut out);
                    print!("{}", out);
                    return Some(ExitCode::SUCCESS);
                } else {
                    let headings = flat_headings(doc);
                    let filtered: Vec<(u8, String)> = if let Some(level) = cli.level {
                        headings.into_iter().filter(|(l, _)| *l as usize == level).collect()
                    } else if let Some(f) = &cli.filter {
                        let fl = f.to_lowercase();
                        headings.into_iter().filter(|(_, t)| t.to_lowercase().contains(&fl)).collect()
                    } else { headings };
                    for (lvl, title) in filtered {
                        println!("{} {}", "#".repeat(lvl as usize), title);
                    }
                    return Some(ExitCode::SUCCESS);
                }
            }
        }
    }
    if let Some(Commands::AtLine { line: _ }) = &cli.command {
        return Some(ExitCode::SUCCESS);
    }
    None
}

fn main() -> ExitCode {
    clap_complete::env::CompleteEnv::with_factory(|| Cli::command()).complete();
    let cli = Cli::parse();
    if cli.setup_completions {
        return completions_setup::setup_completions();
    }
    if cli.query_help {
        print!("{}", completions_setup::QUERY_HELP);
        return ExitCode::SUCCESS;
    }
    let loaded = match load_input(&cli) {
        Ok(l) => l,
        Err(msg) => {
            eprint!("{}", msg);
            return ExitCode::from(1);
        }
    };
    if let Some(code) = run_cli_modes(&cli, &loaded) {
        return code;
    }
    // TUI mode
    tui::run_tui(&cli, loaded)
}
