use std::io::Write;
use std::process::ExitCode;

pub const QUERY_HELP: &str = include_str!("query_help.txt");

pub fn setup_completions() -> ExitCode {
    match do_setup() {
        Ok(()) => ExitCode::SUCCESS,
        Err(msg) => {
            eprintln!("Error setting up completions: {}", msg);
            print_instructions();
            ExitCode::from(1)
        }
    }
}

fn print_instructions() {
    println!("Shell Completion Setup Instructions");
    println!();
    println!("Add the appropriate line to your shell config:");
    println!();
    println!("Bash (~/.bashrc):");
    println!("  source <(COMPLETE=bash treemd)");
    println!();
    println!("Zsh (~/.zshrc):");
    println!("  source <(COMPLETE=zsh treemd)");
    println!();
    println!("Fish (~/.config/fish/config.fish):");
    println!("  COMPLETE=fish treemd | source");
    println!();
    println!("After adding the line, restart your shell or source the config file.");
}

fn do_setup() -> Result<(), String> {
    let shell_env = std::env::var("SHELL").map_err(|_| "Could not detect shell".to_string())?;
    let shell = shell_env.rsplit('/').next().unwrap_or("").to_string();
    println!("Detected shell: {}", shell);
    let home = std::env::var("HOME").unwrap_or_default();
    let (config_path, line): (String, String) = match shell.as_str() {
        "bash" => (format!("{}/.bashrc", home), "source <(COMPLETE=bash treemd)".to_string()),
        "zsh" => (format!("{}/.zshrc", home), "source <(COMPLETE=zsh treemd)".to_string()),
        "fish" => (format!("{}/.config/fish/config.fish", home), "COMPLETE=fish treemd | source".to_string()),
        _ => return Err(format!("Unsupported shell: {}", shell)),
    };
    // already set up?
    if let Ok(existing) = std::fs::read_to_string(&config_path) {
        if existing.contains(&line) {
            println!("✓ Shell completions are already set up in \"{}\"", config_path);
            return Ok(());
        }
    }
    println!();
    println!("To enable shell completions, add this line to \"{}\":", config_path);
    println!("  {}", line);
    println!();
    print!("Would you like to add it automatically? (y/N): ");
    let _ = std::io::stdout().flush();
    let mut answer = String::new();
    let _ = std::io::stdin().read_line(&mut answer);
    println!();
    if answer.trim().to_lowercase() == "y" {
        let addition = format!("\n# treemd shell completion\n{}\n", line);
        match std::fs::OpenOptions::new().create(true).append(true).open(&config_path) {
            Ok(mut f) => {
                if let Err(e) = f.write_all(addition.as_bytes()) {
                    return Err(e.to_string());
                }
            }
            Err(e) => return Err(e.to_string()),
        }
        println!("✓ Added completions to \"{}\"", config_path);
        println!();
        println!("Restart your shell or run:");
        println!("  source \"{}\"", config_path);
    } else {
        println!();
        println!("Manually add the line above to enable completions.");
    }
    Ok(())
}
