cat >> src/completions_setup.rs <<'RS'

fn bin_path_for_script() -> String {
    let argv0 = std::env::args().next().unwrap_or_else(|| "treemd".to_string());
    if argv0.starts_with('/') {
        argv0
    } else if argv0.contains('/') {
        let cwd = std::env::current_dir().map(|p| p.to_string_lossy().to_string()).unwrap_or_default();
        format!("{}/{}", cwd, argv0)
    } else {
        argv0
    }
}

pub fn handle_complete_env() -> Option<std::process::ExitCode> {
    let shell = match std::env::var("COMPLETE") {
        Ok(v) if !v.is_empty() => v,
        _ => return None,
    };
    let args: Vec<String> = std::env::args().collect();
    // Completion request: binary -- words... with _CLAP_COMPLETE_INDEX set
    if args.get(1).map(|s| s == "--").unwrap_or(false) && std::env::var("_CLAP_COMPLETE_INDEX").is_ok() {
        return Some(crate::completions_setup::dynamic::handle_dynamic(&args));
    }
    let template: &str = match shell.as_str() {
        "bash" => include_str!("completion_templates/bash.txt"),
        "zsh" => include_str!("completion_templates/zsh.txt"),
        "fish" => include_str!("completion_templates/fish.txt"),
        "elvish" => include_str!("completion_templates/elvish.txt"),
        "powershell" => include_str!("completion_templates/powershell.txt"),
        _ => {
            eprint!("error: unknown shell `{}`, expected one of `bash`, `elvish`, `fish`, `powershell`, `zsh`", shell);
            return Some(std::process::ExitCode::from(2));
        }
    };
    print!("{}", template.replace("__BIN_PATH__", &bin_path_for_script()));
    Some(std::process::ExitCode::SUCCESS)
}

pub mod dynamic {
    use std::process::ExitCode;
    pub fn handle_dynamic(args: &[String]) -> ExitCode {
        // args: [bin, "--", words...]
        let words: Vec<String> = args.iter().skip(2).cloned().collect();
        if words.is_empty() || words[0] != "treemd" {
            eprint!("error: no completion generated");
            return ExitCode::from(2);
        }
        let index: usize = std::env::var("_CLAP_COMPLETE_INDEX").ok().and_then(|v| v.parse().ok()).unwrap_or(words.len().saturating_sub(1));
        let current: String = if index < words.len() { words[index].clone() } else { String::new() };
        let candidates = super::generate_candidates(&words, index, &current);
        if candidates.is_empty() {
            // clap still returns candidates-empty as success in many cases; match observed no-candidate success except program mismatch.
            // Print nothing.
            return ExitCode::SUCCESS;
        }
        let sep = std::env::var("_CLAP_IFS").unwrap_or_else(|_| "\n".to_string());
        print!("{}", candidates.join(&sep));
        ExitCode::SUCCESS
    }
}

fn generate_candidates(words: &[String], index: usize, current: &str) -> Vec<String> {
    // Determine if we're completing an option value
    let prev = if index >= 2 && index <= words.len() { Some(words[index - 1].as_str()) } else { None };
    // If inside at-line subcommand (words[1] == at-line), no useful candidates
    if words.get(1).map(|s| s == "at-line").unwrap_or(false) {
        return vec![];
    }
    if let Some(p) = prev {
        match p {
            "--output" | "-o" => {
                return ["plain", "json", "tree"].iter().filter(|v| v.starts_with(current)).map(|s| s.to_string()).collect();
            }
            "--color-mode" => {
                return ["auto", "rgb", "256"].iter().filter(|v| v.starts_with(current)).map(|s| s.to_string()).collect();
            }
            "--theme" => {
                return ["OceanDark", "Nord", "Dracula", "Solarized", "Monokai", "Gruvbox", "TokyoNight", "CatppuccinMocha"].iter().filter(|v| v.starts_with(current)).map(|s| s.to_string()).collect();
            }
            "--level" | "-L" | "--filter" | "--section" | "-s" | "--query" | "-q" | "--query-output" => {
                return vec![];
            }
            _ => {}
        }
    }
    let mut out: Vec<String> = Vec::new();
    let is_flag_context = current.starts_with('-');
    if current == "-" {
        // short if available else long, in definition order
        let flags = ["-l", "--tree", "--filter", "-L", "-o", "-s", "--count", "--setup-completions", "--theme", "--color-mode", "--no-images", "--images", "-q", "--query-help", "--query-output", "-h", "-V"];
        return flags.iter().map(|s| s.to_string()).collect();
    }
    if is_flag_context {
        let longs = ["--list", "--tree", "--filter", "--level", "--output", "--section", "--count", "--setup-completions", "--theme", "--color-mode", "--no-images", "--images", "--query", "--query-help", "--query-output", "--help", "--version"];
        return longs.iter().filter(|v| v.starts_with(current)).map(|s| s.to_string()).collect();
    }
    // subcommands
    for cand in ["at-line", "help"] {
        if cand.starts_with(current) { out.push(cand.to_string()); }
    }
    // files / dirs matching current (split into dir prefix + file prefix)
    let (dir_part, file_prefix) = match current.rfind('/') {
        Some(pos) => (current[..=pos].to_string(), current[pos + 1..].to_string()),
        None => (String::new(), current.to_string()),
    };
    let search_dir = if dir_part.is_empty() { ".".to_string() } else { dir_part.trim_end_matches('/').to_string() };
    if let Ok(rd) = std::fs::read_dir(&search_dir) {
        let mut dirs: Vec<String> = Vec::new();
        let mut files: Vec<String> = Vec::new();
        for entry in rd.flatten() {
            let name = entry.file_name().to_string_lossy().to_string();
            if !name.starts_with(&file_prefix) { continue; }
            let ft = match entry.file_type() { Ok(f) => f, Err(_) => continue };
            if ft.is_dir() {
                dirs.push(format!("{}{}/", dir_part, name));
            } else if name.to_lowercase().ends_with(".md") || name.to_lowercase().ends_with(".markdown") {
                files.push(format!("{}{}", dir_part, name));
            }
        }
        dirs.sort();
        files.sort();
        out.extend(dirs);
        out.extend(files);
    }
    // long flags (when current empty or matching)
    if current.is_empty() || current.starts_with('-') {
        let longs = ["--list", "--tree", "--filter", "--level", "--output", "--section", "--count", "--setup-completions", "--theme", "--color-mode", "--no-images", "--images", "--query", "--query-help", "--query-output", "--help", "--version"];
        for f in longs { if f.starts_with(current) { out.push(f.to_string()); } }
    } else {
        // starting with a letter: flags only if they match (they start with '-', so none) - matches original (only at-line + a.md for "a")
    }
    out
}
