    let cand = |v: &str| (v.to_string(), flag_desc(v));
    // help subcommand context: completing subcommand name argument
    if words.get(1).map(|s| s == "help").unwrap_or(false) && index == 2 {
        return ["at-line", "help"].iter().filter(|v| v.starts_with(current)).map(|v| cand(v)).collect();
    }
    // at-line subcommand context
    if words.get(1).map(|s| s == "at-line").unwrap_or(false) {
        if current == "-" { return vec![cand("-h")]; }
        if current.starts_with('-') { return ["--help"].iter().filter(|v| v.starts_with(current)).map(|v| cand(v)).collect(); }
        if current.is_empty() { return vec![cand("--help")]; }
        return vec![];
    }
    // Determine if we're completing an option value
    let prev = if index >= 2 && index <= words.len() { Some(words[index - 1].as_str()) } else { None };
    if let Some(p) = prev {
        match p {
            "--output" | "-o" => {
                return ["plain", "json", "tree"].iter().filter(|v| v.starts_with(current)).map(|v| cand(v)).collect();
            }
            "--color-mode" => {
                return ["auto", "rgb", "256"].iter().filter(|v| v.starts_with(current)).map(|v| cand(v)).collect();
            }
            "--theme" | "--level" | "-L" | "--filter" | "--section" | "-s" | "--query" | "-q" | "--query-output" => {
                return vec![];
            }
            _ => {}
        }
    }
    let mut out: Vec<(String, Option<String>)> = Vec::new();
    if current == "-" {
        let flags = ["-l", "--tree", "--filter", "-L", "-o", "-s", "--count", "--setup-completions", "--theme", "--color-mode", "--no-images", "--images", "-q", "--query-help", "--query-output", "-h", "-V"];
        return flags.iter().map(|v| cand(v)).collect();
    }
    if current.starts_with('-') {
        let longs = ["--list", "--tree", "--filter", "--level", "--output", "--section", "--count", "--setup-completions", "--theme", "--color-mode", "--no-images", "--images", "--query", "--query-help", "--query-output", "--help", "--version"];
        return longs.iter().filter(|v| v.starts_with(current)).map(|v| cand(v)).collect();
    }
    for v in ["at-line", "help"] {
        if v.starts_with(current) { out.push(cand(v)); }
    }
    let (dir_part, file_prefix) = match current.rfind('/') {
        Some(pos) => (current[..=pos].to_string(), current[pos + 1..].to_string()),
        None => (String::new(), current.to_string()),
    };
    let search_dir = if dir_part.is_empty() { ".".to_string() } else { dir_part.trim_end_matches('/').to_string() };
    if let Ok(rd) = std::fs::read_dir(&search_dir) {
        let mut dirs: Vec<String> = Vec::new();
        let mut files: Vec<String> = Vec::new();
        for entry in rd.flatten() {
            let name = entry.file_name().to_string_lossy().to_string();
            if !name.starts_with(&file_prefix) { continue; }
            let ft = match entry.file_type() { Ok(f) => f, Err(_) => continue };
            if ft.is_dir() {
                dirs.push(format!("{}{}/", dir_part, name));
            } else if name.to_lowercase().ends_with(".md") || name.to_lowercase().ends_with(".markdown") {
                files.push(format!("{}{}", dir_part, name));
            }
        }
        dirs.sort();
        files.sort();
        for d in dirs { out.push((d, Some("directory".to_string()))); }
        for f in files { out.push((f, None)); }
    }
    if current.is_empty() {
        let longs = ["--list", "--tree", "--filter", "--level", "--output", "--section", "--count", "--setup-completions", "--theme", "--color-mode", "--no-images", "--images", "--query", "--query-help", "--query-output", "--help", "--version"];
        for f in longs { out.push(cand(f)); }
    }
    out
}
'''
