        let index: usize = std::env::var("_CLAP_COMPLETE_INDEX").ok().and_then(|v| v.parse().ok()).unwrap_or(words.len().saturating_sub(1));
        let current: String = if index < words.len() { words[index].clone() } else { String::new() };
        let candidates = super::generate_candidates(&words, index, &current);
        if candidates.is_empty() {
            return ExitCode::SUCCESS;
        }
        match shell.as_str() {
            "zsh" => {
                let parts: Vec<String> = candidates.iter().map(|(v, d)| match d {
                    Some(desc) => format!("{}:{}", v, desc),
                    None => v.clone(),
                }).collect();
                print!("{}", parts.join("\n"));
            }
            "fish" | "powershell" => {
                let mut out = String::new();
                for (v, d) in &candidates {
                    match d {
                        Some(desc) => out.push_str(&format!("{}\t{}\n", v, desc)),
                        None => out.push_str(&format!("{}\n", v)),
                    }
                }
                print!("{}", out);
            }
            _ => {
                let sep = std::env::var("_CLAP_IFS").unwrap_or_else(|_| "\n".to_string());
                let parts: Vec<String> = candidates.iter().map(|(v, _)| v.clone()).collect();
                print!("{}", parts.join(&sep));
            }
        }
        ExitCode::SUCCESS
    }
}

fn flag_desc(v: &str) -> Option<String> {
    let d = match v {
        "at-line" => "Show heading at specific line number",
        "help" => "Print this message or the help of the given subcommand(s)",
        "-l" | "--list" => "List all headings in the document (non-interactive)",
        "--tree" => "Show heading tree structure with box-drawing characters (non-interactive)",
        "--filter" => "Filter headings by text pattern (case-insensitive)",
        "-L" | "--level" => "Show only headings at specific level (1-6)",
        "-o" | "--output" => "Output format for --list and --tree modes",
        "-s" | "--section" => "Extract specific section by heading name",
        "--count" => "Count headings by level (shows statistics)",
        "--setup-completions" => "Set up shell completions interactively",
        "--theme" => "Set theme for TUI mode",
        "--color-mode" => "Force color mode (auto, rgb, 256)",
        "--no-images" => "Disable image rendering in TUI mode",
        "--images" => "Enable image rendering in TUI mode (override config)",
        "-q" | "--query" => "Query expression for selecting/filtering document elements",
        "--query-help" => "Show query language documentation and examples",
        "--query-output" => "Output format for query results",
        "-h" | "--help" => "Print help (see more with '--help')",
        "-V" | "--version" => "Print version",
        "plain" => "Plain text output",
        "json" => "JSON output",
        "tree" => "Tree format with box-drawing",
        "auto" => "Automatically detect terminal capabilities",
        "rgb" => "Force RGB/true color mode",
        "256" => "Force 256-color mode",
        _ => return None,
    };
    Some(d.to_string())
}

