                if let Some(eq) = t.find('=') {
                    let key = t[..eq].trim();
                    let val = t[eq + 1..].trim().trim_matches('"').to_string();
                    match (section.as_str(), key) {
                        ("ui", "theme") => cfg.theme = val,
                        ("ui", "outline_width") => cfg.outline_width = val.parse().unwrap_or(cfg.outline_width),
                        ("ui", "tree_style") => cfg.tree_style = val,
                        ("terminal", "color_mode") => cfg.color_mode = val,
                        ("terminal", "warned_terminal_app") => cfg.warned_terminal_app = val == "true",
                        ("images", "enabled") => cfg.images_enabled = val == "true",
                        ("content", "hide_frontmatter") => cfg.hide_frontmatter = val == "true",
                        ("content", "hide_latex") => cfg.hide_latex = val == "true",
                        ("content", "latex_aggressive") => cfg.latex_aggressive = val == "true",
                        _ => {}
                    }
                }
            }
        }
    }
    cfg
}
pub fn save_config(cfg: &AppConfig) {
    if let Some(path) = config_path() {
        if let Some(parent) = path.parent() { let _ = std::fs::create_dir_all(parent); }
        let text = format!(
            "[ui]\ntheme = \"{}\"\noutline_width = {}\ntree_style = \"{}\"\n\n[terminal]\ncolor_mode = \"{}\"\nwarned_terminal_app = {}\n\n[theme]\n\n[keybindings]\n\n[editor]\n\n[images]\nenabled = {}\n\n[content]\nhide_frontmatter = {}\nhide_latex = {}\nlatex_aggressive = {}\n",
            cfg.theme, cfg.outline_width, cfg.tree_style, cfg.color_mode, cfg.warned_terminal_app,
            cfg.images_enabled, cfg.hide_frontmatter, cfg.hide_latex, cfg.latex_aggressive
        );
        let _ = std::fs::write(&path, text);
    }
}

