            "[ui]\ntheme = \"{}\"\noutline_width = {}\ntree_style = \"{}\"\n\n[terminal]\ncolor_mode = \"{}\"\nwarned_terminal_app = {}\n\n[theme]\n\n[keybindings]\n\n[editor]\n\n[images]\nenabled = {}\n\n[content]\nhide_frontmatter = {}\nhide_latex = {}\nlatex_aggressive = {}\n",
