// ===================== Drawing buffer =====================
#[derive(Clone, Copy, PartialEq, Debug)]
pub struct Style {
    pub fg: Option<Color>, pub bg: Option<Color>,
    pub bold: bool, pub italic: bool, pub underline: bool,
}
impl Default for Style {
    fn default() -> Self { Style { fg: None, bg: None, bold: false, italic: false, underline: false } }
}
#[derive(Clone)]
struct Cell { ch: char, style: Style, cont: bool }
pub struct Buffer {
    pub w: usize, pub h: usize, cells: Vec<Cell>,
}
impl Buffer {
    fn new(w: usize, h: usize, base: Style) -> Self {
        Buffer { w, h, cells: vec![Cell { ch: ' ', style: base, cont: false }; w * h] }
    }
    fn idx(&self, x: usize, y: usize) -> usize { y * self.w + x }
    fn set_cell(&mut self, x: usize, y: usize, ch: char, style: Style) {
        if x < self.w && y < self.h { let i = self.idx(x, y); self.cells[i] = Cell { ch, style, cont: false }; }
    }
    fn fill_rect(&mut self, x: usize, y: usize, w: usize, h: usize, style: Style) {
        for yy in y..(y + h).min(self.h) {
            for xx in x..(x + w).min(self.w) {
                self.set_cell(xx, yy, ' ', style);
            }
        }
    }
    fn draw_text(&mut self, x: usize, y: usize, text: &str, style: Style, max_w: usize) {
        let mut cx = x;
        let limit = (x + max_w).min(self.w);
        for ch in text.chars() {
            if cx >= limit { break; }
            let width = UnicodeWidthChar::width(ch).unwrap_or(0);
            if width == 0 { continue; }
            if cx + width > limit { break; }
            self.set_cell(cx, y, ch, style);
            if width == 2 && cx + 1 < limit { let i = self.idx(cx + 1, y); self.cells[i] = Cell { ch: ' ', style, cont: true }; }
            cx += width;
        }
    }
    fn render_ansi(&self, rgb_mode: bool) -> String {
        let mut out = String::from("\x1b[?25l\x1b[H");
        for y in 0..self.h {
            out.push_str(&format!("\x1b[{};1H", y + 1));
            let mut cur_style: Option<Style> = None;
            for x in 0..self.w {
                let cell = &self.cells[y * self.w + x];
                if cell.cont { continue; }
                if cur_style.map(|s| s != cell.style).unwrap_or(true) {
                    out.push_str("\x1b[0m");
                    let st = cell.style;
                    if st.bold { out.push_str("\x1b[1m"); }
                    if st.italic { out.push_str("\x1b[3m"); }
                    if st.underline { out.push_str("\x1b[4m"); }
                    if let Some(c) = st.fg { out.push_str(&color_code(c, rgb_mode, true)); }
                    if let Some(c) = st.bg { out.push_str(&color_code(c, rgb_mode, false)); }
                    cur_style = Some(st);
                }
                out.push(cell.ch);
            }
        }
        out.push_str("\x1b[0m");
        out
    }
}
fn color_code(c: Color, rgb: bool, fg: bool) -> String {
    if rgb {
        format!("\x1b[{};2;{};{};{}m", if fg { 38 } else { 48 }, c.1.0, c.1.1, c.1.2)
    } else {
        format!("\x1b[{};5;{}m", if fg { 38 } else { 48 }, c.0)
    }
}

