}

pub struct App {
    doc: Document,
    flat: Vec<Section>,
    nodes: Vec<AppNode>,
    selected_node: usize,
    outline_scroll: usize,
    content_scroll: usize,
    focus: Focus,
    outline_hidden: bool,
    outline_width: usize,
    theme: Theme,
    config: AppConfig,
    rgb_mode: bool,
    source_name: String,
    source_path: Option<PathBuf>,
    raw_content: String,
    is_stdin_source: bool,
    message: Option<String>,
    help_visible: bool,
    help_scroll: usize,
    search: Option<SearchState>,
    picker: Option<PickerState>,
