    checkbox_counter: HashMap<usize, Vec<bool>>, // flat section idx -> checked states in block order (mirrors doc)
    table_edit: Option<(String, usize, usize)>, // editing prompt text, el idx, cell?
}

impl App {
    fn rebuild_nodes(&mut self) {
        fn walk(sections: &[Section], depth: usize, parent: Option<usize>, nodes: &mut Vec<AppNode>) {
            for sec in sections {
                let idx = nodes.len();
                nodes.push(AppNode { section: sec.clone(), depth, parent, has_children: !sec.children.is_empty(), expanded: true, bookmark: false });
                walk(&sec.children, depth + 1, Some(idx), nodes);
            }
        }
        let mut nodes = Vec::new();
        walk(&self.doc.sections, 0, None, &mut nodes);
        // Preserve expanded/bookmark state by title+depth if rebuilding same doc size
        if nodes.len() == self.nodes.len() {
            for (n, o) in nodes.iter_mut().zip(self.nodes.iter()) { n.expanded = o.expanded; n.bookmark = o.bookmark; }
        }
        self.nodes = nodes;
        self.flat = self.doc.flat_sections();
        if self.selected_node >= self.nodes.len() { self.selected_node = 0; }
    }
    fn visible_nodes(&self) -> Vec<usize> {
        let filter_q = self.search.as_ref().and_then(|s| {
            if s.kind == SearchKind::Outline && !s.query.is_empty() { Some(s.query.to_lowercase()) } else { None }
        });
        let mut out = Vec::new();
        for (i, n) in self.nodes.iter().enumerate() {
            // ancestors expanded?
            let mut visible = true;
            let mut p = n.parent;
            while let Some(pi) = p {
                if !self.nodes[pi].expanded { visible = false; break; }
                p = self.nodes[pi].parent;
            }
            if !visible { continue; }
            if let Some(q) = &filter_q {
                if !n.section.title.to_lowercase().contains(q) { continue; }
            }
            if self.todo_filter && !self.subtree_has_open_todo(i) { continue; }
            out.push(i);
        }
        out
    }
    fn subtree_has_open_todo(&self, node_idx: usize) -> bool {
        // check section's own blocks and descendants in flat doc order via nodes subtree
        let node = &self.nodes[node_idx];
        fn blocks_have(blocks: &[Block]) -> bool {
            for b in blocks {
                match b {
                    Block::List { items, .. } => {
                        if items.iter().any(|it| it.checked == Some(false)) { return true; }
                        for it in items { if blocks_have(&it.blocks) { return true; } }
                    }
                    Block::Blockquote { blocks, .. } => if blocks_have(blocks) { return true; },
                    _ => {}
                }
            }
            false
        }
        if blocks_have(&node.section.content.blocks) { return true; }
        // descendants are following nodes with greater depth until depth <=
        let depth = node.depth;
        for n in self.nodes.iter().skip(node_idx + 1) {
            if n.depth <= depth { break; }
            if blocks_have(&n.section.content.blocks) { return true; }
        }
        false
    }
    fn selected_flat_idx(&self) -> usize {
        // nodes are preorder; flat sections are also preorder, indices correspond
        self.selected_node.min(self.flat.len().saturating_sub(1))
    }
    fn collect_links_for_selected(&self) -> Vec<(String, String)> {
        // links from selected section subtree (flat following nodes until level <= selected level)
        let start = self.selected_flat_idx();
        if self.flat.is_empty() { return vec![]; }
        let base_level = self.flat[start].level;
        let ctx = crate::query::QueryContext::build(&self.doc);
        // Use document-order links but restrict by section membership: simpler: collect from own+descendant sections' blocks
        let mut out = Vec::new();
        for (fi, sec) in self.flat.iter().enumerate().skip(start) {
            if fi > start && sec.level <= base_level { break; }
            collect_links_from_section(sec, &mut out);
            let _ = &ctx;
        }
        out
    }
    fn collect_interactive(&self) -> Vec<InteractiveElement> {
        let start = self.selected_flat_idx();
        if self.flat.is_empty() { return vec![]; }
        let base_level = self.flat[start].level;
        let mut els: Vec<InteractiveElement> = Vec::new();
        for (fi, sec) in self.flat.iter().enumerate().skip(start) {
            if fi > start && sec.level <= base_level { break; }
            collect_interactive_from_section(sec, fi, &mut els);
        }
        els
    }
}

fn collect_links_from_section(sec: &Section, out: &mut Vec<(String, String)>) {
    fn from_blocks(blocks: &[Block], out: &mut Vec<(String, String)>) {
        for b in blocks {
            match b {
                Block::Paragraph { inline, .. } | Block::Heading { inline, .. } => {
                    for inl in inline { if let Inline::Link { text, url, .. } = inl { out.push((text.clone(), url.clone())); } }
                }
                Block::List { items, .. } => {
                    for it in items {
                        for inl in &it.inline { if let Inline::Link { text, url, .. } = inl { out.push((text.clone(), url.clone())); } }
                        from_blocks(&it.blocks, out);
                    }
                }
                Block::Table { headers, rows, .. } => {
                    let empty = crate::parser::collect_refs("");
                    for cell in headers.iter().chain(rows.iter().flatten()) {
                        for inl in crate::parser::parse_inline(cell, &empty) {
                            if let Inline::Link { text, url, .. } = &inl { out.push((text.clone(), url.clone())); }
                        }
                    }
                }
                Block::Blockquote { blocks, .. } => from_blocks(blocks, out),
                _ => {}
            }
        }
    }
    for inl in &sec.title_inline { if let Inline::Link { text, url, .. } = inl { out.push((text.clone(), url.clone())); } }
    from_blocks(&sec.content.blocks, out);
}

fn collect_interactive_from_section(sec: &Section, flat_idx: usize, els: &mut Vec<InteractiveElement>) {
    fn walk(blocks: &[Block], flat_idx: usize, els: &mut Vec<InteractiveElement>, checkbox_counter: &mut usize) {
        for b in blocks {
            match b {
                Block::Code { content, language, .. } => {
                    els.push(InteractiveElement { kind: "code".into(), display_text: content.clone(), copy_text: content.clone(), link_url: None, section_flat_idx: flat_idx, checkbox_index: None, line_hint: els.len() });
                    let _ = language;
                }
                Block::List { items, .. } => {
                    for it in items {
                        if it.checked.is_some() {
                            let ci = *checkbox_counter;
                            *checkbox_counter += 1;
                            els.push(InteractiveElement { kind: "checkbox".into(), display_text: it.content.clone(), copy_text: it.content.clone(), link_url: None, section_flat_idx: flat_idx, checkbox_index: Some(ci), line_hint: els.len() });
                        }
                        for inl in &it.inline {
                            if let Inline::Link { text, url, .. } = inl {
                                els.push(InteractiveElement { kind: "link".into(), display_text: text.clone(), copy_text: url.clone(), link_url: Some(url.clone()), section_flat_idx: flat_idx, checkbox_index: None, line_hint: els.len() });
                            }
                            if let Inline::Image { alt, src, .. } = inl {
                                els.push(InteractiveElement { kind: "image".into(), display_text: alt.clone(), copy_text: src.clone(), link_url: None, section_flat_idx: flat_idx, checkbox_index: None, line_hint: els.len() });
                            }
                        }
                        walk(&it.blocks, flat_idx, els, checkbox_counter);
                    }
                }
                Block::Table { headers, rows, .. } => {
                    els.push(InteractiveElement { kind: "table".into(), display_text: format!("Table {}x{}", headers.len(), rows.len()), copy_text: format!("Table({}x{})", headers.len(), rows.len()), link_url: None, section_flat_idx: flat_idx, checkbox_index: None, line_hint: els.len() });
                }
                Block::Paragraph { inline, .. } => {
                    for inl in inline {
                        match inl {
                            Inline::Link { text, url, .. } => els.push(InteractiveElement { kind: "link".into(), display_text: text.clone(), copy_text: url.clone(), link_url: Some(url.clone()), section_flat_idx: flat_idx, checkbox_index: None, line_hint: els.len() }),
                            Inline::Image { alt, src, .. } => els.push(InteractiveElement { kind: "image".into(), display_text: alt.clone(), copy_text: src.clone(), link_url: None, section_flat_idx: flat_idx, checkbox_index: None, line_hint: els.len() }),
                            _ => {}
                        }
                    }
                }
                Block::Blockquote { blocks, .. } => walk(blocks, flat_idx, els, checkbox_counter),
                _ => {}
            }
        }
    }
    let mut counter = 0usize;
    walk(&sec.content.blocks, flat_idx, els, &mut counter);
}

// ===================== Main TUI entry =====================
pub fn run_tui(cli: &Cli, loaded: LoadedInput) -> ExitCode {
    // Open /dev/tty check with exact original error messages
    let tty_read = match std::fs::OpenOptions::new().read(true).write(true).open("/dev/tty") {
        Ok(f) => f,
        Err(e) => {
            let estr = e.to_string();
            let full = format!("Cannot open /dev/tty: {}. Interactive mode requires a terminal.", estr);
            eprintln!("Failed to enable raw mode: {}", full);
            eprintln!("Note: When piping input, ensure you have a controlling terminal.");
            eprint!("Error: \n   0: \x1b[91m{}\x1b[0m\n\nLocation:\n   \x1b[35msrc/main.rs\x1b[0m:\x1b[35m275\x1b[0m\n\nBacktrace omitted. Run with RUST_BACKTRACE=1 environment variable to display it.\nRun with RUST_BACKTRACE=full to include source snippets.\n", full);
            return ExitCode::from(1);
        }
    };
    let tty_write = match std::fs::OpenOptions::new().read(true).write(true).open("/dev/tty") {
        Ok(f) => f,
        Err(_) => tty_read.try_clone().unwrap(),
    };
    let mut config = load_config();
    if let Some(t) = &cli.theme { config.theme = t.clone(); }
    let theme = theme_by_name(&config.theme);
    let color_mode_str = match cli.color_mode {
        Some(ColorMode::Rgb) => "rgb",
        Some(ColorMode::Mode256) => "256",
        Some(ColorMode::Auto) => "auto",
        None => config.color_mode.as_str(),
    }.to_string();
    let rgb_mode = match color_mode_str.as_str() {
        "rgb" => true,
        "256" => false,
        _ => {
            let ct = std::env::var("COLORTERM").unwrap_or_default().to_lowercase();
            ct.contains("truecolor") || ct.contains("24bit")
        }
    };
    config.color_mode = if cli.color_mode.is_some() { color_mode_str.clone() } else { config.color_mode.clone() };
    let images_enabled = if cli.no_images { false } else if cli.images { true } else { config.images_enabled };

    let source_name = loaded.source_name.clone().unwrap_or_else(|| "stdin".to_string());
    let mut app = App {
        doc: loaded.document.clone(),
        flat: vec![],
        nodes: vec![],
        selected_node: 0,
        outline_scroll: 0,
        content_scroll: 0,
        focus: Focus::Outline,
        outline_hidden: false,
        outline_width: config.outline_width,
        theme,
        config,
        rgb_mode,
        source_name: source_name.clone(),
        source_path: loaded.source_path.clone(),
        raw_content: loaded.raw_content.clone(),
        is_stdin_source: loaded.is_stdin,
        message: None,
        help_visible: false,
        help_scroll: 0,
        search: None,
        picker: None,
        palette: None,
        links_mode: None,
        interactive: None,
        history_back: vec![],
        history_forward: vec![],
        count_prefix: String::new(),
        todo_filter: false,
        raw_mode: false,
        discard_first_key: true,
        should_quit: false,
        images_enabled,
        dirty: false,
        checkbox_counter: HashMap::new(),
        table_edit: None,
    };
    app.rebuild_nodes();

    // Initial file picker
    let should_picker = loaded.picker_dir.is_some() || loaded.files_is_picker();
    if should_picker {
        app.picker = Some(build_picker(&loaded));
    }

    // terminal setup
    let _ = crossterm::terminal::enable_raw_mode();
    let mut out = tty_write;
    let _ = out.write_all(b"\x1b[?1049h\x1b[?25l");
    let _ = out.flush();

    // input thread
    let (tx, rx) = std::sync::mpsc::channel::<Vec<u8>>();
    {
        let mut reader = tty_read;
        std::thread::spawn(move || {
            let mut buf = [0u8; 4096];
            loop {
                match reader.read(&mut buf) {
                    Ok(0) => break,
                    Ok(n) => { if tx.send(buf[..n].to_vec()).is_err() { break; } }
                    Err(_) => break,
                }
            }
        });
    }

    let mut input_buffer: Vec<u8> = Vec::new();
    let mut last_size = (0u16, 0u16);
    loop {
        // draw
        let size = crossterm::terminal::size().unwrap_or((80, 24));
        if size != last_size { last_size = size; }
        let frame = draw_frame(&mut app, size.0 as usize, size.1 as usize);
        let _ = out.write_all(frame.render_ansi(app.rgb_mode).as_bytes());
        let _ = out.flush();
        if app.should_quit { break; }

        // wait for input with timeout for resize redraw
        match rx.recv_timeout(std::time::Duration::from_millis(50)) {
            Ok(bytes) => {
                input_buffer.extend_from_slice(&bytes);
                let keys = parse_keys(&input_buffer);
                // parse_keys consumes complete sequences; keep remainder
                let consumed = keys.1;
                input_buffer.drain(..consumed);
                for key in keys.0 {
                    if app.discard_first_key {
                        app.discard_first_key = false;
                        continue;
                    }
                    handle_key(&mut app, key);
                    if app.should_quit { break; }
                }
                // Editor handling requested via a message flag encoded in source_name? handled inside handle_key by direct action (needs out) - deferred below
                if app.table_edit.as_ref().map(|_| false).unwrap_or(false) { unreachable!() }
            }
            Err(std::sync::mpsc::RecvTimeoutError::Timeout) => {
                // check editor request
                if app_needs_editor(&app) {
                    // handled via a sentinel message
                }
                continue;
            }
            Err(std::sync::mpsc::RecvTimeoutError::Disconnected) => break,
        }
        if app.should_quit { break; }
        // Editor invocation is signalled by setting message to a sentinel? Instead handle via flag field table_edit abuse:
        // We use a dedicated check: if app.source_name starts with '\0EDITOR' (never in practice)
        // Actual editor handling is performed in handle_key through a pending flag stored in message.
        if app.message.as_deref() == Some("\u{1}EDITOR") {
            app.message = None;
            // teardown
            let _ = out.write_all(b"\x1b[?25h\x1b[?1049l");
            let _ = out.flush();
            let _ = crossterm::terminal::disable_raw_mode();
            run_editor(&mut app);
            let _ = crossterm::terminal::enable_raw_mode();
            let _ = out.write_all(b"\x1b[?1049h\x1b[?25l");
            let _ = out.flush();
        }
    }

    let _ = out.write_all(b"\x1b[?25h\x1b[?1049l");
    let _ = out.flush();
    let _ = crossterm::terminal::disable_raw_mode();
    ExitCode::SUCCESS
}

fn app_needs_editor(_app: &App) -> bool { false }

trait PickerFlag { fn files_is_picker(&self) -> bool; }
impl PickerFlag for LoadedInput {
    fn files_is_picker(&self) -> bool {
        self.picker_dir.is_some() || !self.picker_files.is_empty() || (self.source_path.is_none() && !self.is_stdin)
    }
}

fn build_picker(loaded: &LoadedInput) -> PickerState {
    let mut files: Vec<PathBuf> = Vec::new();
    let mut display: Vec<String> = Vec::new();
    let mut base_dir: Option<PathBuf> = None;
    if !loaded.picker_files.is_empty() {
        for f in &loaded.picker_files {
            if f.is_dir() {
                collect_md_files(f, &mut files);
            } else {
                files.push(f.clone());
            }
        }
        display = files.iter().map(|f| f.file_name().map(|s| s.to_string_lossy().to_string()).unwrap_or_else(|| f.display().to_string())).collect();
    } else {
        let dir = loaded.picker_dir.clone().unwrap_or_else(|| PathBuf::from("."));
        base_dir = Some(dir.clone());
        collect_md_files(&dir, &mut files);
        display = files.iter().map(|f| {
            if let Some(b) = &base_dir {
                f.strip_prefix(b).map(|p| p.display().to_string()).unwrap_or_else(|_| f.display().to_string())
            } else { f.display().to_string() }
        }).collect();
    }
    PickerState {
        title: "Markdown Files in Current Directory".to_string(),
        files, display, selected: 0, scroll: 0, filter: String::new(), filtering: false, base_dir,
    }
}

fn collect_md_files(dir: &Path, out: &mut Vec<PathBuf>) {
    let mut entries: Vec<PathBuf> = Vec::new();
    if let Ok(rd) = std::fs::read_dir(dir) {
        for e in rd.flatten() { entries.push(e.path()); }
    }
    entries.sort();
    for path in entries {
        if path.is_dir() {
            // skip hidden dirs
            if path.file_name().map(|n| n.to_string_lossy().starts_with('.')).unwrap_or(false) { continue; }
            collect_md_files(&path, out);
        } else if let Some(ext) = path.extension().and_then(|s| s.to_str()) {
            let le = ext.to_lowercase();
            if le == "md" || le == "markdown" { out.push(path); }
        }
    }
    out.sort();
}

fn run_editor(app: &mut App) {
    let editor = std::env::var("VISUAL").ok().filter(|s| !s.is_empty())
        .or_else(|| std::env::var("EDITOR").ok().filter(|s| !s.is_empty()));
    let editor = match editor {
        Some(e) => e,
        None => {
            // check supported editors in PATH
            let mut found: Option<String> = None;
            for cand in ["vim", "vi", "nvim", "nano", "emacs", "code", "gedit"] {
                if which_in_path(cand) { found = Some(cand.to_string()); break; }
            }
            match found {
                Some(f) => f,
                None => {
                    app.message = Some("✗ Editor failed: no editor found: set $VISUAL or $EDITOR, or install a supported editor".to_string());
                    return;
                }
            }
        }
    };
    if let Some(path) = &app.source_path {
        let parts: Vec<String> = editor.split_whitespace().map(|s| s.to_string()).collect();
        if !parts.is_empty() {
            let status = std::process::Command::new(&parts[0]).args(&parts[1..]).arg(path).status();
            match status {
                Ok(_) => {
                    if let Ok(content) = std::fs::read_to_string(path) {
                        app.raw_content = content.clone();
                        app.doc = crate::parser::parse_document(&content);
                        app.rebuild_nodes();
                        app.content_scroll = 0;
                    }
                }
                Err(e) => { app.message = Some(format!("✗ Editor failed: {}", e)); }
            }
        }
    } else {
        app.message = Some("✗ Editor failed: no editor found: set $VISUAL or $EDITOR, or install a supported editor".to_string());
    }
}
fn which_in_path(name: &str) -> bool {
    if let Ok(path) = std::env::var("PATH") {
        for dir in path.split(':') {
            if Path::new(dir).join(name).exists() { return true; }
        }
    }
    false
}

// ---------- Key parsing ----------
fn parse_keys(buf: &[u8]) -> (Vec<Key>, usize) {
    let mut keys = Vec::new();
    let mut i = 0usize;
    while i < buf.len() {
        let b = buf[i];
        if b == 0x1b {
            if i + 1 >= buf.len() {
                // lone escape (if this is all we have, treat as Escape; caller may get more bytes later but tmux sends alone)
                keys.push(Key::Escape);
                i += 1;
                continue;
            }
            if buf[i + 1] == b'[' {
                // find final byte
                let mut j = i + 2;
                let mut final_byte: Option<usize> = None;
                while j < buf.len() && j < i + 12 {
                    let c = buf[j];
                    if (0x40..=0x7e).contains(&c) { final_byte = Some(j); break; }
                    j += 1;
                }
                if final_byte.is_none() {
                    // incomplete, stop and keep from i
                    break;
                }
                let j = final_byte.unwrap();
                let seq = &buf[i + 2..j];
                let last = buf[j] as char;
                let key = match last {
                    'A' => Key::Up, 'B' => Key::Down, 'C' => Key::Right, 'D' => Key::Left,
                    'H' => Key::Home, 'F' => Key::End, 'Z' => Key::BackTab,
                    '~' => {
                        let num: String = seq.iter().take_while(|c| c.is_ascii_digit()).map(|c| *c as char).collect();
                        match num.as_str() { "5" => Key::PageUp, "6" => Key::PageDown, "3" => Key::Delete, "1" | "7" => Key::Home, "4" | "8" => Key::End, _ => Key::Unknown }
                    }
                    _ => Key::Unknown,
                };
                if !matches!(key, Key::Unknown) { keys.push(key); }
                i = j + 1;
                continue;
            } else if buf[i + 1] == b'O' && i + 2 < buf.len() {
                let key = match buf[i + 2] as char { 'A' => Key::Up, 'B' => Key::Down, 'C' => Key::Right, 'D' => Key::Left, 'H' => Key::Home, 'F' => Key::End, _ => Key::Unknown };
                if !matches!(key, Key::Unknown) { keys.push(key); }
                i += 3;
                continue;
            } else {
                keys.push(Key::Escape);
                i += 1;
                continue;
            }
        } else if b == b'\r' || b == b'\n' {
            keys.push(Key::Enter);
            i += 1;
            // swallow \r\n pair
            if b == b'\r' && i < buf.len() && buf[i] == b'\n' { i += 1; }
        } else if b == b'\t' {
            keys.push(Key::Tab); i += 1;
        } else if b == 0x7f {
            keys.push(Key::Backspace); i += 1;
        } else if b == 0x15 {
            keys.push(Key::CtrlU); i += 1;
        } else if b == 0x03 {
            keys.push(Key::CtrlC); i += 1;
        } else if b < 0x20 {
            keys.push(Key::Unknown); i += 1;
        } else {
            // utf8 char
            let s = match std::str::from_utf8(&buf[i..]) {
                Ok(s) => s.to_string(),
                Err(e) => {
                    let valid = e.valid_up_to();
                    if valid == 0 {
                        if e.error_len().is_none() { break; } else { i += 1; continue; }
                    }
                    String::from_utf8_lossy(&buf[i..i + valid]).to_string()
                }
            };
            if let Some(ch) = s.chars().next() {
                let len = ch.len_utf8();
                keys.push(Key::Char(ch));
                i += len;
            } else { break; }
        }
    }
    (keys, i)
}

