fn palette_filtered(query: &str) -> Vec<PaletteCommand> {
    if query.trim().is_empty() { return PALETTE_COMMANDS.to_vec(); }
    let q = query.to_lowercase();
    PALETTE_COMMANDS.iter().filter(|c| {
        let hay = format!("{} ({})", c.name, c.aliases).to_lowercase();
        // fuzzy: all query chars in order, or substring
        if hay.contains(&q) { return true; }
        let mut chars = hay.chars();
        q.chars().all(|qc| chars.any(|hc| hc == qc))
    }).cloned().collect()
}
