// ===================== Content generation =====================
fn inline_plain(inlines: &[Inline]) -> String {
    let mut out = String::new();
    for inl in inlines {
        match inl {
            Inline::Image { .. } => {}
            other => out.push_str(&other.value_text()),
        }
    }
    out
}

fn wrap_logical(text: &str, width: usize, hard: bool) -> Vec<String> {
    if width == 0 { return vec![]; }
    if text.is_empty() { return vec![String::new()]; }
    if unicode_width::UnicodeWidthStr::width(text) <= width { return vec![text.to_string()]; }
    if hard {
        let mut lines = Vec::new();
        let mut cur = String::new();
        let mut curw = 0usize;
        for ch in text.chars() {
            let w = UnicodeWidthChar::width(ch).unwrap_or(0);
            if curw + w > width && !cur.is_empty() { lines.push(cur); cur = String::new(); curw = 0; }
            cur.push(ch); curw += w;
        }
        if !cur.is_empty() || lines.is_empty() { lines.push(cur); }
        return lines;
    }
    // word wrap
    let mut lines: Vec<String> = Vec::new();
    let mut cur = String::new();
    for word in text.split(' ') {
        if unicode_width::UnicodeWidthStr::width(word) > width {
            if !cur.is_empty() { lines.push(cur.clone()); cur.clear(); }
            // hard-split long word
            let mut chunk = String::new();
            let mut cw = 0usize;
            for ch in word.chars() {
                let w = UnicodeWidthChar::width(ch).unwrap_or(0);
                if cw + w > width && !chunk.is_empty() { lines.push(chunk); chunk = String::new(); cw = 0; }
                chunk.push(ch); cw += w;
            }
            cur = chunk;
            continue;
        }
        if cur.is_empty() {
            cur = word.to_string();
        } else if unicode_width::UnicodeWidthStr::width(cur.as_str()) + 1 + unicode_width::UnicodeWidthStr::width(word) <= width {
            cur.push(' ');
            cur.push_str(word);
        } else {
            lines.push(cur);
            cur = word.to_string();
        }
    }
    if !cur.is_empty() || lines.is_empty() { lines.push(cur); }
    lines
}

pub struct ContentGen {
    pub lines: Vec<ContentLine>,
    pub elements: Vec<InteractiveElement>,
}

fn render_block_lines(block: &Block, gen: &mut Vec<ContentLine>, elements: &mut Vec<InteractiveElement>, flat_idx: usize, suppress_sep_after: &mut bool) {
    match block {
        Block::Paragraph { inline, content: _ } => {
            let text = inline_plain(inline);
            let mut el_idx: Option<usize> = None;
            for inl in inline {
                match inl {
                    Inline::Link { text, url, .. } => {
                        if el_idx.is_none() { el_idx = Some(elements.len()); }
                        elements.push(InteractiveElement { kind: "link".into(), display_text: text.clone(), copy_text: url.clone(), link_url: Some(url.clone()), section_flat_idx: flat_idx, checkbox_index: None, line_hint: 0 });
                    }
                    Inline::Image { alt, src, .. } => {
                        if el_idx.is_none() { el_idx = Some(elements.len()); }
                        elements.push(InteractiveElement { kind: "image".into(), display_text: alt.clone(), copy_text: src.clone(), link_url: None, section_flat_idx: flat_idx, checkbox_index: None, line_hint: 0 });
                    }
                    _ => {}
                }
            }
            let img_count = inline.iter().filter(|i| matches!(i, Inline::Image { .. })).count();
            for part in text.split('\n') {
                gen.push(ContentLine { text: part.to_string(), kind: LineKind::Normal, element: el_idx });
            }
            if img_count > 0 {
                for _ in 0..13 { gen.push(ContentLine { text: String::new(), kind: LineKind::Blank, element: el_idx }); }
                *suppress_sep_after = true;
            }
        }
        Block::Heading { level, content, .. } => {
            gen.push(ContentLine { text: content.clone(), kind: LineKind::Heading(*level), element: None });
        }
        Block::Code { language, content, .. } => {
            let el = elements.len();
            elements.push(InteractiveElement { kind: "code".into(), display_text: content.clone(), copy_text: content.clone(), link_url: None, section_flat_idx: flat_idx, checkbox_index: None, line_hint: 0 });
            let fence = format!("```{}", language.clone().unwrap_or_default());
            gen.push(ContentLine { text: fence, kind: LineKind::CodeFence, element: Some(el) });
            for line in content.lines() {
                gen.push(ContentLine { text: line.to_string(), kind: LineKind::Code(language.clone().unwrap_or_default()), element: Some(el) });
            }
            if content.is_empty() {
                // no lines
            }
            gen.push(ContentLine { text: "```".to_string(), kind: LineKind::CodeFence, element: Some(el) });
        }
        Block::List { ordered, items } => {
            let mut checkbox_counter = 0usize;
            for (idx, item) in items.iter().enumerate() {
                let mut el_idx: Option<usize> = None;
                if item.checked.is_some() {
                    el_idx = Some(elements.len());
                    elements.push(InteractiveElement { kind: "checkbox".into(), display_text: item.content.clone(), copy_text: item.content.clone(), link_url: None, section_flat_idx: flat_idx, checkbox_index: Some(checkbox_counter), line_hint: 0 });
                }
                if item.checked.is_some() { checkbox_counter += 1; }
                for inl in &item.inline {
                    match inl {
                        Inline::Link { text, url, .. } => {
                            if el_idx.is_none() { el_idx = Some(elements.len()); }
                            elements.push(InteractiveElement { kind: "link".into(), display_text: text.clone(), copy_text: url.clone(), link_url: Some(url.clone()), section_flat_idx: flat_idx, checkbox_index: None, line_hint: 0 });
                        }
                        Inline::Image { alt, src, .. } => {
                            if el_idx.is_none() { el_idx = Some(elements.len()); }
                            elements.push(InteractiveElement { kind: "image".into(), display_text: alt.clone(), copy_text: src.clone(), link_url: None, section_flat_idx: flat_idx, checkbox_index: None, line_hint: 0 });
                        }
                        _ => {}
                    }
                }
                let prefix = if *ordered {
                    format!("  {}. ", idx + 1)
                } else {
                    match item.checked {
                        Some(true) => "  ☑ ".to_string(),
                        Some(false) => "  ☐ ".to_string(),
                        None => "  • ".to_string(),
                    }
                };
                let segments: Vec<&str> = item.content.split('\n').collect();
                for (si, seg) in segments.iter().enumerate() {
                    if si == 0 {
                        gen.push(ContentLine { text: format!("{}{}", prefix, seg), kind: LineKind::List, element: el_idx });
                    } else {
                        gen.push(ContentLine { text: format!("  {}", seg.trim_start()), kind: LineKind::List, element: el_idx });
                    }
                }
                for b in &item.blocks {
                    render_block_lines(b, gen, elements, flat_idx, suppress_sep_after);
                }
            }
        }
        Block::Table { headers, rows, .. } => {
            let el = elements.len();
            elements.push(InteractiveElement { kind: "table".into(), display_text: format!("{}x{}", headers.len(), rows.len()), copy_text: format!("Table({}x{})", headers.len(), rows.len()), link_url: None, section_flat_idx: flat_idx, checkbox_index: None, line_hint: 0 });
            let ncol = headers.len();
            let mut widths: Vec<usize> = headers.iter().map(|h| unicode_width::UnicodeWidthStr::width(h.as_str())).collect();
            for row in rows {
                for (i, cell) in row.iter().enumerate() {
                    if i < ncol { widths[i] = widths[i].max(unicode_width::UnicodeWidthStr::width(cell.as_str())); }
                }
            }
            let border = |left: &str, mid: &str, right: &str, widths: &[usize]| -> String {
                let mut s = left.to_string();
                for (i, w) in widths.iter().enumerate() {
                    if i > 0 { s.push_str(mid); }
                    s.push_str(&"─".repeat(w + 2));
                }
                s.push_str(right);
                s
            };
            gen.push(ContentLine { text: border("┌", "┬", "┐", &widths), kind: LineKind::Table, element: Some(el) });
            let mut header_line = String::new();
            for (i, h) in headers.iter().enumerate() {
                header_line.push_str(&format!("│ {:<width$} ", h, width = widths[i]));
            }
            header_line.push('│');
            gen.push(ContentLine { text: header_line, kind: LineKind::Table, element: Some(el) });
