                gen.push(ContentLine { text: format!("│ {}", part), kind: LineKind::Quote, element: None });
            }
        }
        Block::HorizontalRule => {
            gen.push(ContentLine { text: "─".repeat(60), kind: LineKind::Table, element: None });
        }
    }
