#[derive(Clone)]
struct PaletteCommand { name: &'static str, aliases: &'static str, desc: &'static str, action: &'static str }
const PALETTE_COMMANDS: &[PaletteCommand] = &[
    PaletteCommand { name: "Save changes", aliases: "w, write, save", desc: "Save pending edits to file", action: "save" },
    PaletteCommand { name: "Undo edit", aliases: "u, undo", desc: "Undo last edit", action: "undo" },
    PaletteCommand { name: "Save width to config", aliases: "sw, savewidth", desc: "Save current outline width to config file", action: "savewidth" },
    PaletteCommand { name: "Toggle outline", aliases: "outline, sidebar", desc: "Toggle outline visibility", action: "outline" },
    PaletteCommand { name: "Toggle help", aliases: "help, ?", desc: "Toggle help", action: "help" },
    PaletteCommand { name: "Toggle raw source", aliases: "raw, source", desc: "Switch between rendered and raw markdown", action: "raw" },
    PaletteCommand { name: "Jump to top", aliases: "top, first, gg", desc: "Go to first heading", action: "top" },
    PaletteCommand { name: "Jump to bottom", aliases: "bottom, last, G", desc: "Go to last heading", action: "bottom" },
    PaletteCommand { name: "Collapse all", aliases: "collapse, ca", desc: "Collapse all headings (or :collapse N for level N)", action: "collapse_all" },
    PaletteCommand { name: "Expand all", aliases: "expand, ea", desc: "Expand all headings (or :expand N for level N)", action: "expand_all" },
    PaletteCommand { name: "Collapse level", aliases: "collapse 1, collapse 2, collapse 3, collapse 4, collapse 5", desc: "Collapse headings at specific level", action: "collapse_level" },
    PaletteCommand { name: "Expand level", aliases: "expand 1, expand 2, expand 3, expand 4, expand 5", desc: "Expand headings at specific level", action: "expand_level" },
    PaletteCommand { name: "Quit", aliases: "q, quit, exit", desc: "Quit treemd", action: "quit" },
];

fn palette_filtered(query: &str) -> Vec<PaletteCommand> {
    if query.trim().is_empty() { return PALETTE_COMMANDS.to_vec(); }
    let q = query.to_lowercase();
    PALETTE_COMMANDS.iter().filter(|c| {
        let hay = format!("{} ({})", c.name, c.aliases).to_lowercase();
        // fuzzy: all query chars in order, or substring
        if hay.contains(&q) { return true; }
        let mut chars = hay.chars();
        q.chars().all(|qc| chars.any(|hc| hc == qc))
    }).cloned().collect()
}
