// ===================== Drawing =====================
fn st_fg(theme: &Theme, c: Color) -> Style { Style { fg: Some(c), ..Default::default() } }

fn draw_box(buf: &mut Buffer, x: usize, y: usize, w: usize, h: usize, title: &str, border: Style, bg: Style) {
    if w < 2 || h < 2 { return; }
    buf.fill_rect(x, y, w, h, bg);
    // top
    buf.set_cell(x, y, '┌', border);
    buf.set_cell(x + w - 1, y, '┐', border);
    buf.draw_text(x + 1, y, &format!(" {} ", title), border, w - 2);
    let title_w = unicode_width::UnicodeWidthStr::width(format!(" {} ", title).as_str());
    for xx in x + 1 + title_w..x + w - 1 { buf.set_cell(xx, y, '─', border); }
    for yy in y + 1..y + h - 1 {
        buf.set_cell(x, yy, '│', border);
        buf.set_cell(x + w - 1, yy, '│', border);
    }
    buf.set_cell(x, y + h - 1, '└', border);
    buf.set_cell(x + w - 1, y + h - 1, '┘', border);
    for xx in x + 1..x + w - 1 { buf.set_cell(xx, y + h - 1, '─', border); }
}

fn draw_frame(app: &mut App, w: usize, h: usize) -> Buffer {
    let theme = app.theme.clone();
    let base = Style { fg: Some(theme.text), ..Default::default() };
    let mut buf = Buffer::new(w.max(1), h.max(1), base);
    if w == 0 || h < 4 { return buf; }
    // header
    let header = format!("treemd - {} - {} headings", app.source_name, app.doc.heading_count);
    let mut header_style = st_fg(&theme, theme.accent);
    header_style.bold = true;
    buf.draw_text(0, 0, &header, header_style, w);
    // divider
    for x in 0..w { buf.set_cell(x, 1, '─', st_fg(&theme, theme.text)); }

    // geometry
    let search_h = if app.search.is_some() { 3 } else { 0 };
    let panes_y = 2 + search_h;
    let panes_h = h.saturating_sub(panes_y + 2);
    let status_y = h - 2;
    let footer_y = h - 1;

    // search box
    if let Some(search) = &app.search {
        let title = match search.kind {
            SearchKind::Content => "Content Search (Tab: switch to Outline)",
            SearchKind::Outline => "Outline Search (Tab: switch to Content)",
        };
        let border = st_fg(&theme, theme.accent);
        let bg = Style { fg: Some(theme.text), bg: Some(theme.pane_bg), ..Default::default() };
        draw_box(&mut buf, 0, 2, w, 3, title, border, bg);
        let label = match search.kind { SearchKind::Content => "Find", SearchKind::Outline => "Filter" };
        let mut line = format!("{}: {}", label, search.query);
        if search.editing {
            line.push('_');
            if search.kind == SearchKind::Content && !search.query.is_empty() {
                let (cur, total) = content_match_info(app, w, h);
                if total > 0 { line.push_str(&format!(" [{}/{}]", cur + 1, total)); }
            }
            line.push_str("  (Esc, Ctrl+U)");
        } else {
            if search.kind == SearchKind::Content && !search.query.is_empty() {
                let (cur, total) = content_match_info(app, w, h);
                if total > 0 { line.push_str(&format!(" [{}/{}]", cur + 1, total)); }
            }
            line.push_str("  (Esc, Tab, /: edit)");
        }
        buf.draw_text(1, 3, &line, bg, w - 2);
    }

    // panes
    let outline_w = if app.outline_hidden { 0 } else { (w * app.outline_width) / 100 };
    let content_x = outline_w;
    let content_w = w - content_x;
    let pane_bg = Style { fg: Some(theme.text), bg: Some(theme.pane_bg), ..Default::default() };
    let focused_border = st_fg(&theme, theme.accent);
    let unfocused_border = st_fg(&theme, theme.muted);
    if outline_w >= 4 && panes_h >= 3 {
        let border = if app.focus == Focus::Outline { focused_border } else { unfocused_border };
        let mut bstyle = border; bstyle.bg = Some(theme.pane_bg);
        draw_box(&mut buf, 0, panes_y, outline_w, panes_h, "Outline", bstyle, pane_bg);
        // outline rows
        let inner_h = panes_h - 2;
        let inner_w = outline_w - 2;
        let visible = app.visible_nodes();
        let sel_pos = visible.iter().position(|&i| i == app.selected_node).unwrap_or(0);
        if sel_pos < app.outline_scroll { app.outline_scroll = sel_pos; }
        if inner_h > 0 && sel_pos >= app.outline_scroll + inner_h { app.outline_scroll = sel_pos - inner_h + 1; }
        if app.outline_scroll > visible.len().saturating_sub(inner_h) && visible.len() > inner_h {
            // keep scroll as is if possible (ratatui-like); clamp only if far
            app.outline_scroll = app.outline_scroll.min(visible.len().saturating_sub(1));
        }
        for row in 0..inner_h {
            let vi = app.outline_scroll + row;
            if vi >= visible.len() { break; }
            let node_idx = visible[vi];
            let node = &app.nodes[node_idx];
            let is_sel = node_idx == app.selected_node;
            let mut row_style = pane_bg;
            if is_sel { row_style = Style { fg: Some(theme.text), bg: Some(theme.selected_bg), bold: false, ..Default::default() }; }
            buf.fill_rect(1, panes_y + 1 + row, inner_w, 1, row_style);
            // build prefix + heading
            let cursor = if is_sel { "►" } else { " " };
            let indent = "  ".repeat(node.depth);
            let expand = if node.has_children { if node.expanded { "▼ " } else { "▶ " } } else { "  " };
            let bookmark = if node.bookmark { "⚑ " } else { "" };
            let prefix = format!("{} {}{}{}", cursor, indent, expand, bookmark);
            buf.draw_text(1, panes_y + 1 + row, &prefix, row_style, inner_w);
            let prefix_w = unicode_width::UnicodeWidthStr::width(prefix.as_str());
            let heading_text = format!("{} {}", "#".repeat(node.section.level as usize), node.section.title);
            let mut hstyle = row_style;
            hstyle.fg = Some(theme.headings[(node.section.level as usize).clamp(1, 6) - 1]);
            if is_sel { hstyle.bold = true; hstyle.fg = Some(col(15, (255, 255, 255))); }
            if prefix_w < inner_w {
                buf.draw_text(1 + prefix_w, panes_y + 1 + row, &heading_text, hstyle, inner_w - prefix_w);
            }
        }
        // outline scrollbar
        let syms = scrollbar_symbols(visible.len(), sel_pos, inner_h);
        let sb_style = Style { fg: Some(theme.faint), bg: Some(theme.pane_bg), ..Default::default() };
        for (i, sym) in syms.iter().enumerate() {
            if i < inner_h { buf.set_cell(outline_w - 1, panes_y + 1 + i, *sym, sb_style); }
        }
    }

    // content pane
    if content_w >= 4 && panes_h >= 3 {
        let border = if app.focus == Focus::Content { focused_border } else { unfocused_border };
        let mut bstyle = border; bstyle.bg = Some(theme.pane_bg);
        let sel_sec_title = if app.flat.is_empty() { String::new() } else { app.flat[app.selected_flat_idx()].title.clone() };
        let content_title = if app.raw_mode {
            format!("[RAW] {}", sel_sec_title)
        } else if let Some(ls) = &app.links_mode {
            format!("{} [Links: {}]", sel_sec_title, ls.links.len())
        } else { sel_sec_title };
        draw_box(&mut buf, content_x, panes_y, content_w, panes_h, &content_title, bstyle, pane_bg);
        let inner_h = panes_h - 2;
        let inner_w = content_w - 2;
        let gen = generate_content(app, inner_w);
        let total_lines = gen.lines.len();
        let max_scroll = total_lines.saturating_sub(inner_h);
        if app.content_scroll > max_scroll { app.content_scroll = max_scroll; }
        // interactive highlight element
        let active_element: Option<usize> = app.interactive.as_ref().map(|s| s.selected);
        let active_link: Option<usize> = app.links_mode.as_ref().map(|s| s.selected);
        for row in 0..inner_h {
            let li = app.content_scroll + row;
            if li >= total_lines { break; }
            let line = &gen.lines[li];
            let y = panes_y + 1 + row;
            // raw mode numbering
            if app.raw_mode {
                let num = format!("{:>4} │ ", li + 1);
                let mut ns = pane_bg; ns.fg = Some(theme.faint);
