                LineKind::CodeFence => { style.fg = Some(theme.code); }
                LineKind::Code(_) => { style.fg = Some(theme.text); }
                LineKind::Quote => { style.fg = Some(theme.muted); style.italic = true; }
                LineKind::Table => { style.fg = Some(theme.faint); }
