                }
            }
            if let Some(_sel_link) = active_link {
                // highlight lines containing selected link text
                if let Some(ls) = &app.links_mode {
                    if let Some((txt, _)) = ls.links.get(ls.selected) {
                        if !txt.is_empty() && line.text.contains(txt) { style.bg = Some(theme.selected_bg); }
                    }
                }
            }
            buf.draw_text(content_x + 1, y, &line.text, style, inner_w);
            // search highlighting (content)
            if let Some(search) = &app.search {
                if search.kind == SearchKind::Content && !search.query.is_empty() {
                    let q = search.query.to_lowercase();
                    let hay = line.text.to_lowercase();
                    let mut start = 0usize;
                    while let Some(pos) = hay[start..].find(&q) {
                        let byte_start = start + pos;
                        let char_start = hay[..byte_start].chars().count();
                        let char_len = search.query.chars().count();
                        // map char index to x: approximate with width of prefix text
                        let prefix_text: String = line.text.chars().take(char_start).collect();
                        let px = unicode_width::UnicodeWidthStr::width(prefix_text.as_str());
                        let mtext: String = line.text.chars().skip(char_start).take(char_len).collect();
                        let mw = unicode_width::UnicodeWidthStr::width(mtext.as_str());
                        let mut hl = style; hl.bg = Some(col(220, (240, 200, 80))); hl.fg = Some(col(16, (0, 0, 0)));
                        for dx in 0..mw {
                            if content_x + 1 + px + dx < content_x + content_w - 1 {
                                let idx = buf.idx(content_x + 1 + px + dx, y);
                                buf.cells[idx].style.bg = hl.bg;
                                buf.cells[idx].style.fg = hl.fg;
                            }
                        }
                        start = byte_start + q.len().max(1);
                        if start >= hay.len() { break; }
                    }
                }
            }
        }
        let syms = scrollbar_symbols(total_lines, app.content_scroll, inner_h);
        let sb_style = Style { fg: Some(theme.faint), bg: Some(theme.pane_bg), ..Default::default() };
        for (i, sym) in syms.iter().enumerate() {
            if i < inner_h { buf.set_cell(content_x + content_w - 1, panes_y + 1 + i, *sym, sb_style); }
        }
