}

fn content_pane_inner_width(app: &App, w: usize) -> usize {
    let outline_w = if app.outline_hidden { 0 } else { (w * app.outline_width) / 100 };
    let cw = w - outline_w;
    cw.saturating_sub(2)
}
fn content_total(app: &App, w: usize, h: usize) -> (usize, usize) {
    let _ = h;
    let gen = generate_content(app, content_pane_inner_width(app, w));
    (gen.lines.len(), gen.elements.len())
}
fn content_match_info(app: &App, w: usize, _h: usize) -> (usize, usize) {
    if let Some(search) = &app.search {
        if search.query.is_empty() { return (0, 0); }
        let gen = generate_content(app, content_pane_inner_width(app, w));
        let q = search.query.to_lowercase();
        let mut total = 0usize;
        for line in &gen.lines {
            let hay = line.text.to_lowercase();
            let mut start = 0usize;
            while let Some(pos) = hay[start..].find(&q) { total += 1; start = start + pos + q.len().max(1); if start >= hay.len() { break; } }
        }
        (search.current_match, total)
    } else { (0, 0) }
}

fn compute_status(app: &App, w: usize, h: usize) -> String {
    if let Some(msg) = &app.message {
        return msg.clone();
    }
    let theme = &app.theme;
    if let Some(ls) = &app.links_mode {
        if let Some((txt, url)) = ls.links.get(ls.selected) {
            return format!(" [LINKS] Link {}/{}: \"{}\" → {}  • Theme:{}", ls.selected + 1, ls.links.len(), txt, url, theme.display);
        }
    }
    match app.focus {
        Focus::Outline => {
            let visible = app.visible_nodes();
            let pos = visible.iter().position(|&i| i == app.selected_node).map(|p| p + 1).unwrap_or(1);
            let total = visible.len().max(1);
            let pct = if visible.is_empty() { 100 } else { pos * 100 / total };
            let bookmark = if app.nodes.get(app.selected_node).map(|n| n.bookmark).unwrap_or(false) { " ⚑" } else { "" };
            let hist = if !app.history_back.is_empty() { format!(" ← {} ", app.history_back.len()) } else { String::new() };
            let hist_sep = if app.history_back.is_empty() { String::new() } else { " ".to_string() };
            format!(" [Outline] {}/{} ({}%){}{}{} • Outline:{}% • Theme:{}", pos, total, pct, bookmark, hist, hist_sep, app.outline_width, theme.display)
        }
        Focus::Content => {
            let (total_lines, _) = content_total(app, w, h);
            let line_no = app.content_scroll + 1;
            let pct = if total_lines == 0 { 100 } else { line_no * 100 / total_lines };
            let outline_part = if app.outline_hidden { "Outline:Hidden".to_string() } else { format!("Outline:{}%", app.outline_width) };
            format!(" [Content] Line {} ({}%) • {} • Theme:{}", line_no, pct, outline_part, theme.display)
        }
    }
}

fn compute_footer(app: &App) -> String {
    if app.palette.is_some() {
        return " j/k Navigate  Enter Select  Esc Cancel".to_string();
    }
    if app.links_mode.is_some() {
        return " Tab Next Link  1-9 Jump  Enter Follow  y Copy URL  Esc Exit".to_string();
    }
    if app.interactive.is_some() {
        return " j/k Navigate  y Copy  Esc Exit".to_string();
    }
    if let Some(search) = &app.search {
        if search.kind == SearchKind::Content {
            return " n/N Next/Prev  Tab Outline Search  Enter Accept  Esc Cancel".to_string();
        }
    }
    match app.focus {
        Focus::Outline => " j/k Navigate  Enter Select  / Search  i Interactive  f Links  ? Help".to_string(),
        Focus::Content => " j/k Scroll  / Search  i Interactive  f Links  y Copy  ? Help".to_string(),
    }
}

fn draw_help(app: &App, buf: &mut Buffer, w: usize, h: usize) {
    let theme = &app.theme;
    let bw = (w * 70) / 100;
    let bh = (h * 80) / 100;
    let x = (w - bw) / 2;
    let y = (h - bh) / 2;
    let border = Style { fg: Some(theme.accent), bg: Some(theme.pane_bg), ..Default::default() };
    let bg = Style { fg: Some(theme.text), bg: Some(theme.pane_bg), ..Default::default() };
    draw_box(buf, x, y, bw, bh, "Help", border, bg);
    let inner_h = bh - 2;
    let inner_w = bw - 2;
    let max_scroll = HELP_LINES.len().saturating_sub(inner_h);
    let scroll = app.help_scroll.min(max_scroll);
    for row in 0..inner_h {
        let li = scroll + row;
        if li >= HELP_LINES.len() { break; }
        let mut style = bg;
        let line = HELP_LINES[li];
        // headings style
        if !line.starts_with(' ') && !line.is_empty() && !line.starts_with("treemd") && !line.starts_with("Use") && !line.starts_with("Note") {
            style.bold = true; style.fg = Some(theme.accent);
        }
        buf.draw_text(x + 1, y + 1 + row, line, style, inner_w);
    }
    let syms = scrollbar_symbols(HELP_LINES.len(), scroll, inner_h);
    let sb_style = Style { fg: Some(theme.faint), bg: Some(theme.pane_bg), ..Default::default() };
    for (i, sym) in syms.iter().enumerate() {
        if i < inner_h { buf.set_cell(x + bw - 1, y + 1 + i, *sym, sb_style); }
    }
}

fn draw_picker(app: &App, buf: &mut Buffer, w: usize, h: usize) {
    let theme = &app.theme;
    let picker = match &app.picker { Some(p) => p, None => return };
    let bw = (w * 80) / 100;
    let bh = (h * 60) / 100;
    let x = (w - bw) / 2;
    let y = (h - bh) / 2;
    let border = Style { fg: Some(theme.accent), bg: Some(theme.pane_bg), ..Default::default() };
    let bg = Style { fg: Some(theme.text), bg: Some(theme.pane_bg), ..Default::default() };
    draw_box(buf, x, y, bw, bh, "File Picker", border, bg);
    let inner_w = bw - 2;
    let inner_h = bh - 2;
    let filtered = picker_filtered(picker);
    let header = if picker.filtering || !picker.filter.is_empty() {
        format!("Filter: {} ({} files)", picker.filter, filtered.len())
    } else {
        format!("{} ({} found) - /: search, j/k: navigate, Enter: open", picker.title, picker.files.len())
    };
    let mut row = 0usize;
    if row < inner_h { buf.draw_text(x + 1, y + 1 + row, &header, bg, inner_w); row += 1; }
    if row < inner_h { row += 1; } // blank
    let footer_row_needed = 2usize;
    let list_capacity = inner_h.saturating_sub(row + footer_row_needed);
    let sel = picker.selected;
    let mut scroll = picker.scroll;
    if sel < scroll { scroll = sel; }
    if list_capacity > 0 && sel >= scroll + list_capacity { scroll = sel - list_capacity + 1; }
    for i in 0..list_capacity {
        let fi = scroll + i;
        if fi >= filtered.len() { break; }
        let (orig_idx, disp) = filtered[fi];
        let marker = if fi == sel { "▶" } else { " " };
        let line = format!("{} [{}] {}", marker, orig_idx + 1, disp);
        let mut style = bg;
        if fi == sel { style.bold = true; }
        buf.draw_text(x + 1, y + 1 + row, &line, style, inner_w);
        row += 1;
    }
    row += 1; // blank before footer
    if row < inner_h {
        buf.draw_text(x + 1, y + 1 + row, "j/k: Navigate • /: Filter • 1-9: Jump • Enter: Open • Esc: Cancel", bg, inner_w);
    }
}

fn picker_filtered(picker: &PickerState) -> Vec<(usize, String)> {
    let q = picker.filter.to_lowercase();
    picker.display.iter().enumerate().filter(|(_, d)| q.is_empty() || d.to_lowercase().contains(&q)).map(|(i, d)| (i, d.clone())).collect()
}

fn draw_palette(app: &App, buf: &mut Buffer, w: usize, h: usize) {
    let theme = &app.theme;
    let palette = match &app.palette { Some(p) => p, None => return };
    let bw = (w * 60) / 100;
    let bh = (h * 50) / 100;
    let x = (w - bw) / 2;
    let y = (h - bh) / 2;
    let border = Style { fg: Some(theme.accent), bg: Some(theme.pane_bg), ..Default::default() };
    let bg = Style { fg: Some(theme.text), bg: Some(theme.pane_bg), ..Default::default() };
    draw_box(buf, x, y, bw, bh, "Command Palette", border, bg);
    let inner_w = bw - 2;
    let inner_h = bh - 2;
    let mut lines: Vec<(String, bool)> = Vec::new();
    lines.push((String::new(), false));
    lines.push((format!(": {}█", palette.query), false));
    lines.push((String::new(), false));
    let filtered = palette_filtered(&palette.query);
    if filtered.is_empty() {
        lines.push(("  No matching commands".to_string(), false));
        lines.push((String::new(), false));
        lines.push(("↑↓/Tab navigate  Enter execute  Esc cancel".to_string(), false));
    } else {
        for (i, cmd) in filtered.iter().enumerate() {
            let marker = if i == palette.selected { "▸" } else { " " };
            lines.push((format!("{} {} ({})", marker, cmd.name, cmd.aliases), i == palette.selected));
            if i == palette.selected {
                lines.push((format!("    {}", cmd.desc), false));
            }
        }
        lines.push((String::new(), false));
        lines.push(("↑↓/Tab navigate  Enter execute  Esc cancel".to_string(), false));
    }
    // scroll to keep selected visible: estimate line of selected cmd
    let mut scroll = palette.scroll;
    // compute selected line index
    let mut sel_line: Option<usize> = None;
    {
        let mut idx = 3usize;
        if filtered.is_empty() { sel_line = None; }
        for (i, _) in filtered.iter().enumerate() {
            if i == palette.selected { sel_line = Some(idx); break; }
            idx += if i == palette.selected { 2 } else { 1 };
            if i < palette.selected { /* desc counted above when that was selected only */ }
        }
        // simpler: selected line = 3 + selected (plus 0 because only selected has desc after it)
        if sel_line.is_none() && !filtered.is_empty() { sel_line = Some(3 + palette.selected); }
    }
    if let Some(sl) = sel_line {
        if sl < scroll { scroll = sl; }
        if inner_h > 0 && sl >= scroll + inner_h { scroll = sl - inner_h + 1; }
    }
    for row in 0..inner_h {
        let li = scroll + row;
        if li >= lines.len() { break; }
        let (text, is_sel) = &lines[li];
        let mut style = bg;
        if *is_sel { style.bold = true; }
        buf.draw_text(x + 1, y + 1 + row, text, style, inner_w);
    }
}
RS
