// ===================== Drawing =====================
fn st_fg(theme: &Theme, c: Color) -> Style { Style { fg: Some(c), ..Default::default() } }

fn draw_box(buf: &mut Buffer, x: usize, y: usize, w: usize, h: usize, title: &str, border: Style, bg: Style) {
    if w < 2 || h < 2 { return; }
    buf.fill_rect(x, y, w, h, bg);
    // top
    buf.set_cell(x, y, '┌', border);
    buf.set_cell(x + w - 1, y, '┐', border);
    buf.draw_text(x + 1, y, &format!(" {} ", title), border, w - 2);
    let title_w = unicode_width::UnicodeWidthStr::width(format!(" {} ", title).as_str());
    for xx in x + 1 + title_w..x + w - 1 { buf.set_cell(xx, y, '─', border); }
    for yy in y + 1..y + h - 1 {
        buf.set_cell(x, yy, '│', border);
        buf.set_cell(x + w - 1, yy, '│', border);
    }
    buf.set_cell(x, y + h - 1, '└', border);
    buf.set_cell(x + w - 1, y + h - 1, '┘', border);
    for xx in x + 1..x + w - 1 { buf.set_cell(xx, y + h - 1, '─', border); }
}

fn draw_frame(app: &mut App, w: usize, h: usize) -> Buffer {
    let theme = app.theme.clone();
    let base = Style { fg: Some(theme.text), ..Default::default() };
    let mut buf = Buffer::new(w.max(1), h.max(1), base);
    if w == 0 || h < 4 { return buf; }
    // header
    let header = format!("treemd - {} - {} headings", app.source_name, app.doc.heading_count);
    let mut header_style = st_fg(&theme, theme.accent);
    header_style.bold = true;
    buf.draw_text(0, 0, &header, header_style, w);
    // divider
    for x in 0..w { buf.set_cell(x, 1, '─', st_fg(&theme, theme.text)); }

    // geometry
    let search_h = if app.search.is_some() { 3 } else { 0 };
    let panes_y = 2 + search_h;
    let panes_h = h.saturating_sub(panes_y + 2);
    let status_y = h - 2;
    let footer_y = h - 1;

    // search box
    if let Some(search) = &app.search {
        let title = match search.kind {
            SearchKind::Content => "Content Search (Tab: switch to Outline)",
            SearchKind::Outline => "Outline Search (Tab: switch to Content)",
        };
        let border = st_fg(&theme, theme.accent);
        let bg = Style { fg: Some(theme.text), bg: Some(theme.pane_bg), ..Default::default() };
        draw_box(&mut buf, 0, 2, w, 3, title, border, bg);
        let label = match search.kind { SearchKind::Content => "Find", SearchKind::Outline => "Filter" };
        let mut line = format!("{}: {}", label, search.query);
        if search.editing {
            line.push('_');
            if search.kind == SearchKind::Content && !search.query.is_empty() {
                let (cur, total) = content_match_info(app, w, h);
                if total > 0 { line.push_str(&format!(" [{}/{}]", cur + 1, total)); }
            }
            line.push_str("  (Esc, Ctrl+U)");
        } else {
            if search.kind == SearchKind::Content && !search.query.is_empty() {
                let (cur, total) = content_match_info(app, w, h);
                if total > 0 { line.push_str(&format!(" [{}/{}]", cur + 1, total)); }
            }
            line.push_str("  (Esc, Tab, /: edit)");
        }
        buf.draw_text(1, 3, &line, bg, w - 2);
    }

    // panes
    let outline_w = if app.outline_hidden { 0 } else { (w * app.outline_width) / 100 };
    let content_x = outline_w;
    let content_w = w - content_x;
    let pane_bg = Style { fg: Some(theme.text), bg: Some(theme.pane_bg), ..Default::default() };
    let focused_border = st_fg(&theme, theme.accent);
    let unfocused_border = st_fg(&theme, theme.muted);
    if outline_w >= 4 && panes_h >= 3 {
        let border = if app.focus == Focus::Outline { focused_border } else { unfocused_border };
        let mut bstyle = border; bstyle.bg = Some(theme.pane_bg);
        draw_box(&mut buf, 0, panes_y, outline_w, panes_h, "Outline", bstyle, pane_bg);
        // outline rows
        let inner_h = panes_h - 2;
        let inner_w = outline_w - 2;
        let visible = app.visible_nodes();
        let sel_pos = visible.iter().position(|&i| i == app.selected_node).unwrap_or(0);
        if sel_pos < app.outline_scroll { app.outline_scroll = sel_pos; }
        if inner_h > 0 && sel_pos >= app.outline_scroll + inner_h { app.outline_scroll = sel_pos - inner_h + 1; }
        if app.outline_scroll > visible.len().saturating_sub(inner_h) && visible.len() > inner_h {
            // keep scroll as is if possible (ratatui-like); clamp only if far
            app.outline_scroll = app.outline_scroll.min(visible.len().saturating_sub(1));
        }
        for row in 0..inner_h {
            let vi = app.outline_scroll + row;
            if vi >= visible.len() { break; }
            let node_idx = visible[vi];
            let node = &app.nodes[node_idx];
            let is_sel = node_idx == app.selected_node;
            let mut row_style = pane_bg;
            if is_sel { row_style = Style { fg: Some(theme.text), bg: Some(theme.selected_bg), bold: false, ..Default::default() }; }
            buf.fill_rect(1, panes_y + 1 + row, inner_w, 1, row_style);
            // build prefix + heading
            let cursor = if is_sel { "►" } else { " " };
            let indent = "  ".repeat(node.depth);
            let expand = if node.has_children { if node.expanded { "▼ " } else { "▶ " } } else { "  " };
            let bookmark = if node.bookmark { "⚑ " } else { "" };
            let prefix = format!("{} {}{}{}", cursor, indent, expand, bookmark);
            buf.draw_text(1, panes_y + 1 + row, &prefix, row_style, inner_w);
            let prefix_w = unicode_width::UnicodeWidthStr::width(prefix.as_str());
            let heading_text = format!("{} {}", "#".repeat(node.section.level as usize), node.section.title);
            let mut hstyle = row_style;
            hstyle.fg = Some(theme.headings[(node.section.level as usize).clamp(1, 6) - 1]);
            if is_sel { hstyle.bold = true; hstyle.fg = Some(col(15, (255, 255, 255))); }
            if prefix_w < inner_w {
                buf.draw_text(1 + prefix_w, panes_y + 1 + row, &heading_text, hstyle, inner_w - prefix_w);
            }
        }
        // outline scrollbar
        let syms = scrollbar_symbols(visible.len(), sel_pos, inner_h);
        let sb_style = Style { fg: Some(theme.faint), bg: Some(theme.pane_bg), ..Default::default() };
        for (i, sym) in syms.iter().enumerate() {
            if i < inner_h { buf.set_cell(outline_w - 1, panes_y + 1 + i, *sym, sb_style); }
        }
    }

    // content pane
    if content_w >= 4 && panes_h >= 3 {
        let border = if app.focus == Focus::Content { focused_border } else { unfocused_border };
        let mut bstyle = border; bstyle.bg = Some(theme.pane_bg);
        let sel_sec_title = if app.flat.is_empty() { String::new() } else { app.flat[app.selected_flat_idx()].title.clone() };
        let content_title = if app.raw_mode {
            format!("[RAW] {}", sel_sec_title)
        } else if let Some(ls) = &app.links_mode {
            format!("{} [Links: {}]", sel_sec_title, ls.links.len())
        } else { sel_sec_title };
        draw_box(&mut buf, content_x, panes_y, content_w, panes_h, &content_title, bstyle, pane_bg);
        let inner_h = panes_h - 2;
        let inner_w = content_w - 2;
        let gen = generate_content(app, inner_w);
        let total_lines = gen.lines.len();
        let max_scroll = total_lines.saturating_sub(inner_h);
        if app.content_scroll > max_scroll { app.content_scroll = max_scroll; }
        // interactive highlight element
        let active_element: Option<usize> = app.interactive.as_ref().map(|s| s.selected);
        let active_link: Option<usize> = app.links_mode.as_ref().map(|s| s.selected);
        for row in 0..inner_h {
            let li = app.content_scroll + row;
            if li >= total_lines { break; }
            let line = &gen.lines[li];
            let y = panes_y + 1 + row;
            // raw mode numbering
            if app.raw_mode {
                let num = format!("{:>4} │ ", li + 1);
                let mut ns = pane_bg; ns.fg = Some(theme.faint);
                buf.draw_text(content_x + 1, y, &num, ns, inner_w);
                let numw = unicode_width::UnicodeWidthStr::width(num.as_str());
                buf.draw_text(content_x + 1 + numw, y, &line.text, pane_bg, inner_w.saturating_sub(numw));
                continue;
            }
            let mut style = pane_bg;
            match &line.kind {
                LineKind::Heading(lvl) => { style.fg = Some(theme.headings[(*lvl as usize).clamp(1, 6) - 1]); style.bold = true; style.underline = true; }
                LineKind::CodeFence => { style.fg = Some(theme.code); }
                LineKind::Code(_) => { style.fg = Some(theme.text); }
                LineKind::Quote => { style.fg = Some(theme.muted); style.italic = true; }
                LineKind::Table => { style.fg = Some(theme.faint); }
                _ => {}
            }
            if let Some(sel_el) = active_element {
                if line.element == Some(sel_el) {
                    style.bg = Some(theme.selected_bg);
                }
            }
            if let Some(_sel_link) = active_link {
                // highlight lines containing selected link text
                if let Some(ls) = &app.links_mode {
                    if let Some((txt, _)) = ls.links.get(ls.selected) {
                        if !txt.is_empty() && line.text.contains(txt) { style.bg = Some(theme.selected_bg); }
                    }
                }
            }
            buf.draw_text(content_x + 1, y, &line.text, style, inner_w);
            // search highlighting (content)
            if let Some(search) = &app.search {
                if search.kind == SearchKind::Content && !search.query.is_empty() {
                    let q = search.query.to_lowercase();
                    let hay = line.text.to_lowercase();
                    let mut start = 0usize;
                    while let Some(pos) = hay[start..].find(&q) {
                        let byte_start = start + pos;
                        let char_start = hay[..byte_start].chars().count();
                        let char_len = search.query.chars().count();
                        // map char index to x: approximate with width of prefix text
                        let prefix_text: String = line.text.chars().take(char_start).collect();
                        let px = unicode_width::UnicodeWidthStr::width(prefix_text.as_str());
                        let mtext: String = line.text.chars().skip(char_start).take(char_len).collect();
                        let mw = unicode_width::UnicodeWidthStr::width(mtext.as_str());
                        let mut hl = style; hl.bg = Some(col(220, (240, 200, 80))); hl.fg = Some(col(16, (0, 0, 0)));
                        for dx in 0..mw {
                            if content_x + 1 + px + dx < content_x + content_w - 1 {
                                let idx = buf.idx(content_x + 1 + px + dx, y);
                                buf.cells[idx].style.bg = hl.bg;
                                buf.cells[idx].style.fg = hl.fg;
                            }
                        }
                        start = byte_start + q.len().max(1);
                        if start >= hay.len() { break; }
                    }
                }
            }
        }
        let syms = scrollbar_symbols(total_lines, app.content_scroll, inner_h);
        let sb_style = Style { fg: Some(theme.faint), bg: Some(theme.pane_bg), ..Default::default() };
        for (i, sym) in syms.iter().enumerate() {
            if i < inner_h { buf.set_cell(content_x + content_w - 1, panes_y + 1 + i, *sym, sb_style); }
        }
        let _ = total_lines;
    }

    // status line
    let status_style = Style { fg: Some(theme.text), bg: Some(theme.status_bg), ..Default::default() };
    buf.fill_rect(0, status_y, w, 1, status_style);
    let status_text = compute_status(app, w, h);
    buf.draw_text(0, status_y, &status_text, status_style, w);

    // footer
    let footer_style = Style { fg: Some(theme.text), bg: Some(theme.pane_bg), ..Default::default() };
    buf.fill_rect(0, footer_y, w, 1, footer_style);
    let footer = compute_footer(app);
    // footer segments: draw plainly (colors simplified)
    buf.draw_text(0, footer_y, &footer, footer_style, w);

    // overlays
    if app.help_visible { draw_help(app, &mut buf, w, h); }
    if app.picker.is_some() { draw_picker(app, &mut buf, w, h); }
    if app.palette.is_some() { draw_palette(app, &mut buf, w, h); }

    buf
}

fn content_pane_inner_width(app: &App, w: usize) -> usize {
    let outline_w = if app.outline_hidden { 0 } else { (w * app.outline_width) / 100 };
    let cw = w - outline_w;
    cw.saturating_sub(2)
}
fn content_total(app: &App, w: usize, h: usize) -> (usize, usize) {
    let _ = h;
    let gen = generate_content(app, content_pane_inner_width(app, w));
    (gen.lines.len(), gen.elements.len())
}
fn content_match_info(app: &App, w: usize, _h: usize) -> (usize, usize) {
    if let Some(search) = &app.search {
        if search.query.is_empty() { return (0, 0); }
        let gen = generate_content(app, content_pane_inner_width(app, w));
        let q = search.query.to_lowercase();
        let mut total = 0usize;
        for line in &gen.lines {
            let hay = line.text.to_lowercase();
            let mut start = 0usize;
            while let Some(pos) = hay[start..].find(&q) { total += 1; start = start + pos + q.len().max(1); if start >= hay.len() { break; } }
        }
        (search.current_match, total)
    } else { (0, 0) }
}

fn compute_status(app: &App, w: usize, h: usize) -> String {
    if let Some(msg) = &app.message {
        return msg.clone();
    }
    let theme = &app.theme;
    if let Some(ls) = &app.links_mode {
        if let Some((txt, url)) = ls.links.get(ls.selected) {
            return format!(" [LINKS] Link {}/{}: \"{}\" → {}  • Theme:{}", ls.selected + 1, ls.links.len(), txt, url, theme.display);
        }
    }
    match app.focus {
        Focus::Outline => {
            let visible = app.visible_nodes();
            let pos = visible.iter().position(|&i| i == app.selected_node).map(|p| p + 1).unwrap_or(1);
            let total = visible.len().max(1);
            let pct = if visible.is_empty() { 100 } else { pos * 100 / total };
            let bookmark = if app.nodes.get(app.selected_node).map(|n| n.bookmark).unwrap_or(false) { " ⚑" } else { "" };
            let hist = if !app.history_back.is_empty() { format!(" ← {} ", app.history_back.len()) } else { String::new() };
            let hist_sep = if app.history_back.is_empty() { String::new() } else { " ".to_string() };
            format!(" [Outline] {}/{} ({}%){}{}{} • Outline:{}% • Theme:{}", pos, total, pct, bookmark, hist, hist_sep, app.outline_width, theme.display)
        }
        Focus::Content => {
            let (total_lines, _) = content_total(app, w, h);
            let line_no = app.content_scroll + 1;
            let pct = if total_lines == 0 { 100 } else { line_no * 100 / total_lines };
            let outline_part = if app.outline_hidden { "Outline:Hidden".to_string() } else { format!("Outline:{}%", app.outline_width) };
            format!(" [Content] Line {} ({}%) • {} • Theme:{}", line_no, pct, outline_part, theme.display)
        }
    }
}

fn compute_footer(app: &App) -> String {
    if app.palette.is_some() {
        return " j/k Navigate  Enter Select  Esc Cancel".to_string();
    }
    if app.links_mode.is_some() {
        return " Tab Next Link  1-9 Jump  Enter Follow  y Copy URL  Esc Exit".to_string();
    }
    if app.interactive.is_some() {
        return " j/k Navigate  y Copy  Esc Exit".to_string();
    }
    if let Some(search) = &app.search {
        if search.kind == SearchKind::Content {
            return " n/N Next/Prev  Tab Outline Search  Enter Accept  Esc Cancel".to_string();
        }
    }
    match app.focus {
        Focus::Outline => " j/k Navigate  Enter Select  / Search  i Interactive  f Links  ? Help".to_string(),
        Focus::Content => " j/k Scroll  / Search  i Interactive  f Links  y Copy  ? Help".to_string(),
    }
}

fn draw_help(app: &App, buf: &mut Buffer, w: usize, h: usize) {
    let theme = &app.theme;
    let bw = (w * 70) / 100;
    let bh = (h * 80) / 100;
    let x = (w - bw) / 2;
    let y = (h - bh) / 2;
    let border = Style { fg: Some(theme.accent), bg: Some(theme.pane_bg), ..Default::default() };
    let bg = Style { fg: Some(theme.text), bg: Some(theme.pane_bg), ..Default::default() };
    draw_box(buf, x, y, bw, bh, "Help", border, bg);
    let inner_h = bh - 2;
    let inner_w = bw - 2;
    let max_scroll = HELP_LINES.len().saturating_sub(inner_h);
    let scroll = app.help_scroll.min(max_scroll);
    for row in 0..inner_h {
        let li = scroll + row;
        if li >= HELP_LINES.len() { break; }
        let mut style = bg;
        let line = HELP_LINES[li];
        // headings style
        if !line.starts_with(' ') && !line.is_empty() && !line.starts_with("treemd") && !line.starts_with("Use") && !line.starts_with("Note") {
            style.bold = true; style.fg = Some(theme.accent);
        }
        buf.draw_text(x + 1, y + 1 + row, line, style, inner_w);
    }
    let syms = scrollbar_symbols(HELP_LINES.len(), scroll, inner_h);
    let sb_style = Style { fg: Some(theme.faint), bg: Some(theme.pane_bg), ..Default::default() };
    for (i, sym) in syms.iter().enumerate() {
        if i < inner_h { buf.set_cell(x + bw - 1, y + 1 + i, *sym, sb_style); }
    }
}

fn draw_picker(app: &App, buf: &mut Buffer, w: usize, h: usize) {
    let theme = &app.theme;
    let picker = match &app.picker { Some(p) => p, None => return };
    let bw = (w * 80) / 100;
    let bh = (h * 60) / 100;
    let x = (w - bw) / 2;
    let y = (h - bh) / 2;
    let border = Style { fg: Some(theme.accent), bg: Some(theme.pane_bg), ..Default::default() };
    let bg = Style { fg: Some(theme.text), bg: Some(theme.pane_bg), ..Default::default() };
    draw_box(buf, x, y, bw, bh, "File Picker", border, bg);
    let inner_w = bw - 2;
    let inner_h = bh - 2;
    let filtered = picker_filtered(picker);
    let header = if picker.filtering || !picker.filter.is_empty() {
        format!("Filter: {} ({} files)", picker.filter, filtered.len())
    } else {
        format!("{} ({} found) - /: search, j/k: navigate, Enter: open", picker.title, picker.files.len())
    };
    let mut row = 0usize;
    if row < inner_h { buf.draw_text(x + 1, y + 1 + row, &header, bg, inner_w); row += 1; }
    if row < inner_h { row += 1; } // blank
    let footer_row_needed = 2usize;
    let list_capacity = inner_h.saturating_sub(row + footer_row_needed);
    let sel = picker.selected;
    let mut scroll = picker.scroll;
    if sel < scroll { scroll = sel; }
    if list_capacity > 0 && sel >= scroll + list_capacity { scroll = sel - list_capacity + 1; }
    for i in 0..list_capacity {
        let fi = scroll + i;
        if fi >= filtered.len() { break; }
        let (orig_idx, disp) = filtered[fi];
        let marker = if fi == sel { "▶" } else { " " };
        let line = format!("{} [{}] {}", marker, orig_idx + 1, disp);
        let mut style = bg;
        if fi == sel { style.bold = true; }
        buf.draw_text(x + 1, y + 1 + row, &line, style, inner_w);
        row += 1;
    }
    row += 1; // blank before footer
    if row < inner_h {
        buf.draw_text(x + 1, y + 1 + row, "j/k: Navigate • /: Filter • 1-9: Jump • Enter: Open • Esc: Cancel", bg, inner_w);
    }
}

fn picker_filtered(picker: &PickerState) -> Vec<(usize, String)> {
    let q = picker.filter.to_lowercase();
    picker.display.iter().enumerate().filter(|(_, d)| q.is_empty() || d.to_lowercase().contains(&q)).map(|(i, d)| (i, d.clone())).collect()
}

fn draw_palette(app: &App, buf: &mut Buffer, w: usize, h: usize) {
    let theme = &app.theme;
    let palette = match &app.palette { Some(p) => p, None => return };
    let bw = (w * 60) / 100;
    let bh = (h * 50) / 100;
    let x = (w - bw) / 2;
    let y = (h - bh) / 2;
