// ===================== Key handling =====================
fn clipboard_attempt(text: &str) -> String {
    // Try common linux clipboard tools
    let candidates: Vec<(&str, Vec<&str>)> = vec![
        ("xclip", vec!["-selection", "clipboard"]),
        ("xsel", vec!["--clipboard", "--input"]),
        ("wl-copy", vec![]),
        ("clipit", vec![]),
        ("pbcopy", vec![]),
    ];
    for (cmd, args) in candidates {
        if !which_in_path(cmd) { continue; }
        match std::process::Command::new(cmd).args(&args).stdin(std::process::Stdio::piped()).stdout(std::process::Stdio::null()).stderr(std::process::Stdio::null()).spawn() {
            Ok(mut child) => {
                if let Some(mut stdin) = child.stdin.take() { let _ = stdin.write_all(text.as_bytes()); }
                match child.wait() {
                    Ok(s) if s.success() => return "✓ Copied to clipboard".to_string(),
                    _ => continue,
                }
            }
            Err(_) => continue,
        }
    }
    "✗ Clipboard not available".to_string()
}

fn selected_heading_raw(app: &App) -> String {
    let start = app.selected_flat_idx();
    if app.flat.is_empty() { return String::new(); }
    let sec = &app.flat[start];
    let mut end = app.doc.content.len();
    for other in app.flat.iter().skip(start + 1) {
        if other.level <= sec.level { end = other.heading_start_byte; break; }
    }
    app.doc.content[sec.heading_start_byte..end].trim_end().to_string()
}

fn current_history(app: &App, selected: usize) -> HistoryEntry {
    HistoryEntry {
        document: app.doc.clone(), source_name: app.source_name.clone(), source_path: app.source_path.clone(), raw_content: app.raw_content.clone(),
    }
}
fn load_history(app: &mut App, entry: HistoryEntry) {
    app.doc = entry.document;
    app.source_name = entry.source_name;
    app.source_path = entry.source_path;
    app.raw_content = entry.raw_content;
    app.rebuild_nodes();
    app.selected_node = 0;
    app.content_scroll = 0;
    app.outline_scroll = 0;
    app.focus = Focus::Outline;
    app.links_mode = None;
    app.interactive = None;
}

fn open_file_into(app: &mut App, path: &Path, push_history: bool) {
    match std::fs::read_to_string(path) {
        Ok(content) => {
            if push_history {
                let cur = current_history(app, app.selected_node);
                app.history_back.push(cur);
                app.history_forward.clear();
            }
            app.raw_content = content.clone();
            app.doc = crate::parser::parse_document(&content);
            app.source_name = path.file_name().map(|s| s.to_string_lossy().to_string()).unwrap_or_else(|| path.display().to_string());
            app.source_path = Some(path.to_path_buf());
            app.rebuild_nodes();
            app.selected_node = 0;
            app.content_scroll = 0;
            app.outline_scroll = 0;
            app.focus = Focus::Outline;
            app.picker = None;
        }
        Err(e) => {
            app.message = Some(format!("✗ Could not open {}: {}", path.display(), e));
        }
    }
}

fn follow_link(app: &mut App, _text: &str, url: &str) {
    app.links_mode = None;
    app.interactive = None;
    if let Some(anchor) = url.strip_prefix('#') {
        // find section by slug
        let target = app.flat.iter().position(|s| crate::parser::slugify(&s.title) == anchor);
        if let Some(idx) = target {
            select_node(app, idx);
        }
        return;
    }
    if url.starts_with("http://") || url.starts_with("https://") || url.starts_with("mailto:") {
        // open external with xdg-open if present
        if which_in_path("xdg-open") {
            let _ = std::process::Command::new("xdg-open").arg(url).stdout(std::process::Stdio::null()).stderr(std::process::Stdio::null()).spawn();
        }
        app.message = Some(format!("Opening {} ...", url));
        return;
    }
    // file link: split anchor/query
    let (path_part, anchor) = match url.split_once('#') { Some((p, a)) => (p, Some(a.to_string())), None => (url, None) };
    let path_part = path_part.split('?').next().unwrap_or(path_part);
    if path_part.is_empty() {
        if let Some(a) = anchor {
            let target = app.flat.iter().position(|s| crate::parser::slugify(&s.title) == a);
            if let Some(idx) = target { select_node(app, idx); }
        }
        return;
    }
    let base = app.source_path.as_ref().and_then(|p| p.parent().map(|p| p.to_path_buf())).unwrap_or_else(|| PathBuf::from("."));
    let resolved = base.join(path_part);
    if resolved.is_dir() {
        app.message = Some(format!("✗ Link is a directory: {}", resolved.display()));
        return;
    }
    if !resolved.exists() {
        app.message = Some(format!("✗ File not found: {}", path_part));
        return;
    }
    open_file_into(app, &resolved, true);
    if let Some(a) = anchor {
        let target = app.flat.iter().position(|s| crate::parser::slugify(&s.title) == a);
        if let Some(idx) = target { select_node(app, idx); }
    }
}

fn select_node(app: &mut App, node_idx: usize) {
    if node_idx >= app.nodes.len() { return; }
    // expand ancestors
    let mut p = app.nodes[node_idx].parent;
    while let Some(pi) = p { app.nodes[pi].expanded = true; p = app.nodes[pi].parent; }
    if app.selected_node != node_idx {
        app.selected_node = node_idx;
        app.content_scroll = 0;
    }
}

fn move_selection(app: &mut App, delta: i64) {
    let visible = app.visible_nodes();
    if visible.is_empty() { return; }
    let pos = visible.iter().position(|&i| i == app.selected_node).unwrap_or(0) as i64;
    let mut new_pos = pos + delta;
    if new_pos < 0 { new_pos = 0; }
    if new_pos >= visible.len() as i64 { new_pos = visible.len() as i64 - 1; }
    select_node(app, visible[new_pos as usize]);
}

fn ensure_selected_visible(app: &mut App) {
    let visible = app.visible_nodes();
    if !visible.contains(&app.selected_node) {
        if let Some(&first) = visible.first() { app.selected_node = first; app.content_scroll = 0; }
    }
}

fn toggle_todo_filter(app: &mut App) {
    app.todo_filter = !app.todo_filter;
    if app.todo_filter {
        let count = {
            // count nodes whose subtree has open todo (before applying? same as visible count after filter)
            let mut c = 0;
            for i in 0..app.nodes.len() { if app.subtree_has_open_todo(i) { c += 1; } }
            c
        };
        ensure_selected_visible(app);
        app.message = Some(format!("Todo filter ON: {} headings with open todos", count));
    } else {
        app.message = Some("Todo filter OFF: showing all headings".to_string());
    }
}

fn handle_key(app: &mut App, key: Key) {
    // count prefix consumption handled inside normal processing
    if app.should_quit { return; }
    // Picker has priority
    if app.picker.is_some() {
        handle_picker_key(app, key);
        return;
    }
    // Palette
    if app.palette.is_some() {
        handle_palette_key(app, key);
        return;
    }
    // Help overlay: Esc/? close, navigation also scrolls help and falls through
    if app.help_visible {
        match &key {
            Key::Escape => { app.help_visible = false; app.message = None; return; }
            Key::Char('?') => { app.help_visible = false; return; }
            Key::Char('q') => { app.should_quit = true; return; }
            _ => {
                // scroll help
                let max = HELP_LINES.len().saturating_sub(10);
                match &key {
                    Key::Char('j') | Key::Down => app.help_scroll = (app.help_scroll + 1).min(max),
                    Key::Char('k') | Key::Up => app.help_scroll = app.help_scroll.saturating_sub(1),
                    Key::Char('g') => app.help_scroll = 0,
                    Key::Char('G') => app.help_scroll = max,
                    Key::Char('d') | Key::PageDown => app.help_scroll = (app.help_scroll + 10).min(max),
                    Key::Char('u') | Key::PageUp => app.help_scroll = app.help_scroll.saturating_sub(10),
                    _ => {}
                }
                // fall through to normal processing for navigation keys
                if matches!(key, Key::Char('j') | Key::Char('k') | Key::Char('g') | Key::Char('G') | Key::Char('d') | Key::Char('u') | Key::Down | Key::Up | Key::PageDown | Key::PageUp) {
                    handle_normal_key(app, key, true);
                }
                return;
            }
        }
    }
    // Search
    if app.search.is_some() {
        if handle_search_key(app, &key) {
            return;
        }
        // else fall through to normal
    }
    // Links mode
    if app.links_mode.is_some() {
        handle_links_key(app, key);
        return;
    }
    // Interactive mode
    if app.interactive.is_some() {
        handle_interactive_key(app, key);
        return;
    }
    handle_normal_key(app, key, false);
}

fn handle_search_key(app: &mut App, key: &Key) -> bool {
    let search = match &app.search { Some(s) => s.clone(), None => return false };
    if search.editing {
        match key {
            Key::Escape => { app.search = None; app.message = None; ensure_selected_visible(app); true }
            Key::Enter => {
                if let Some(s) = &mut app.search { s.editing = false; }
                true
            }
            Key::Tab => {
                if let Some(s) = &mut app.search { s.kind = match s.kind { SearchKind::Content => SearchKind::Outline, SearchKind::Outline => SearchKind::Content }; }
                true
            }
            Key::Backspace => {
                if let Some(s) = &mut app.search { s.query.pop(); s.current_match = 0; }
                if search.kind == SearchKind::Outline { ensure_selected_visible(app); }
                true
            }
            Key::CtrlU => {
                if let Some(s) = &mut app.search { s.query.clear(); s.current_match = 0; }
                if search.kind == SearchKind::Outline { ensure_selected_visible(app); }
                true
            }
            Key::Char(c) => {
                if let Some(s) = &mut app.search { s.query.push(*c); s.current_match = 0; }
                if search.kind == SearchKind::Outline { ensure_selected_visible(app); }
                true
            }
            _ => true,
        }
    } else {
        match key {
            Key::Escape => { app.search = None; app.message = None; ensure_selected_visible(app); true }
            Key::Tab => {
                if let Some(s) = &mut app.search { s.kind = match s.kind { SearchKind::Content => SearchKind::Outline, SearchKind::Outline => SearchKind::Content }; }
                true
            }
            Key::Char('/') => {
                if let Some(s) = &mut app.search { s.editing = true; }
                true
            }
            Key::Char('n') => { next_content_match(app, 1); true }
            Key::Char('N') => { next_content_match(app, -1); true }
            Key::Char('s') if search.kind == SearchKind::Content => false,
            _ => false,
        }
    }
}

fn next_content_match(app: &mut App, dir: i64) {
    // Outline kind: move to next/prev visible filtered heading
    let kind = match &app.search { Some(s) => s.kind.clone(), None => return };
    if kind == SearchKind::Outline {
        move_selection(app, dir);
        return;
    }
    let query = match &app.search { Some(s) => s.query.clone(), None => return };
    if query.is_empty() { return; }
    // generate content at last known width: recompute from terminal size
    let (tw, _th) = crossterm::terminal::size().unwrap_or((100, 30));
    let gen = generate_content(app, content_pane_inner_width(app, tw as usize));
    let q = query.to_lowercase();
    let mut match_lines: Vec<usize> = Vec::new();
    let mut total_matches = 0usize;
    for (li, line) in gen.lines.iter().enumerate() {
        let hay = line.text.to_lowercase();
        let mut start = 0usize;
        while let Some(pos) = hay[start..].find(&q) {
            match_lines.push(li);
            total_matches += 1;
            start = start + pos + q.len().max(1);
            if start >= hay.len() { break; }
        }
    }
    if total_matches == 0 { return; }
    if let Some(s) = &mut app.search {
        let cur = s.current_match as i64;
        let mut next = cur + dir;
        if next < 0 { next = total_matches as i64 - 1; }
        if next >= total_matches as i64 { next = 0; }
        s.current_match = next as usize;
    }
    let cur = app.search.as_ref().map(|s| s.current_match).unwrap_or(0);
    if let Some(&target_line) = match_lines.get(cur) {
        // scroll so target is visible
        let (_, th) = crossterm::terminal::size().unwrap_or((100, 30));
        let panes_h = (th as usize).saturating_sub(2 + if app.search.is_some() { 3 } else { 0 } + 2);
        let inner_h = panes_h.saturating_sub(2).max(1);
        if target_line < app.content_scroll { app.content_scroll = target_line; }
        if target_line >= app.content_scroll + inner_h { app.content_scroll = target_line - inner_h + 1; }
    }
}

fn handle_normal_key(app: &mut App, key: Key, _from_help: bool) {
    // clear transient message unless key sets one
    let mut keep_message = false;
    match key {
        Key::CtrlC => { app.should_quit = true; return; }
        Key::Escape => { app.should_quit = true; return; }
        Key::Char('q') => { app.should_quit = true; return; }
        Key::Char('?') => { app.help_visible = true; app.help_scroll = 0; return; }
        Key::Char(':') => {
            app.palette = Some(PaletteState { query: String::new(), selected: 0, scroll: 0 });
            app.count_prefix.clear();
            return;
        }
        Key::Char('/') => {
            app.search = Some(SearchState { kind: SearchKind::Content, query: String::new(), editing: true, current_match: 0 });
            return;
        }
        Key::Char('s') if app.links_mode.is_none() && app.interactive.is_none() => {
            app.search = Some(SearchState { kind: SearchKind::Outline, query: String::new(), editing: true, current_match: 0 });
            return;
        }
        _ => {}
    }
    // digits count prefix (outline/content normal)
    if let Key::Char(c) = key {
        if c.is_ascii_digit() && app.focus == Focus::Outline {
            // But if a search is active accepted etc, fallthrough already handled
            app.count_prefix.push(c);
            return;
        }
    }
    let count: usize = if app.count_prefix.is_empty() { 1 } else { app.count_prefix.parse().unwrap_or(1).max(1) };
    match key {
        Key::Char('j') | Key::Down => {
            match app.focus {
                Focus::Outline => move_selection(app, count as i64),
                Focus::Content => app.content_scroll += count,
            }
            app.count_prefix.clear();
        }
        Key::Char('k') | Key::Up => {
            match app.focus {
                Focus::Outline => move_selection(app, -(count as i64)),
                Focus::Content => app.content_scroll = app.content_scroll.saturating_sub(count),
            }
            app.count_prefix.clear();
        }
        Key::Char('g') => {
            match app.focus {
                Focus::Outline => { let v = app.visible_nodes(); if let Some(&f) = v.first() { select_node(app, f); } }
                Focus::Content => app.content_scroll = 0,
            }
            app.count_prefix.clear();
        }
        Key::Char('G') => {
            match app.focus {
                Focus::Outline => { let v = app.visible_nodes(); if let Some(&l) = v.last() { select_node(app, l); } }
                Focus::Content => {
                    let (tw, _) = crossterm::terminal::size().unwrap_or((100, 30));
                    let gen = generate_content(app, content_pane_inner_width(app, tw as usize));
                    let (_, th) = crossterm::terminal::size().unwrap_or((100, 30));
                    let inner_h = (th as usize).saturating_sub(2 + if app.search.is_some() { 3 } else { 0 } + 2 + 2).max(1);
                    app.content_scroll = gen.lines.len().saturating_sub(inner_h);
                }
            }
            app.count_prefix.clear();
        }
        Key::Char('p') => {
            if let Some(parent) = app.nodes.get(app.selected_node).and_then(|n| n.parent) {
                select_node(app, parent);
            }
            app.count_prefix.clear();
        }
        Key::Char('d') | Key::PageDown => {
            app.content_scroll += 10;
            app.count_prefix.clear();
        }
        Key::Char('u') | Key::PageUp => {
            app.content_scroll = app.content_scroll.saturating_sub(10);
            app.count_prefix.clear();
        }
        Key::Enter | Key::Char(' ') => {
            if app.focus == Focus::Outline {
                // If selected is "Select a file" placeholder and picker available, open picker
                if app.nodes.get(app.selected_node).map(|n| n.section.title == "Select a file").unwrap_or(false) && app.source_path.is_none() && !app.is_stdin_source {
                    let loaded_like = crate::LoadedInput {
                        document: app.doc.clone(), source_name: None, source_path: None,
                        picker_files: vec![], picker_dir: Some(PathBuf::from(".")),
                        raw_content: app.raw_content.clone(), is_stdin: false, files: vec![],
                    };
                    app.picker = Some(build_picker(&loaded_like));
                    return;
                }
                if let Some(node) = app.nodes.get_mut(app.selected_node) {
                    if node.has_children { node.expanded = !node.expanded; }
                }
            }
            app.count_prefix.clear();
        }
        Key::Char('l') | Key::Right => {
            if app.focus == Focus::Outline {
                let mut target_child: Option<usize> = None;
                if let Some(node) = app.nodes.get_mut(app.selected_node) {
                    if node.has_children && !node.expanded { node.expanded = true; }
                    else if node.has_children && node.expanded {
                        // move to first child (visible next node that is direct child)
                        target_child = None;
                        let _ = &mut target_child;
                    }
                }
                if let Some(c) = target_child { select_node(app, c); }
            }
            app.count_prefix.clear();
        }
        Key::Char('h') | Key::Left => {
            if app.focus == Focus::Outline {
                let mut to_parent: Option<usize> = None;
                if let Some(node) = app.nodes.get_mut(app.selected_node) {
                    if node.has_children && node.expanded { node.expanded = false; }
                    else { to_parent = node.parent; }
                }
                if let Some(p) = to_parent { select_node(app, p); }
            }
            app.count_prefix.clear();
        }
        Key::Tab => {
            if !app.outline_hidden {
                app.focus = match app.focus { Focus::Outline => Focus::Content, Focus::Content => Focus::Outline };
            } else {
                app.focus = Focus::Content;
            }
            app.count_prefix.clear();
        }
        Key::BackTab => {
            if !app.outline_hidden {
                app.focus = match app.focus { Focus::Outline => Focus::Content, Focus::Content => Focus::Outline };
            }
            app.count_prefix.clear();
        }
        Key::Char('r') => {
            app.raw_mode = !app.raw_mode;
            app.message = Some(if app.raw_mode { "Raw source view enabled".to_string() } else { "Rendered view enabled".to_string() });
            app.content_scroll = 0;
            keep_message = true;
            app.count_prefix.clear();
        }
        Key::Char('w') => {
            app.outline_hidden = !app.outline_hidden;
            if app.outline_hidden { app.focus = Focus::Content; } else { app.focus = Focus::Outline; }
            app.count_prefix.clear();
        }
        Key::Char('[') => {
            cycle_width(app, -1);
            keep_message = true;
            app.count_prefix.clear();
        }
        Key::Char(']') => {
            cycle_width(app, 1);
            keep_message = true;
            app.count_prefix.clear();
        }
        Key::Char('t') => {
            toggle_todo_filter(app);
            keep_message = true;
            app.count_prefix.clear();
        }
        Key::Char('m') => {
            for n in app.nodes.iter_mut() { n.bookmark = false; }
            if let Some(node) = app.nodes.get_mut(app.selected_node) { node.bookmark = true; }
            app.count_prefix.clear();
        }
        Key::Char('\'') => {
            if let Some(idx) = app.nodes.iter().position(|n| n.bookmark) {
                select_node(app, idx);
            }
            app.count_prefix.clear();
        }
        Key::Char('b') => {
            if let Some(entry) = app.history_back.pop() {
                let cur = current_history(app, app.selected_node);
                app.history_forward.push(cur);
                load_history(app, entry);
            }
            app.count_prefix.clear();
        }
        Key::Char('F') => {
            if let Some(entry) = app.history_forward.pop() {
                let cur = current_history(app, app.selected_node);
                app.history_back.push(cur);
                load_history(app, entry);
            }
            app.count_prefix.clear();
        }
        Key::Char('f') => {
            let links = app.collect_links_for_selected();
            if !links.is_empty() {
                app.links_mode = Some(LinkState { links, selected: 0 });
            }
            app.count_prefix.clear();
        }
        Key::Char('i') => {
            let els = app.collect_interactive();
            let n = els.len();
            app.interactive = Some(InteractiveState { elements: els, selected: 0, table_cell: None });
            app.message = Some(format!("✓ Interactive mode: {} elements found (Tab to cycle)", n));
            keep_message = true;
            app.count_prefix.clear();
        }
        Key::Char('e') => {
            app.message = Some("\u{1}EDITOR".to_string());
            app.count_prefix.clear();
            return;
        }
        Key::Char('y') => {
            let text = selected_heading_raw(app);
            app.message = Some(clipboard_attempt(&text));
            keep_message = true;
            app.count_prefix.clear();
        }
        Key::Char('Y') => {
            let sec = app.flat.get(app.selected_flat_idx());
            let anchor = sec.map(|s| format!("#{}", crate::parser::slugify(&s.title))).unwrap_or_default();
            let text = if let Some(s) = sec { format!("[{}]({})", s.title, anchor) } else { anchor };
            app.message = Some(clipboard_attempt(&text));
            keep_message = true;
            app.count_prefix.clear();
        }
        Key::Char('n') => {
            // search next if there's an accepted search? handled above in accepted state.
            // If a previous search query exists in state, handled. Otherwise no-op.
            app.count_prefix.clear();
        }
        Key::Char('N') => { app.count_prefix.clear(); }
        _ => {
            app.count_prefix.clear();
        }
    }
    if !keep_message {
        // messages from other actions were set explicitly; normal navigation clears prior message
        // Only clear if this handler didn't set one in this call: handled by keep_message flags for specific keys.
        // For navigation etc, clear.
        match key {
            Key::Char('r') | Key::Char('[') | Key::Char(']') | Key::Char('t') | Key::Char('i') | Key::Char('y') | Key::Char('Y') => {}
            _ => app.message = None,
        }
    }
}

fn cycle_width(app: &mut App, dir: i64) {
    let widths = [20usize, 30, 40];
    let cur_idx = widths.iter().position(|&w| w == app.outline_width).unwrap_or(1) as i64;
    let mut next = cur_idx + dir;
    if next < 0 { next = widths.len() as i64 - 1; }
    if next >= widths.len() as i64 { next = 0; }
    app.outline_width = widths[next as usize];
    app.config.outline_width = app.outline_width;
    app.config.theme = app.theme.config_name.clone();
    app.config.images_enabled = app.images_enabled;
    save_config(&app.config);
    app.message = Some(format!("Width: {}%", app.outline_width));
}

fn handle_links_key(app: &mut App, key: Key) {
    let mut state = match app.links_mode.take() { Some(s) => s, None => return };
    match key {
        Key::Escape => { app.links_mode = None; app.message = None; }
        Key::Tab | Key::Down | Key::Char('j') => {
            if !state.links.is_empty() { state.selected = (state.selected + 1) % state.links.len(); }
            app.links_mode = Some(state);
        }
        Key::BackTab | Key::Up | Key::Char('k') => {
            if !state.links.is_empty() { state.selected = if state.selected == 0 { state.links.len() - 1 } else { state.selected - 1 }; }
            app.links_mode = Some(state);
        }
        Key::Char(c) if c.is_ascii_digit() && c != '0' => {
            let idx = (c as usize) - ('1' as usize);
            if idx < state.links.len() { state.selected = idx; }
            app.links_mode = Some(state);
        }
        Key::Enter => {
            if let Some((txt, url)) = state.links.get(state.selected).cloned() {
                // links_mode already taken (None)
                follow_link(app, &txt, &url);
            }
        }
        Key::Char('y') => {
            if let Some((_, url)) = state.links.get(state.selected) {
                app.message = Some(clipboard_attempt(url));
            }
            app.links_mode = Some(state);
        }
        Key::Char('p') => {
            app.links_mode = Some(state);
            if let Some(parent) = app.nodes.get(app.selected_node).and_then(|n| n.parent) {
                select_node(app, parent);
                let links = app.collect_links_for_selected();
                if !links.is_empty() { app.links_mode = Some(LinkState { links, selected: 0 }); }
            }
        }
        Key::Char('q') => { app.should_quit = true; }
        _ => { app.links_mode = Some(state); }
    }
}

fn handle_interactive_key(app: &mut App, key: Key) {
    let mut state = match app.interactive.take() { Some(s) => s, None => return };
    match key {
        Key::Escape => { app.interactive = None; app.message = None; }
        Key::Tab | Key::Down | Key::Char('j') => {
            if !state.elements.is_empty() { state.selected = (state.selected + 1) % state.elements.len(); }
            app.interactive = Some(state);
            app.message = None;
        }
        Key::BackTab | Key::Up | Key::Char('k') => {
            if !state.elements.is_empty() { state.selected = if state.selected == 0 { state.elements.len() - 1 } else { state.selected - 1 }; }
            app.interactive = Some(state);
            app.message = None;
        }
        Key::Char('u') | Key::PageUp => { app.content_scroll = app.content_scroll.saturating_sub(10); app.interactive = Some(state); }
        Key::Char('d') | Key::PageDown => { app.content_scroll += 10; app.interactive = Some(state); }
        Key::Enter | Key::Char(' ') => {
            let el = state.elements.get(state.selected).cloned();
            app.interactive = Some(state);
            if let Some(el) = el {
                activate_element(app, &el, key == Key::Char(' '));
            }
        }
        Key::Char('y') => {
            let copy = state.elements.get(state.selected).map(|e| {
                if e.kind == "link" { e.copy_text.clone() } else { e.copy_text.clone() }
            }).unwrap_or_default();
            app.message = Some(clipboard_attempt(&copy));
            app.interactive = Some(state);
        }
        Key::Char('h') | Key::Left => { app.interactive = Some(state); }
        Key::Char('l') | Key::Right => { app.interactive = Some(state); }
        Key::Char('q') => { app.should_quit = true; }
        _ => { app.interactive = Some(state); }
    }
}

fn activate_element(app: &mut App, el: &InteractiveElement, _is_space: bool) {
    match el.kind.as_str() {
        "checkbox" => {
            // Toggle the checkbox in the underlying file content: nth checkbox in document order for its section
            // Compute a document-order global checkbox index: sections up to el.section_flat_idx
            // Our raw_content toggle: find checkbox occurrences in processed document order? Files use raw_content.
            // Toggle in raw_content string: find all "- [ ]"/"- [x]" style occurrences and pick the one corresponding.
            // Determine global checkbox ordinal:
            let ordinal = global_checkbox_ordinal(app, el);
            if let Some(o) = ordinal {
                if toggle_nth_checkbox_in_text(&mut app.raw_content, o) {
                    app.dirty = true;
                    app.doc = crate::parser::parse_document(&app.raw_content);
                    // preserve selection node by index if possible
                    let sel = app.selected_node;
                    app.rebuild_nodes();
                    app.selected_node = sel.min(app.nodes.len().saturating_sub(1));
                    // Recreate interactive state elements to reflect toggle
                    let els = app.collect_interactive();
                    app.interactive = Some(InteractiveState { elements: els, selected: app.interactive.as_ref().map(|s| s.selected).unwrap_or(0), table_cell: None });
                    app.message = Some("☑ Toggled checkbox (unsaved - use :w in palette to save)".to_string());
                    // Simplify message maybe overwritten later; keep generic if clipboard etc.
                    app.message = Some("Toggled checkbox".to_string());
                }
            }
        }
        "link" => {
            if let Some(url) = &el.link_url {
                let txt = el.display_text.clone();
                let urlc = url.clone();
                app.interactive = None;
                follow_link(app, &txt, &urlc);
            }
        }
        "code" => {
            app.message = Some(clipboard_attempt(&el.copy_text));
        }
        "table" => {
            app.message = Some("Table mode: use hjkl to navigate cells, Enter to edit".to_string());
        }
        "image" => {
            app.message = Some(format!("Image: {}", el.display_text));
        }
        _ => {}
    }
}

fn global_checkbox_ordinal(app: &App, el: &InteractiveElement) -> Option<usize> {
    // Count checkboxes in flat sections before el.section_flat_idx, plus el.checkbox_index in its section.
    let mut count = 0usize;
    for (i, sec) in app.flat.iter().enumerate() {
        if i == el.section_flat_idx {
            return el.checkbox_index.map(|ci| count + ci);
        }
        count += count_checkboxes_in_blocks(&sec.content.blocks);
    }
    None
}
fn count_checkboxes_in_blocks(blocks: &[Block]) -> usize {
    let mut c = 0;
    for b in blocks {
        match b {
            Block::List { items, .. } => {
                for it in items {
                    if it.checked.is_some() { c += 1; }
                    c += count_checkboxes_in_blocks(&it.blocks);
                }
            }
            Block::Blockquote { blocks, .. } => c += count_checkboxes_in_blocks(blocks),
            _ => {}
        }
    }
    c
}
fn toggle_nth_checkbox_in_text(text: &mut String, ordinal: usize) -> bool {
    // Find occurrences of "[ ]", "[x]", "[X]" preceded by "- "/"* "/"+" or digit marker, in order.
    let bytes = text.clone();
    let mut count = 0usize;
    let mut idx = 0usize;
    let b = bytes.as_bytes();
    while idx + 2 < b.len() {
        if b[idx] == b'[' && idx + 2 < b.len() && (b[idx + 1] == b' ' || b[idx + 1] == b'x' || b[idx + 1] == b'X') && b[idx + 2] == b']' {
            // check it's a task marker: preceded (ignoring spaces) by - * + or digit.
            let mut j = idx;
            let mut ok = false;
            while j > 0 {
                j -= 1;
                if b[j] == b' ' || b[j] == b'\t' { continue; }
                if b[j] == b'-' || b[j] == b'*' || b[j] == b'+' || b[j].is_ascii_digit() { ok = true; }
                break;
            }
            if ok {
                if count == ordinal {
                    let mut owned = bytes.clone().into_bytes();
                    if owned[idx + 1] == b' ' { owned[idx + 1] = b'x'; } else { owned[idx + 1] = b' '; }
                    *text = String::from_utf8_lossy(&owned).to_string();
                    return true;
                }
                count += 1;
            }
        }
        idx += 1;
    }
    false
}

fn handle_palette_key(app: &mut App, key: Key) {
    let mut pal = match app.palette.take() { Some(p) => p, None => return };
    match key {
        Key::Escape => { app.palette = None; app.message = None; }
        Key::Enter => {
            let filtered = palette_filtered(&pal.query);
            let action_query = pal.query.clone();
            app.palette = None;
            if let Some(cmd) = filtered.get(pal.selected) {
                execute_palette_action(app, cmd.action, &action_query);
            }
        }
        Key::Down => {
            let filtered = palette_filtered(&pal.query);
            if !filtered.is_empty() { pal.selected = (pal.selected + 1).min(filtered.len() - 1); }
            app.palette = Some(pal);
        }
        Key::Up => {
            pal.selected = pal.selected.saturating_sub(1);
            app.palette = Some(pal);
        }
        Key::Tab => {
            let filtered = palette_filtered(&pal.query);
            if !filtered.is_empty() { pal.selected = (pal.selected + 1) % filtered.len(); }
            app.palette = Some(pal);
        }
        Key::BackTab => {
            let filtered = palette_filtered(&pal.query);
            if !filtered.is_empty() { pal.selected = if pal.selected == 0 { filtered.len() - 1 } else { pal.selected - 1 }; }
            app.palette = Some(pal);
        }
        Key::Backspace => { pal.query.pop(); pal.selected = 0; pal.scroll = 0; app.palette = Some(pal); }
        Key::CtrlU => { pal.query.clear(); pal.selected = 0; app.palette = Some(pal); }
        Key::Char(c) => { pal.query.push(c); pal.selected = 0; pal.scroll = 0; app.palette = Some(pal); }
        _ => { app.palette = Some(pal); }
    }
}

fn execute_palette_action(app: &mut App, action: &str, query: &str) {
    match action {
        "save" => {
            if let Some(path) = &app.source_path {
                match std::fs::write(path, &app.raw_content) {
                    Ok(()) => { app.dirty = false; app.message = Some("✓ Saved changes".to_string()); }
                    Err(e) => app.message = Some(format!("✗ Save failed: {}", e)),
                }
            } else {
                app.message = Some("✗ No file to save".to_string());
            }
        }
        "undo" => {
            // Reload from disk if file exists
            if let Some(path) = &app.source_path {
                if let Ok(content) = std::fs::read_to_string(path) {
                    app.raw_content = content.clone();
                    app.doc = crate::parser::parse_document(&content);
                    app.rebuild_nodes();
                    app.dirty = false;
                }
            }
        }
        "savewidth" => {
            app.config.outline_width = app.outline_width;
            app.config.theme = app.theme.config_name.clone();
            save_config(&app.config);
            app.message = Some("✓ Width saved to config".to_string());
        }
        "outline" => {
            app.outline_hidden = !app.outline_hidden;
            if app.outline_hidden { app.focus = Focus::Content; } else { app.focus = Focus::Outline; }
        }
        "help" => { app.help_visible = true; app.help_scroll = 0; }
        "raw" => {
            app.raw_mode = !app.raw_mode;
            app.message = Some(if app.raw_mode { "Raw source view enabled".to_string() } else { "Rendered view enabled".to_string() });
        }
        "top" => { let v = app.visible_nodes(); if let Some(&f) = v.first() { select_node(app, f); } }
        "bottom" => { let v = app.visible_nodes(); if let Some(&l) = v.last() { select_node(app, l); } }
        "collapse_all" => { for n in app.nodes.iter_mut() { n.expanded = false; } ensure_selected_visible(app); }
        "expand_all" => { for n in app.nodes.iter_mut() { n.expanded = true; } }
        "collapse_level" | "expand_level" => {
            if let Some(level) = parse_level_from_query(query) {
                for n in app.nodes.iter_mut() {
                    if n.section.level == level { n.expanded = action == "expand_level"; }
                    if action == "expand_level" && n.section.level < level { n.expanded = true; }
                }
                ensure_selected_visible(app);
            }
        }
        "quit" => { app.should_quit = true; }
        _ => {}
    }
}
fn parse_level_from_query(q: &str) -> Option<u8> {
    for part in q.split_whitespace() {
        if let Ok(n) = part.parse::<u8>() { if (1..=6).contains(&n) { return Some(n); } }
    }
    None
}

fn handle_picker_key(app: &mut App, key: Key) {
    let mut picker = match app.picker.take() { Some(p) => p, None => return };
    if picker.filtering {
        match key {
            Key::Escape => { picker.filtering = false; picker.filter.clear(); picker.selected = 0; app.picker = Some(picker); }
            Key::Enter => {
                let filtered = picker_filtered(&picker);
                if let Some((orig_idx, _)) = filtered.get(picker.selected) {
                    let path = picker.files[*orig_idx].clone();
                    app.picker = Some(picker);
                    // open file (push history)
                    open_file_into(app, &path, true);
                    return;
                }
                app.picker = Some(picker);
            }
            Key::Backspace => { picker.filter.pop(); picker.selected = 0; app.picker = Some(picker); }
            Key::CtrlU => { picker.filter.clear(); picker.selected = 0; app.picker = Some(picker); }
            Key::Char(c) => { picker.filter.push(c); picker.selected = 0; app.picker = Some(picker); }
            _ => { app.picker = Some(picker); }
        }
        return;
    }
    match key {
        Key::Escape => { app.picker = None; app.message = None; }
        Key::Char('q') => { app.should_quit = true; }
        Key::Char('/') => { picker.filtering = true; app.picker = Some(picker); }
        Key::Char('j') | Key::Down => {
            let filtered = picker_filtered(&picker);
            if !filtered.is_empty() { picker.selected = (picker.selected + 1).min(filtered.len() - 1); }
            app.picker = Some(picker);
        }
        Key::Char('k') | Key::Up => { picker.selected = picker.selected.saturating_sub(1); app.picker = Some(picker); }
        Key::Char('g') => { picker.selected = 0; app.picker = Some(picker); }
        Key::Char('G') => {
            let filtered = picker_filtered(&picker);
            if !filtered.is_empty() { picker.selected = filtered.len() - 1; }
            app.picker = Some(picker);
        }
        Key::Char(c) if c.is_ascii_digit() && c != '0' => {
            let idx = (c as usize) - ('1' as usize);
            let filtered = picker_filtered(&picker);
            if idx < filtered.len() { picker.selected = idx; }
            app.picker = Some(picker);
        }
        Key::Enter => {
            let filtered = picker_filtered(&picker);
            if let Some((orig_idx, _)) = filtered.get(picker.selected) {
                let path = picker.files[*orig_idx].clone();
                app.picker = Some(picker);
                open_file_into(app, &path, true);
                return;
            }
            app.picker = Some(picker);
        }
        _ => { app.picker = Some(picker); }
    }
}
