cat >> src/tui.rs <<'RS'

fn link_filtered_indices(state: &LinkState) -> Vec<usize> {
    let q = state.filter.to_lowercase();
    state.links.iter().enumerate().filter(|(_, (text, url))| {
        q.is_empty() || text.to_lowercase().contains(&q) || url.to_lowercase().contains(&q)
    }).map(|(i, _)| i).collect()
}

fn draw_link_navigator(app: &App, buf: &mut Buffer, w: usize, h: usize) {
    let theme = &app.theme;
    let state = match &app.links_mode { Some(s) => s, None => return };
    let bw = (w * 80) / 100;
    let bh = (h * 60) / 100;
    let x = (w - bw) / 2;
    let y = (h - bh) / 2;
    let border = Style { fg: Some(theme.accent), bg: Some(theme.pane_bg), ..Default::default() };
    let bg = Style { fg: Some(theme.text), bg: Some(theme.pane_bg), ..Default::default() };
    draw_box(buf, x, y, bw, bh, "Link Navigator", border, bg);
    let inner_w = bw - 2;
    let inner_h = bh - 2;
    let filtered = link_filtered_indices(state);
    // build display lines
    let mut lines: Vec<(String, bool)> = Vec::new();
    if state.filtering || !state.filter.is_empty() {
        lines.push((format!("Search: {}_", state.filter), false));
    } else {
        lines.push((format!("Links in this section ({} found) - /: search, Tab/j/k: navigate, Enter: follow", state.links.len()), false));
    }
    lines.push((String::new(), false));
    // selected position in filtered list
    for (pos, &orig_idx) in filtered.iter().enumerate() {
        let (text, url) = &state.links[orig_idx];
        let marker = if pos == state.selected.min(filtered.len().saturating_sub(1)) { "▶" } else { " " };
        // selection state stores index into filtered list for navigator
        lines.push((format!("{} [{}] {} → {}", marker, orig_idx + 1, text, url), pos == state.selected));
        lines.push((String::new(), false));
    }
    lines.push(("Tab/j/k: Navigate • /: Search • 1-9: Jump • p: Parent • Enter: Follow • Esc: Cancel".to_string(), false));
    // wrap long lines (footer) preserving lines order
    let mut wrapped: Vec<(String, bool)> = Vec::new();
    for (text, sel) in &lines {
        if text.is_empty() { wrapped.push((String::new(), *sel)); continue; }
        for part in wrap_logical(text, inner_w, false) { wrapped.push((part, *sel)); }
    }
    for row in 0..inner_h {
        if row >= wrapped.len() { break; }
        let (text, is_sel) = &wrapped[row];
        let mut style = bg;
        if *is_sel { style.bold = true; }
        buf.draw_text(x + 1, y + 1 + row, text, style, inner_w);
    }
}
