    let mut state = match app.links_mode.take() { Some(s) => s, None => return };
    if state.filtering {
        match key {
            Key::Escape => { state.filtering = false; state.filter.clear(); state.selected = 0; app.links_mode = Some(state); }
            Key::Enter => {
                let filtered = link_filtered_indices(&state);
                if let Some(&orig_idx) = filtered.get(state.selected) {
                    if let Some((txt, url)) = state.links.get(orig_idx).cloned() {
                        follow_link(app, &txt, &url);
                        return;
                    }
                }
                app.links_mode = Some(state);
            }
            Key::Backspace => { state.filter.pop(); state.selected = 0; app.links_mode = Some(state); }
            Key::CtrlU => { state.filter.clear(); state.selected = 0; app.links_mode = Some(state); }
            Key::Char(c) => { state.filter.push(c); state.selected = 0; app.links_mode = Some(state); }
            _ => { app.links_mode = Some(state); }
        }
        return;
    }
    let filtered = link_filtered_indices(&state);
    match key {
        Key::Escape => { app.links_mode = None; app.message = None; }
        Key::Tab | Key::Down | Key::Char('j') => {
            if !filtered.is_empty() { state.selected = (state.selected + 1) % filtered.len(); }
            app.links_mode = Some(state);
        }
        Key::BackTab | Key::Up | Key::Char('k') => {
            if !filtered.is_empty() { state.selected = if state.selected == 0 { filtered.len() - 1 } else { state.selected - 1 }; }
            app.links_mode = Some(state);
        }
        Key::Char('/') => { state.filtering = true; app.links_mode = Some(state); }
        Key::Char(c) if c.is_ascii_digit() && c != '0' => {
            let idx = (c as usize) - ('1' as usize);
            // digits jump by original link number (position in filtered if filter active else absolute)
            if state.filter.is_empty() {
                if idx < state.links.len() {
                    state.selected = idx;
                }
            } else if idx < filtered.len() { state.selected = idx; }
            app.links_mode = Some(state);
        }
        Key::Enter => {
            if let Some(&orig_idx) = filtered.get(state.selected) {
                if let Some((txt, url)) = state.links.get(orig_idx).cloned() {
                    follow_link(app, &txt, &url);
                    return;
                }
            }
            app.links_mode = Some(state);
        }
        Key::Char('y') => {
            if let Some(&orig_idx) = filtered.get(state.selected) {
                if let Some((_, url)) = state.links.get(orig_idx) {
                    app.message = Some(clipboard_attempt(url));
                }
            }
            app.links_mode = Some(state);
        }
        Key::Char('p') => {
            app.links_mode = Some(state);
            if let Some(parent) = app.nodes.get(app.selected_node).and_then(|n| n.parent) {
                select_node(app, parent);
                let links = app.collect_links_for_selected();
                if !links.is_empty() { app.links_mode = Some(LinkState { links, selected: 0, filter: String::new(), filtering: false }); }
            }
        }
        Key::Char('q') => { app.should_quit = true; }
        _ => { app.links_mode = Some(state); }
    }
}

