fn scroll_to_interactive_element(app: &mut App, selected_el: usize) {
    let el = match app.interactive.as_ref().and_then(|s| s.elements.get(selected_el)) { Some(e) => e.clone(), None => return };
    let (tw, th) = crossterm::terminal::size().unwrap_or((100, 30));
    let gen = generate_content(app, content_pane_inner_width(app, tw as usize));
    let mut target: Option<usize> = None;
    for (i, line) in gen.lines.iter().enumerate() {
        if line.element == Some(selected_el) { target = Some(i); break; }
        if el.kind == "link" && line.text.contains(&el.display_text) { target = Some(i); break; }
    }
    if let Some(t) = target {
        let panes_h = (th as usize).saturating_sub(2 + if app.search.is_some() { 3 } else { 0 } + 2);
        let inner_h = panes_h.saturating_sub(2).max(1);
        if t < app.content_scroll { app.content_scroll = t; }
        if t >= app.content_scroll + inner_h { app.content_scroll = t - inner_h + 1; }
    }
}
