cat >> src/tui.rs <<'RS'

fn outline_scrollbar_params(app: &App, visible: &[usize], sel_pos: usize) -> (usize, usize) {
    let search_active = app.search.as_ref().map(|s| s.kind == SearchKind::Outline && !s.query.is_empty()).unwrap_or(false);
    if search_active {
        return (visible.len(), sel_pos);
    }
    // expanded-visible (ignoring search/todo filters)
    let mut expanded_visible: Vec<usize> = Vec::new();
    for (i, n) in app.nodes.iter().enumerate() {
        let mut vis = true;
        let mut p = n.parent;
        while let Some(pi) = p { if !app.nodes[pi].expanded { vis = false; break; } p = app.nodes[pi].parent; }
        if vis { expanded_visible.push(i); }
    }
    let pos = expanded_visible.iter().position(|&i| i == app.selected_node).unwrap_or(sel_pos);
    if app.todo_filter {
        (app.nodes.len(), pos)
    } else {
        (expanded_visible.len(), pos)
    }
}
