new=r'''fn handle_interactive_key(app: &mut App, key: Key) {
    let mut state = match app.interactive.take() { Some(s) => s, None => return };
    // Table cell editing prompt
    if state.table_edit.is_some() {
        let mut edit = state.table_edit.take().unwrap();
        match key {
            Key::Escape => { app.interactive = Some(state); app.message = None; }
            Key::Enter => {
                let row = edit.row; let col = edit.col; let text = edit.text.clone();
                let el = state.elements.get(state.selected).cloned();
                app.interactive = Some(state);
                if let Some(el) = el { apply_table_edit(app, &el, row, col, &text); }
            }
            Key::Backspace => { edit.text.pop(); state.table_edit = Some(edit); app.interactive = Some(state); }
            Key::CtrlU => { edit.text.clear(); state.table_edit = Some(edit); app.interactive = Some(state); }
            Key::Char(c) => { edit.text.push(c); state.table_edit = Some(edit); app.interactive = Some(state); }
            _ => { state.table_edit = Some(edit); app.interactive = Some(state); }
        }
        return;
    }
    // Table mode
    if state.table_mode {
        let el = state.elements.get(state.selected).cloned();
        let (nrows, ncols) = el.as_ref().and_then(|e| e.table_data.as_ref()).map(|(h, r, _)| (1 + r.len(), h.len())).unwrap_or((1, 1));
        match key {
            Key::Escape => { state.table_mode = false; app.interactive = Some(state); app.message = None; }
            Key::Char('j') | Key::Down => { state.table_row = (state.table_row + 1).min(nrows.saturating_sub(1)); app.interactive = Some(state); app.message = None; }
            Key::Char('k') | Key::Up => { state.table_row = state.table_row.saturating_sub(1); app.interactive = Some(state); app.message = None; }
            Key::Char('l') | Key::Right => { state.table_col = (state.table_col + 1).min(ncols.saturating_sub(1)); app.interactive = Some(state); app.message = None; }
            Key::Char('h') | Key::Left => { state.table_col = state.table_col.saturating_sub(1); app.interactive = Some(state); app.message = None; }
            Key::Enter | Key::Char('e') => {
                if let Some(el) = &el {
                    if let Some((headers, rows, _)) = &el.table_data {
                        let text = if state.table_row == 0 { headers.get(state.table_col).cloned().unwrap_or_default() } else { rows.get(state.table_row - 1).and_then(|r| r.get(state.table_col)).cloned().unwrap_or_default() };
                        state.table_edit = Some(TableEdit { text, row: state.table_row, col: state.table_col });
                    }
                }
                app.interactive = Some(state);
            }
            Key::Char('y') => {
                if let Some(el) = &el {
                    if let Some((headers, rows, _)) = &el.table_data {
                        let text = if state.table_row == 0 { headers.get(state.table_col).cloned().unwrap_or_default() } else { rows.get(state.table_row - 1).and_then(|r| r.get(state.table_col)).cloned().unwrap_or_default() };
                        app.message = Some(clipboard_attempt(&text));
                    }
                }
                app.interactive = Some(state);
            }
            Key::Char('Y') => {
                if let Some(el) = &el {
                    if let Some((headers, rows, _)) = &el.table_data {
                        let cells: Vec<String> = if state.table_row == 0 { headers.clone() } else { rows.get(state.table_row - 1).cloned().unwrap_or_default() };
                        app.message = Some(clipboard_attempt(&format!("| {} |", cells.join(" | "))));
                    }
                }
                app.interactive = Some(state);
            }
            Key::Char('r') => {
                if let Some(el) = &el {
                    app.message = Some(clipboard_attempt(&format_table_markdown(el)));
                }
                app.interactive = Some(state);
            }
            Key::Char('q') => { app.should_quit = true; }
            _ => { app.interactive = Some(state); }
        }
        return;
    }
    match key {
        Key::Escape => { app.interactive = None; app.message = None; }
        Key::Tab | Key::Down | Key::Char('j') => {
            if !state.elements.is_empty() { state.selected = (state.selected + 1) % state.elements.len(); }
            state.moved = true;
            let sel = state.selected;
            app.interactive = Some(state);
            app.message = None;
            scroll_to_interactive_element(app, sel);
