fn format_table_markdown(el: &InteractiveElement) -> String {
    if let Some((headers, rows, _)) = &el.table_data {
        let mut lines = vec![format!("| {} |", headers.join(" | ")), format!("| {} |", headers.iter().map(|_| "---").collect::<Vec<_>>().join(" | "))];
        for r in rows { lines.push(format!("| {} |", r.join(" | "))); }
        lines.join("\n")
    } else { String::new() }
}

fn apply_table_edit(app: &mut App, el: &InteractiveElement, row: usize, col: usize, new_text: &str) {
    let (headers, rows, ordinal_in_section) = match &el.table_data { Some(x) => x.clone(), None => return };
    // global table ordinal: count tables in flat sections before this one + ordinal_in_section
    let mut global_ordinal = ordinal_in_section;
    for (i, sec) in app.flat.iter().enumerate() {
        if i == el.section_flat_idx { break; }
        global_ordinal += count_tables_in_blocks(&sec.content.blocks);
    }
    // update doc model: find matching table in the section
    if let Some(sec) = app.flat.get_mut(el.section_flat_idx) {
        let _ = sec;
    }
    // Apply to doc via rebuilding from edited raw below; first update raw_content table
    let updated = update_table_in_raw(&mut app.raw_content, global_ordinal, &headers, &rows, row, col, new_text);
    if updated {
        app.pending_edit_count += 1;
        app.dirty = true;
        let sel_node = app.selected_node;
        let sel_el = app.interactive.as_ref().map(|s| s.selected).unwrap_or(0);
        let trow = app.interactive.as_ref().map(|s| s.table_row).unwrap_or(0);
        let tcol = app.interactive.as_ref().map(|s| s.table_col).unwrap_or(0);
        app.doc = crate::parser::parse_document(&app.raw_content);
        app.rebuild_nodes();
        app.selected_node = sel_node.min(app.nodes.len().saturating_sub(1));
        let els = app.collect_interactive();
        app.interactive = Some(InteractiveState { elements: els, selected: sel_el, table_cell: None, moved: true, table_mode: true, table_row: trow, table_col: tcol, table_edit: None });
        let n = app.pending_edit_count;
        app.message = Some(format!("✓ Cell updated ({} unsaved change{})", n, if n == 1 { "" } else { "s" }));
    }
}

fn count_tables_in_blocks(blocks: &[Block]) -> usize {
    let mut c = 0;
    for b in blocks {
        match b {
            Block::Table { .. } => c += 1,
            Block::Blockquote { blocks, .. } => c += count_tables_in_blocks(blocks),
            Block::List { items, .. } => { for it in items { c += count_tables_in_blocks(&it.blocks); } }
            _ => {}
        }
    }
    c
}

fn update_table_in_raw(raw: &mut String, global_ordinal: usize, _headers: &[String], _rows: &[Vec<String>], row: usize, col: usize, new_text: &str) -> bool {
    let text = raw.clone();
    let mut lines: Vec<String> = text.lines().map(|s| s.to_string()).collect();
    let had_trailing_newline = text.ends_with('\n');
    let mut table_idx = 0usize;
    let mut i = 0usize;
    while i + 1 < lines.len() {
        // table start if next line is delimiter
        let is_delim = {
            let cells: Vec<&str> = lines[i + 1].split('|').collect();
            lines[i].contains('|') && lines[i + 1].contains('-') && cells.iter().all(|c| { let t = c.trim(); t.is_empty() || t.chars().all(|ch| ch == '-' || ch == ':') })
        };
        if is_delim {
            if table_idx == global_ordinal {
                // collect rows
                let start = i;
                let mut end = i + 2;
                while end < lines.len() && !lines[end].trim().is_empty() && lines[end].contains('|') { end += 1; }
                // rebuild with updated cell
                let split_cells = |line: &str| -> Vec<String> {
                    let mut v: Vec<String> = line.split('|').map(|s| s.trim().to_string()).collect();
                    if !v.is_empty() && v.first().map(|s| s.is_empty()).unwrap_or(false) { v.remove(0); }
                    if !v.is_empty() && v.last().map(|s| s.is_empty()).unwrap_or(false) { v.pop(); }
                    v
                };
                let mut header_cells = split_cells(&lines[start]);
                let delim_line = lines[start + 1].clone();
                let mut data: Vec<Vec<String>> = Vec::new();
                for r in (start + 2)..end { data.push(split_cells(&lines[r])); }
                if row == 0 {
                    if col < header_cells.len() { header_cells[col] = new_text.to_string(); }
                } else if row - 1 < data.len() && col < data[row - 1].len() {
                    data[row - 1][col] = new_text.to_string();
                } else { return false; }
                let mut new_lines: Vec<String> = Vec::new();
                new_lines.push(format!("| {} |", header_cells.join(" | ")));
                new_lines.push(delim_line);
                for r in &data { new_lines.push(format!("| {} |", r.join(" | "))); }
                lines.splice(start..end, new_lines);
                let mut out = lines.join("\n");
                if had_trailing_newline { out.push('\n'); }
                *raw = out;
                return true;
            }
            table_idx += 1;
            i += 2;
            continue;
        }
        i += 1;
    }
    false
}

