new=r'''fn draw_picker(app: &App, buf: &mut Buffer, w: usize, h: usize) {
    let theme = &app.theme;
    let picker = match &app.picker { Some(p) => p, None => return };
    let bw = (w * 80) / 100;
    let bh = (h * 60) / 100;
    let x = (w - bw) / 2;
    let y = (h - bh) / 2;
    let border = Style { fg: Some(theme.accent), bg: Some(theme.pane_bg), ..Default::default() };
    let bg = Style { fg: Some(theme.text), bg: Some(theme.pane_bg), ..Default::default() };
    draw_box(buf, x, y, bw, bh, "File Picker", border, bg);
    let inner_w = bw - 2;
    let inner_h = bh - 2;
    let filtered = picker_filtered(picker);
    let mut lines: Vec<(String, bool, Option<usize>)> = Vec::new(); // text, bold, filtered index if item
    if picker.filtering || !picker.filter.is_empty() {
        lines.push((format!("Files ({}/{}) - /: search, Enter: open, Esc: stop search", filtered.len(), picker.files.len()), false, None));
        lines.push((format!("Filter: {}▌", picker.filter), false, None));
        if filtered.is_empty() {
            lines.push(("No files match your search".to_string(), false, None));
            lines.push((String::new(), false, None));
        } else {
            for (pos, (orig_idx, disp)) in filtered.iter().enumerate() {
                let marker = if pos == picker.selected { "▶" } else { " " };
                lines.push((format!("{} [{}] {}", marker, orig_idx + 1, disp), pos == picker.selected, Some(pos)));
                lines.push((String::new(), false, None));
            }
        }
        lines.push(("Type to filter • Enter: select • Esc: stop search • Backspace: delete".to_string(), false, None));
    } else {
        lines.push((format!("{} ({} found) - /: search, j/k: navigate, Enter: open", picker.title, picker.files.len()), false, None));
        lines.push((String::new(), false, None));
        for (pos, (orig_idx, disp)) in filtered.iter().enumerate() {
            let marker = if pos == picker.selected { "▶" } else { " " };
            lines.push((format!("{} [{}] {}", marker, orig_idx + 1, disp), pos == picker.selected, Some(pos)));
            lines.push((String::new(), false, None));
        }
        lines.push(("j/k: Navigate • /: Filter • 1-9: Jump • Enter: Open • Esc: Cancel".to_string(), false, None));
    }
    // scroll so selected item line is visible
    let mut scroll = picker.scroll;
    if let Some(sel_line) = lines.iter().position(|(_, _, fi)| fi.map(|v| v == picker.selected).unwrap_or(false)) {
        if sel_line < scroll { scroll = sel_line; }
        if inner_h > 0 && sel_line >= scroll + inner_h { scroll = sel_line - inner_h + 1; }
    }
    for row in 0..inner_h {
        let li = scroll + row;
        if li >= lines.len() { break; }
        let (text, is_sel, _) = &lines[li];
        let mut style = bg;
        if *is_sel { style.bold = true; }
        // wrap long lines
        if unicode_width::UnicodeWidthStr::width(text.as_str()) > inner_w {
            let wrapped = wrap_logical(text, inner_w, false);
            if let Some(first) = wrapped.first() { buf.draw_text(x + 1, y + 1 + row, first, style, inner_w); }
        } else {
            buf.draw_text(x + 1, y + 1 + row, text, style, inner_w);
        }
    }
}

