cat >> src/tui.rs <<'RS'

fn compute_footer_segments(app: &App) -> Vec<(String, String)> {
    let seg = |pairs: &[(&str, &str)]| pairs.iter().map(|(a, b)| (a.to_string(), b.to_string())).collect::<Vec<_>>();
    if app.palette.is_some() {
        return seg(&[("j/k", "Navigate"), ("Enter", "Select"), ("Esc", "Cancel")]);
    }
    if app.links_mode.is_some() {
        return seg(&[("Tab", "Next Link"), ("1-9", "Jump"), ("Enter", "Follow"), ("y", "Copy URL"), ("Esc", "Exit")]);
    }
    if let Some(st) = &app.interactive {
        if st.table_edit.is_some() {
            return seg(&[("Enter", "Save"), ("Esc", "Cancel")]);
        }
        if st.table_mode {
            return seg(&[("j/k", "Row"), ("h/l", "Col"), ("e", "Edit"), ("y", "Copy"), ("Esc", "Exit Table")]);
        }
        if let Some(el) = st.elements.get(st.selected) {
