                let set_fg = |buf: &mut Buffer, cx: usize, y: usize, c: Color, bold: bool| {
                    if cx < buf.w && y < buf.h {
                        let idx = buf.idx(cx, y);
                        buf.cells[idx].style.fg = Some(c);
                        if bold { buf.cells[idx].style.bold = true; }
                    }
                };
                if matches!(line.kind, LineKind::List) {
                    if let Some(mpos) = display_text.find(|c| c == '•' || c == '☐' || c == '☑') {
                        let px = unicode_width::UnicodeWidthStr::width(&display_text[..mpos]);
                        set_fg(&mut *buf, content_x + 1 + px, y, col(6, (0, 255, 255)), false);
                    } else {
                        // ordered marker: digits + '.'
                        let trimmed = display_text.trim_start_matches(|c| c == ' ' || c == '→');
                        let off = display_text.len() - trimmed.len();
                        let mut di = 0usize;
                        let mut digits = String::new();
                        for ch in trimmed.chars() { if ch.is_ascii_digit() { digits.push(ch); di += 1; } else { break; } }
                        if !digits.is_empty() && trimmed.chars().nth(di) == Some('.') {
                            for k in 0..=di {
                                set_fg(&mut *buf, content_x + 1 + off + k, y, col(6, (0, 255, 255)), false);
                            }
                        }
                        let _ = off;
                    }
                }
                if matches!(line.kind, LineKind::Table) {
                    let is_header = li > 0 && gen.lines[li - 1].text.starts_with('┌');
                    let mut cx = content_x + 1;
                    for ch in display_text.chars() {
                        let cwd = unicode_width::UnicodeWidthChar::width(ch).unwrap_or(0);
                        if "┌┬┐├┼┤└┴┘─│".contains(ch) {
                            set_fg(&mut *buf, cx, y, col(241, (160, 160, 160)), false);
                        } else if is_header && ch != ' ' {
                            set_fg(&mut *buf, cx, y, col(121, (150, 255, 190)), true);
                        }
                        cx += cwd;
                    }
                }
            }
            // search highlighting (content)'''
if anchor not in t: raise SystemExit("anchor missing")
t=t.replace(anchor,new)
p.write_text(t)
