cat >> src/tui.rs <<'RS'

fn draw_code_line(buf: &mut Buffer, x: usize, y: usize, text: &str, kind: &LineKind, base_bg: Style, max_w: usize) {
    let lang = match kind { LineKind::Code(l) => l.to_lowercase(), _ => String::new() };
    let mk = |idx: u8, rgb: (u8, u8, u8), italic: bool| Style { fg: Some(Color(idx, rgb)), bg: base_bg.bg, bold: false, italic, underline: false, force_rgb: true };
    let st_text = mk(188, (192, 197, 206), false);
    let st_kw = mk(175, (180, 142, 173), false);
    let st_fn = mk(110, (143, 161, 179), false);
    let st_str = mk(150, (163, 190, 140), false);
    let st_num = mk(173, (208, 135, 108), false);
    let st_com = mk(66, (101, 115, 126), true);
    let st_type = mk(186, (235, 203, 139), false);
    const KEYWORDS: &[&str] = &["fn","let","mut","pub","struct","enum","impl","trait","for","while","if","else","match","return","use","mod","const","static","type","where","async","await","break","continue","loop","in","move","ref","self","Self","crate","def","class","import","from","as","pass","try","except","finally","with","lambda","global","nonlocal","assert","del","is","not","and","or","func","function","var","package","func","go","defer","chan","map","interface","switch","case","default","select","fallthrough","range","void","int","float","bool","string","char","double","long","short","unsigned","signed","new","delete","this","super","extends","implements","instanceof","throws","throw","throws","public","private","protected","final","abstract","virtual","override","readonly","namespace","using","echo","print","println"];
    let chars: Vec<char> = text.chars().collect();
    let mut i = 0usize;
    let mut cx = x;
    let limit = x + max_w;
    // comment start detection
    let comment_prefix = if lang == "rust" || lang == "js" || lang == "javascript" || lang == "ts" || lang == "typescript" || lang == "go" || lang == "java" || lang == "c" || lang == "cpp" { "//" }
        else if lang == "python" || lang == "ruby" || lang == "sh" || lang == "bash" || lang == "shell" || lang == "yaml" || lang == "toml" { "#" }
        else { "" };
    while i < chars.len() && cx < limit {
        // comment
        if !comment_prefix.is_empty() && text[i..].starts_with(comment_prefix) {
            let rest: String = chars[i..].iter().collect();
            buf.draw_text(cx, y, &rest, st_com, limit - cx);
            break;
        }
        let c = chars[i];
        if c == '"' || c == '\'' {
            // string (not for apostrophes in comments - simplified)
            let quote = c;
            let mut j = i + 1;
            while j < chars.len() {
                if chars[j] == '\\' { j += 2; continue; }
                if chars[j] == quote { j += 1; break; }
                j += 1;
            }
            if j > chars.len() { j = chars.len(); }
            let seg: String = chars[i..j].iter().collect();
            let w = unicode_width::UnicodeWidthStr::width(seg.as_str());
            buf.draw_text(cx, y, &seg, st_str, limit - cx);
            cx += w; i = j; continue;
        }
        if c.is_alphabetic() || c == '_' {
            let mut j = i;
            let mut word = String::new();
            while j < chars.len() && (chars[j].is_alphanumeric() || chars[j] == '_' || chars[j] == '!') { word.push(chars[j]); j += 1; }
            // function call if next non-space is '('
            let mut k = j;
            while k < chars.len() && chars[k] == ' ' { k += 1; }
            let is_call = k < chars.len() && chars[k] == '(';
            let style = if KEYWORDS.contains(&word.as_str()) { st_kw }
                else if is_call { st_fn }
                else if word.chars().next().map(|ch| ch.is_uppercase()).unwrap_or(false) { st_type }
                else { st_text };
            let w = unicode_width::UnicodeWidthStr::width(word.as_str());
            buf.draw_text(cx, y, &word, style, limit - cx);
            cx += w; i = j; continue;
        }
        if c.is_ascii_digit() {
            let mut j = i;
            let mut num = String::new();
            while j < chars.len() && (chars[j].is_ascii_digit() || chars[j] == '.' || chars[j] == '_') { num.push(chars[j]); j += 1; }
            let w = unicode_width::UnicodeWidthStr::width(num.as_str());
            buf.draw_text(cx, y, &num, st_num, limit - cx);
            cx += w; i = j; continue;
        }
        // single char (punct/space)
        let seg = c.to_string();
        buf.draw_text(cx, y, &seg, st_text, limit - cx);
        cx += unicode_width::UnicodeWidthChar::width(c).unwrap_or(0);
        i += 1;
    }
}
